window.PIRTIL_OFFICIAL_DOCUMENTS = [{"id": "gunluk_maarif_ders_plani", "title": "Maarif Modeli Günlük Ders Akış Planı", "category": "Yıllık & Günlük Plan", "icon": "📖", "subtitle": "Giriş, keşfetme, derinleştirme ve süreç değerlendirme", "legalBasis": "MEB Mevzuatı ve Maarif Modeli İlkeleri", "defaultAgenda": "", "defaultDecisions": "", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "yillik_cerceve_plan_2026", "title": "Türkiye Yüzyılı Maarif Modeli Yıllık Çerçeve Planı (2026-2027)", "category": "Yıllık & Günlük Plan", "icon": "📅", "subtitle": "Tema, öğrenme çıktıları, süreç bileşenleri ve erdem-değer-eylem takvimi", "legalBasis": "Talim ve Terbiye Kurulu Başkanlığı Maarif Modeli Çerçeve Programı", "defaultAgenda": "1. 2026-2027 Eğitim-Öğretim yılı tema ve öğrenme çıktıları dağılımı.\n2. Temel beceriler, kavramsal beceriler ve eğilimlerin ders haftalarına yayılımı.\n3. Erdem-değer-eylem modeli bileşenlerinin (adalet, merhamet, vatanseverlik, çalışkanlık) tematik entegrasyonu.\n4. Süreç odaklı ölçme ve değerlendirme periyotları (biçimlendirici rubrikler, gözlem formları).\n5. Belirli gün ve haftalar ile disiplinler arası köprülerin kurulması.\n6. Özel eğitim ihtiyacı olan kaynaştırma / BEP öğrencilerine yönelik uyarlama planı.", "defaultDecisions": "1. Yıllık plan 36 çalışma haftası üzerinden hazırlanmış, her temanın gerektirdiği öğrenme çıktıları dengeli dağıtılmıştır.\n2. Bilgi ezberletme yöntemi terk edilerek; beceri temelli öğrenme çıktıları, akıl yürütme ve problem çözme etkinlikleri merkeze alınmıştır.\n3. Her ay en az bir süreç değerlendirme aracı (rubrik / e-portfolyo kontrol listesi) uygulanacaktır.\n4. Zümreler arası eşgüdüm sağlanarak temalar ortak takvimle yürütülecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "gunluk_maarif_ders_plani", "title": "Maarif Modeli Günlük / Haftalık Ders Akış Planı", "category": "Yıllık & Günlük Plan", "icon": "📖", "subtitle": "Giriş, keşfetme, derinleştirme ve süreç değerlendirme basamakları", "legalBasis": "MEB Ders Planı Hazırlama Yönergesi ve Maarif Modeli İlkeleri", "defaultAgenda": "1. Dersin Adı, Sınıf, Süre ve Hedeflenen Öğrenme Çıktıları.\n2. İlgili Beceri Alanları (Akıl Yürütme, Eleştirel Düşünme, Dijital Yetkinlik).\n3. Giriş Basamağı: Merak uyandırma, hazırbulunuşluk yoklaması ve günlük hayatla bağ kurma.\n4. Keşfetme Basamağı: Etkin katılım, problem senaryoları, grup çalışması ve sorgulama.\n5. Derinleştirme Basamağı: Kavramsal anlama, analiz, modelleme ve erdem-eylem pekiştirme.\n6. Süreç Odaklı Değerlendirme: Ders sonu çıkış kartları, anlık gözlem rubriği ve geri bildirim.\n7. Farklılaştırılmış Öğretim: Hızlı öğrenenler için zenginleştirme, destek gerekenler için basamaklama.", "defaultDecisions": "1. Derste öğretmen merkezli anlatım yerine öğrencinin keşfederek öğrendiği istasyon ve problem çözme metotları uygulanacaktır.\n2. Türkiye Yüzyılı Maarif Modeli öğrenme çıktılarına tam riayet edilecek, ders defterine ilgili çıktı kodu yazılacaktır.\n3. Ders bitiminde öğrenci öz değerlendirmeleri toplanarak gelişim portfolyosuna kaydedilecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "secmeli_ders_yillik_plan", "title": "Seçmeli Dersler Yıllık Çalışma ve Uygulama Planı", "category": "Yıllık & Günlük Plan", "icon": "💡", "subtitle": "Düşünme eğitimi, proje tasarımı, halk kültürü ve fen uygulamaları planı", "legalBasis": "MEB Seçmeli Dersler Öğretim Programı", "defaultAgenda": "1. Seçmeli dersin vizyonu, haftalık 2 saatlik ders dağılımı ve beklenen öğrenme çıktıları.\n2. Proje tabanlı öğrenme, atölye çalışmaları ve alan araştırmaları takvimi.\n3. Öğrenci ilgi ve kabiliyetlerine göre bireyselleştirilmiş üretim hedefleri.\n4. Dönem sonu ürün sergisi ve sunum değerlendirme rubrikleri.", "defaultDecisions": "1. Seçmeli ders uygulamalı olarak atölye formatında işlenecek, teorik yük asgari düzeyde tutulacaktır.\n2. Her öğrenci dönem boyunca en az bir özgün proje veya araştırma dosyası tamamlayacaktır.\n3. Öğrencilerin derse aktif katılımı ve problem çözme becerileri süreç odaklı gözlem formlarıyla puanlanacaktır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "maarif_aylik_rapor", "title": "Maarif Modeli Aylık Öğrenme Çıktısı Gerçekleşme Raporu", "category": "Yıllık & Günlük Plan", "icon": "📊", "subtitle": "Aylık hedeflenen beceri ve çıktıların gerçekleşme düzeyi ve telafi analizi", "legalBasis": "Türkiye Yüzyılı Maarif Modeli İzleme ve Değerlendirme Yönergesi", "defaultAgenda": "1. İlgili ay boyunca hedeflenen öğrenme çıktıları listesi ve işleniş saatleri.\n2. Gerçekleşen öğrenme çıktıları oranı (%) ve gecikme yaşanan konuların analizi.\n3. Süreç değerlendirme araçları (rubrik, tanılayıcı dallanmış ağaç) sonuçları.\n4. Öğrenme güçlüğü yaşayan öğrenciler için planlanan telafi ve pekiştirme adımları.\n5. Zümre ve veli işbirliğiyle hayata geçirilen destek faaliyetleri.", "defaultDecisions": "1. Ay boyunca hedeflenen 8 ana öğrenme çıktısının %92 oranında başarıyla tamamlandığı tespit edilmiştir.\n2. Soyut kavramlarda kavrama güçlüğü çeken öğrenciler için somut modeller ve dijital simülasyonlarla telafi saati ayrılmıştır.\n3. Bir sonraki ayın ilk haftasında pekiştirme etkinlikleri zümreyle koordineli olarak uygulanacaktır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "maarif_donemlik_gelisim_raporu", "title": "Maarif Modeli Dönemlik Öğrenci Bütüncül Gelişim Raporu", "category": "Yıllık & Günlük Plan", "icon": "📈", "subtitle": "Akademik beceri, erdem-değer ve sosyal gelişim dönem özeti", "legalBasis": "MEB Ölçme ve Değerlendirme Yönetmeliği", "defaultAgenda": "1. Dönem genelinde hedeflenen öğrenme çıktılarının edinilme düzeyi analizi.\n2. Erdem-değer-eylem göstergelerinin sınıf ortamındaki yansımaları.\n3. Süreç değerlendirme ve ortak yazılı sınav notlarının korelasyonu.\n4. Destekleme ve telafi programlarından istifade eden öğrenci performansı.", "defaultDecisions": "1. Şube bazında akademik beceri gelişiminin hedeflenen standardın üzerinde gerçekleştiği belirlenmiştir.\n2. Öğrencilerin takım çalışması ve akran iletişimi erdem göstergelerinde somut ilerleme kaydedilmiştir.\n3. Dönem sonu gelişim karneleri velilerle paylaşılarak ara tatil rehberlik tavsiyeleri iletilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "zumre_donem_basi", "title": "Zümre Öğretmenler Kurulu Tutanağı (Sene Başı / 1. Dönem)", "category": "Zümre & ŞÖK", "icon": "📋", "subtitle": "1. Dönem başı zümre toplantı tutanağı, yıllık plan ve ortak sınav kararları", "legalBasis": "MEB Eğitim Kurumları Yönetmeliği Madde 35", "defaultAgenda": "1. Açılış, yoklama ve kurul başkanının seçimi.\n2. Bir önceki eğitim-öğretim yılı zümre kararlarının değerlendirilmesi.\n3. Türkiye Yüzyılı Maarif Modeli çerçevesinde öğretim programı ve öğrenme çıktılarının analizi.\n4. Yıllık ve günlük planların hazırlanmasında birlikteliğin sağlanması.\n5. Süreç odaklı ölçme ve değerlendirme araçlarının (rubrik, gözlem formu, e-portfolyo) belirlenmesi.\n6. Ortak yazılı sınav tarihleri ve sınav senaryolarının belirlenmesi.\n7. Özel eğitim ihtiyacı olan kaynaştırma / BEP öğrencileri için sınav ve ders uyarlamaları.\n8. Zümreler arası işbirliği, açık kaynak ders materyalleri ve laboratuvar kullanımı.\n9. Dilek ve temenniler.", "defaultDecisions": "1. Kurul başkanlığına oy birliğiyle karar verilmiş, toplantı gündemi aynen kabul edilmiştir.\n2. Türkiye Yüzyılı Maarif Modeli esas alınarak bilgi ezberi yerine beceri ve erdem odaklı öğrenme çıktıları temele oturtulacaktır.\n3. Öğrenci başarısının değerlendirilmesinde tek bir yazılı sınav yerine; süreç değerlendirme rubrikleri, ders içi gözlem formları ve akıl yürütme ödevleri ağırlıklı olarak kullanılacaktır.\n4. 1. Ortak yazılı sınav kasım ayının ilk haftasında, 2. ortak sınav ocak ayının ilk haftasında MEB senaryolarına uygun olarak icra edilecektir.\n5. BEP uygulanan öğrenciler için basitleştirilmiş sorular ve ek sınav süresi tahsis edilecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "zumre_ikinci_donem", "title": "Zümre Öğretmenler Kurulu Tutanağı (2. Dönem Başı)", "category": "Zümre & ŞÖK", "icon": "📑", "subtitle": "1. Dönem başarı analizi, telafi planı ve 2. dönem uygulama kararları", "legalBasis": "MEB Eğitim Kurumları Yönetmeliği Madde 35", "defaultAgenda": "1. Açılış ve yoklama.\n2. 1. Dönem zümre kararlarının gerçekleşme düzeyinin değerlendirilmesi.\n3. 1. Dönem yazılı sınavlar ve süreç değerlendirme sonuçlarının şube bazlı analizi.\n4. Başarısı düşük olan öğrenciler için 2. dönem uygulanacak telafi ve destek planları.\n5. 2. Dönem ortak sınav tarihleri ve proje değerlendirme ölçeklerinin belirlenmesi.\n6. TÜBİTAK, TEKNOFEST ve bilimsel yarışmalara katılım hazırlıkları.\n7. Dilek ve temenniler.", "defaultDecisions": "1. 1. Dönem zümre hedeflerinin %91 oranında yerine getirildiği memnuniyetle tespit edilmiştir.\n2. Not ortalaması 60 puanın altında kalan öğrenme çıktıları için ders başlangıçlarında 10'ar dakikalık mikro telafi etkinlikleri yapılacaktır.\n3. 2. Dönem 1. sınav nisan başında, 2. sınav haziran başında uygulanacaktır.\n4. Proje ve performans ödevlerinin nisan ayının son haftasında rubrikle değerlendirilip e-Okul'a girilmesine karar verilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "zumre_sene_sonu", "title": "Zümre Öğretmenler Kurulu Tutanağı (Sene Sonu)", "category": "Zümre & ŞÖK", "icon": "📊", "subtitle": "Yıllık öğrenme çıktıları gerçekleşme oranı ve genel başarı değerlendirmesi", "legalBasis": "MEB Eğitim Kurumları Yönetmeliği Madde 35", "defaultAgenda": "1. Açılış ve yoklama.\n2. Yıl boyunca hedeflenen öğretim programı öğrenme çıktılarının gerçekleşme analizi.\n3. Şubelerin yıl sonu ders başarı ortalamaları ve başarı grafiği.\n4. Süreç odaklı değerlendirme araçlarının verimliliği ve öğrenci gelişimine etkisi.\n5. Yıl boyunca uygulanan telafi ve destek eğitimlerinin sonuçları.\n6. Gelecek eğitim-öğretim yılı için alınması tavsiye edilen pedagojik tedbirler.\n7. Kapanış.", "defaultDecisions": "1. Müfredattaki öğrenme çıktılarının %96 oranında başarıyla tamamlandığı kayıt altına alınmıştır.\n2. Süreç odaklı değerlendirme yaklaşımı sayesinde öğrencilerin derse ilgisinde ve akıl yürütme becerilerinde kayda değer artış sağlanmıştır.\n3. Laboratuvar ve somut materyal kullanımının başarıyı doğrudan artırdığı görülmüş, gelecek yıl bu sürenin artırılması kararlaştırılmıştır.\n4. Zümre yıllık çalışma dosyası eksiksiz tanzim edilerek okul idaresine teslim edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "ilce_zumre_tutanagi", "title": "İl / İlçe Zümre Başkanları Kurulu Karar Tutanağı", "category": "Zümre & ŞÖK", "icon": "🏛️", "subtitle": "İlçe genelinde eğitim standardizasyonu ve ortak yazılı sınav koordinasyonu", "legalBasis": "MEB Eğitim Kurumları Yönetmeliği Madde 36", "defaultAgenda": "1. Açılış, yoklama ve ilçe zümre başkanı seçimi.\n2. İlçe genelinde akademik başarının ve öğrenme çıktılarının okul türlerine göre incelenmesi.\n3. İlçe genelinde uygulanacak ortak yazılı sınavların konu soru dağılım tablolarının (senaryolar) kesinleştirilmesi.\n4. İlçedeki okullar arasında öğretmen değişimi, ortak materyal ve soru bankası havuzu kurulması.\n5. Dezavantajlı bölgelerdeki okullara yönelik destekleme stratejileri.", "defaultDecisions": "1. İlçe genelinde birliktelik sağlamak üzere MEB 1. ve 2. senaryoları ortak sınav kılavuzu olarak benimsenmiştir.\n2. Ortak dijital materyal ve rubrik havuzu kurularak tüm ilçe branş öğretmenlerinin erişimine açılmıştır.\n3. İlçe zümre tavsiye kararları İlçe Millî Eğitim Müdürlüğü onayına sunulmuştur.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "sok_1_donem", "title": "1. Dönem Şube Öğretmenler Kurulu (ŞÖK) Tutanağı & Kararları", "category": "Zümre & ŞÖK", "icon": "👥", "subtitle": "Şube bazlı akademik başarı, disiplin, kaynaştırma ve rehberlik kurul tutanağı", "legalBasis": "MEB Ortaöğretim / İlköğretim Kurumları Yönetmeliği Madde 36", "defaultAgenda": "1. Açılış ve yoklama.\n2. Şubenin genel başarı durumunun tüm branşlar bazında ayrı ayrı değerlendirilmesi.\n3. Sürekli devamsızlık riski taşıyan öğrencilerin durumları ve alınan tedbirler.\n4. Şubedeki kaynaştırma (BEP) öğrencilerinin gelişimi, ders ve sınav uyarlamaları.\n5. Ailevi sorunları veya maddi dezavantajı bulunan öğrencilere yönelik okul rehberlik desteği.\n6. Sınıf iklimi, akran zorbalığı riski ve disiplin durumlarının müzakeresi.\n7. Şubenin akademik ve ahlaki gelişimini pekiştirecek ortak kurul kararlarının alınması.", "defaultDecisions": "1. Şubenin genel akademik başarısının yüksek olduğu, ders dinleme ve sınıf kurallarına uyum düzeyinin olumlu seyrettiği saptanmıştır.\n2. Devamsızlık sınırına yaklaşan öğrencilerin velileriyle sınıf rehber öğretmeni tarafından ivedilikle birebir görüşme yapılması kararlaştırılmıştır.\n3. Derse odaklanma sorunu yaşayan öğrencilere sınıf içerisinde ön sıralarda yer verilmesi ve derste söz hakkı verilerek motivasyonlarının pekiştirilmesi kararlaştırılmıştır.\n4. BEP planı olan öğrencilerin destek eğitim odasından haftalık 4 saat düzenli faydalanmaları sağlanacaktır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "sok_2_donem", "title": "2. Dönem Şube Öğretmenler Kurulu (ŞÖK) Tutanağı & Kararları", "category": "Zümre & ŞÖK", "icon": "🤝", "subtitle": "1. Dönem kararlarının takibi, riskli öğrencilere destek ve sınıf geçme durumları", "legalBasis": "MEB Eğitim Kurumları Yönetmeliği Madde 36", "defaultAgenda": "1. Açılış ve yoklama.\n2. 1. Dönem ŞÖK kararlarının öğrenci bazlı sonuçlarının incelenmesi.\n3. Başarısızlık veya sınıf tekrarı riski olan öğrencilerin ders öğretmenlerince değerlendirilmesi.\n4. Rehberlik servisiyle yürütülen çalışmaların öğrenci davranışlarına yansıması.\n5. Bir üst sınıfa hazırlık ve LGS/YKS sınav rehberliği süreçleri.", "defaultDecisions": "1. 1. Dönem hakkında tedbir kararı alınan 3 öğrenciden 2'sinin not ortalamalarını yükselttiği ve devamsızlıklarını sonlandırdığı görülmüştür.\n2. Destek ihtiyacı devam eden öğrenci için sınıf rehber öğretmeni, veli ve okul rehberlik servisi üçgeninde haftalık takip kartı oluşturulacaktır.\n3. Ders dışı etüt ve soru çözüm saatlerine ilgili öğrencilerin katılımı teşvik edilecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "sok_bireysel_tedbir", "title": "ŞÖK Bireysel Öğrenci Destek ve Tedbir Takip Formu", "category": "Zümre & ŞÖK", "icon": "🎯", "subtitle": "Akademik ve davranışsal destek kararı alınan öğrenci takip çizelgesi", "legalBasis": "MEB Rehberlik ve Psikolojik Danışma Hizmetleri Yönergesi", "defaultAgenda": "1. ŞÖK kurulunda hakkında özel tedbir kararı alınan öğrencinin kimlik ve şube bilgileri.\n2. Ders öğretmenlerinin öğrenciye ilişkin somut gözlemleri ve eksik kalan beceriler.\n3. Öğrenci için belirlenen hedef davranışlar ve akademik çalışma takvimi.\n4. Veli görüşme periyotları ve evdeki çalışma ortamının desteklenmesi.\n5. Ara değerlendirme tarihleri ve sonuç göstergeleri.", "defaultDecisions": "1. Öğrencinin derse katılımını teşvik etmek amacıyla ön sıralara oturtulması ve ders içi küçük sorumluluklar verilmesi kararlaştırılmıştır.\n2. Veli ile 15 günde bir periyodik durum değerlendirme toplantısı yapılmasına karar verilmiştir.\n3. Rehberlik servisinin hazırladığı haftalık çalışma programı tüm branş öğretmenlerince ortak takip edilecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "dilimizin_zenginlikleri_yillik_plan", "title": "Dilimizin Zenginlikleri Projesi Yıllık Eylem Planı (2026-2027)", "category": "Dilimizin Zenginlikleri", "icon": "📚", "subtitle": "Klasik eserler, sözlük özgürlüktür, Dîvânu Lugâti't-Türk ve deyimler planı", "legalBasis": "MEB Ortaöğretim Genel Müdürlüğü Dilimizin Zenginlikleri Projesi Kılavuzu", "defaultAgenda": "1. Dilimizin Zenginlikleri Projesi okul yürütme komisyonunun teşkili.\n2. Ekim Ayı: Bilen Tanır & Klasik Eser Okumaları etkinliği.\n3. Kasım Ayı: 'Sözlük Özgürlüktür' temalı özgün sözlük tasarımı yarışması.\n4. Aralık Ayı: Dîvânu Lugâti't-Türk okumaları ve kelime avı panosu.\n5. Ocak Ayı: Deyimler ve Atasözleri Okumaları, canlandırma ve resimleme sergisi.\n6. Şubat - Mart: Safahat ve Kutadgu Bilig okumaları, beyit ezberleme etkinliği.\n7. Nisan - Mayıs: Yunus Emre şiirleri dinletisi ve türkülerle dilimiz şöleni.\n8. Yıl sonu proje sergisi ve raporlaştırma.", "defaultDecisions": "1. Okul komisyonu kurulmuş, her ayın ilk haftasında sınıf panolarında tematik kelime köşesi açılması kararlaştırılmıştır.\n2. Türkçe / Edebiyat derslerinde haftada 1 ders saati projenin belirlediği klasik eser okumalarına tahsis edilecektir.\n3. Öğrencilerin tasarladığı sözlükler okul kütüphanesinde sergilenecek ve dereceye giren öğrenciler ödüllendirilecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "dilimizin_zenginlikleri_aylik_rapor", "title": "Dilimizin Zenginlikleri Aylık Etkinlik Uygulama & Pano Tutanağı", "category": "Dilimizin Zenginlikleri", "icon": "🎨", "subtitle": "Aylık tematik yarışmalar, pano sergisi ve öğrenci katılım tutanağı", "legalBasis": "Dilimizin Zenginlikleri Projesi Uygulama Esasları", "defaultAgenda": "1. İlgili ayın proje teması ve okul genelinde icra edilen faaliyetler.\n2. Sınıflar bazında hazırlanan tematik panoların incelenmesi.\n3. Ayın yarışmasına (Sözlük Tasarımı / Cümle Kurma / Resimleme) katılan öğrenci sayısı.\n4. Komisyon tarafından dereceye layık görülen öğrenci ürünleri.\n5. İlçe MEM proje koordinatörlüğüne iletilecek görsel ve raporların tanzimi.", "defaultDecisions": "1. Ayın faaliyeti tüm sınıfların katılımıyla eksiksiz uygulanmış, okul panosu güncellenmiştir.\n2. Yarışmada ilk üç dereceye giren öğrencilere katılım ve başarı belgesi takdim edilmiştir.\n3. Etkinlik fotoğrafları ve sonuç raporu MEBBİS proje modülüne yüklenmek üzere idareye arz edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "veli_toplantisi_1_donem", "title": "1. Dönem Sınıf Veli Toplantısı Tutanağı & Gündem Kararları", "category": "Veli Toplantısı", "icon": "👨‍👩‍👧", "subtitle": "Maarif Modeli tanıtımı, süreç odaklı değerlendirme ve veli imza kararları", "legalBasis": "MEB Okul-Aile Birliği Yönetmeliği ve Eğitim Kurumları Yönetmeliği", "defaultAgenda": "1. Açılış, saygı duruşu ve İstiklâl Marşı.\n2. Türkiye Yüzyılı Maarif Modeli'nin velilere tanıtılması ve süreç değerlendirme yaklaşımı.\n3. Öğrencilerin ders çalışma alışkanlıkları, kitap okuma saati ve dijital ekran sınırlaması.\n4. Devamsızlık, kılık-kıyafet kuralları, beslenme ve okul giriş-çıkış saatleri.\n5. Sınıf veli temsilcisi ve yedek üyesinin seçimi.\n6. Bireysel veli görüşmeleri ve dilek-temenniler.", "defaultDecisions": "1. Velilere her gün evde en az 30 dakika ailece kitap okuma saati uygulanması tavsiye edilmiştir.\n2. Ders saatlerinde cep telefonu kullanımının yasak olduğu kuralı velilerle teyit edilmiştir.\n3. Sınıf veli temsilcisi oy birliğiyle seçilmiş, sınıf iletişim panosu belirlenmiştir.\n4. Öğrenci durumları hakkında e-Okul sistemi üzerinden düzenli takip yapılması kararlaştırılmıştır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "veli_toplantisi_2_donem", "title": "2. Dönem Sınıf Veli Toplantısı Tutanağı & Başarı Analizi", "category": "Veli Toplantısı", "icon": "📊", "subtitle": "1. Dönem karne değerlendirmesi, ikinci dönem hedefleri ve telafi kararları", "legalBasis": "MEB Eğitim Kurumları Yönetmeliği", "defaultAgenda": "1. Açılış ve yoklama.\n2. 1. Dönem karne notlarının ve ders başarı grafiklerinin değerlendirilmesi.\n3. Süreç değerlendirme rubriklerinin 2. dönemdeki işleyişi.\n4. Bahar dönemi motivasyonu, zararlı alışkanlıklardan korunma ve akran ilişkileri.\n5. Üst öğrenim kurumları ve merkezi sınav hazırlıkları hakkında veli bilgilendirmesi.", "defaultDecisions": "1. 1. Dönem akademik ortalamasının sınıf düzeyinde memnuniyet verici olduğu saptanmıştır.\n2. Zayıf notu bulunan öğrencilerin 2. dönem telafi çalışmalarına aktif katılımı için veli desteği taahhüt edilmiştir.\n3. Öğrencilerin düzenli uyku ve dengeli beslenme alışkanlıklarının korunması kararlaştırılmıştır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "veli_imza_sirkusu", "title": "Veli Toplantısı İmzalı Katılım Çizelgesi & İletişim Formu", "category": "Veli Toplantısı", "icon": "✍️", "subtitle": "Toplantıya iştirak eden velilerin imza, telefon ve iletişim listesi", "legalBasis": "MEB Resmi Yazışma Kuralları", "defaultAgenda": "1. Toplantı Tarihi, Saati ve Yeri.\n2. Şube Mevcudu ve Toplantıya Katılan Asil Veli Sayısı.\n3. Mazeret Bildirerek Katılamayan Velilerin Listesi.\n4. İletişim Numaraları ve Acil Durum İrtibat Bilgileri Güncellemesi.", "defaultDecisions": "1. Sınıf mevcudunun %88'i toplantıya bizzat katılarak imza sirküsünü imzalamıştır.\n2. Katılamayan veliler ile sınıf rehber öğretmeni tarafından birebir randevu planlanmıştır.\n3. İmzalı tutanak okul idaresine teslim edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "bireysel_veli_gorusme", "title": "Bireysel Veli Görüşme & Rehberlik Bilgilendirme Formu", "category": "Veli Toplantısı", "icon": "🗣️", "subtitle": "Öğrenci odaklı özel veli randevusu, gözlem ve mutabakat tutanağı", "legalBasis": "MEB Rehberlik ve Psikolojik Danışma Hizmetleri Yönetmeliği", "defaultAgenda": "1. Görüşme yapılan öğrencinin adı, soyadı, sınıfı ve okul numarası.\n2. Görüşme talebinin kaynağı (Öğretmen Daveti / Veli Talebi).\n3. Görüşme konusu (Akademik Başarı / Davranış / Uyum / Devamsızlık).\n4. Öğretmenin tespit ve önerileri.\n5. Velinin beyanı ve evdeki gözlemleri.\n6. Kararlaştırılan ortak eylem adımları.", "defaultDecisions": "1. Öğrencinin ders içi dikkat süresini artırmak adına günlük ders çalışma planı hazırlandı.\n2. Veli tarafından tablet/telefon süresinin hafta içi sınırlandırılması kabul edildi.\n3. 3 hafta sonra ara değerlendirme amacıyla telefonla geri bildirim yapılmasına karar verildi.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "belirli_gunler_yillik_takvim", "title": "Belirli Gün ve Haftalar Yıllık Kutlama / Anma Programı Takvimi", "category": "Belirli Günler & Haftalar", "icon": "🗓️", "subtitle": "Yıl boyunca icra edilecek milli, kültürel ve sosyal anma/kutlama görev dağılımı", "legalBasis": "MEB Sosyal Etkinlikler Yönetmeliği Ek-1 Tablosu", "defaultAgenda": "1. 2026-2027 Eğitim-Öğretim yılı kutlanacak Belirli Gün ve Haftalar listesi.\n2. Tören ve kutlama komisyonu koordinatör öğretmen görev dağılımı.\n3. Salon, okul bahçesi, ses sistemi ve pano hazırlık ekipleri.\n4. Bütçe, davetiye ve protokol planlaması.", "defaultDecisions": "1. İlköğretim Haftası, Cumhuriyet Bayramı, 10 Kasım, Öğretmenler Günü, 12 Mart, 18 Mart ve 23 Nisan tören sorumluları belirlenmiştir.\n2. Her törenden en az 10 gün önce program akışı okul müdürlüğüne sunularak onay alınacaktır.\n3. Törenlerde milli ve manevi değerlerimizi pekiştirici özgün öğrenci koroları ve oratoryolar hazırlanacaktır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "cumhuriyet_bayrami_29_ekim", "title": "29 Ekim Cumhuriyet Bayramı Kutlama Programı & Konuşma Metni", "category": "Belirli Günler & Haftalar", "icon": "🇹🇷", "subtitle": "Tören akışı, öğretmen açılış konuşması, şiirler ve koro programı", "legalBasis": "Ulusal ve Resmi Bayramlar ile Mahalli Kurtuluş Günleri Yönetmeliği", "defaultAgenda": "1. Saygı duruşu ve İstiklâl Marşı'nın okunması.\n2. Günün anlam ve önemini belirten öğretmen açış konuşması.\n3. Öğrenci temsilcisi konuşması ve cumhuriyet temalı şiirlerin okunması.\n4. 'Cumhuriyetin Faziletleri ve Maarif' konulu öğrenci oratoryosu.\n5. Okul korosu marş dinletisi ve ödül töreni.", "defaultDecisions": "1. 29 Ekim sabahı tüm öğretmen ve öğrencilerin eksiksiz katılımıyla tören gerçekleştirilecektir.\n2. Hafta boyunca okul koridorlarında Cumhuriyet temalı resim ve şiir sergisi açık kalacaktır.\n3. İlçe düzeyinde düzenlenen yarışmalarda dereceye giren öğrencilere ödülleri takdim edilecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "ataturk_anma_10_kasim", "title": "10 Kasım Atatürk'ü Anma Töreni Programı & Oratoryo Dosyası", "category": "Belirli Günler & Haftalar", "icon": "🕯️", "subtitle": "09:05 Saygı duruşu, anma metinleri, oratoryo ve anma tutanağı", "legalBasis": "Atatürk Haftası Anma Genelgesi", "defaultAgenda": "1. Saat 09:05'te iki dakikalık saygı duruşu ve bayrakların yarıya indirilmesi.\n2. İstiklâl Marşı'nın okunması.\n3. Atatürk'ün askeri dehası, devlet adamlığı ve bilime verdiği önemi içeren anma konuşması.\n4. 'Atatürk ve Maarif İnkılabı' oratoryo sunumu.\n5. Sevdiği şarkılar ve şiir dinletisiyle törenin hitama ermesi.", "defaultDecisions": "1. Siren ve ses sistemi kontrolleri bir gün önceden teknik komisyonca yapılmıştır.\n2. Anma töreninin ciddiyet ve hürmet ikliminde gerçekleşmesi sağlanmıştır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "ogretmenler_gunu_24_kasim", "title": "24 Kasım Öğretmenler Günü Kutlama Programı Tutanağı", "category": "Belirli Günler & Haftalar", "icon": "💐", "subtitle": "Öğretmenler günü salon programı, emekli öğretmenlere vefa ve kutlama akışı", "legalBasis": "Öğretmenler Günü Kutlama Yönergesi", "defaultAgenda": "1. Kutlama kurulu görev dağılımı ve salon hazırlıkları.\n2. Açılış konuşması ve Başöğretmen Gazi Mustafa Kemal Atatürk'ün yâd edilmesi.\n3. Mesleğe yeni başlayan öğretmenler adına konuşma ve yemin merasimi.\n4. Emekli öğretmenlere hizmet şeref belgesi ve plaket takdimi.\n5. Öğrencilerden öğretmenlere mektup ve müzik dinletisi.", "defaultDecisions": "1. Program komisyonu tüm hazırlıkları tamamlayarak provayı icra etmiştir.\n2. Okul-Aile Birliği desteğiyle öğretmenler odasında kutlama kokteyli tertip edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "istiklal_marsi_12_mart", "title": "12 Mart İstiklâl Marşı'nın Kabulü ve M. Âkif Ersoy'u Anma Programı", "category": "Belirli Günler & Haftalar", "icon": "📜", "subtitle": "İstiklâl Marşı güzel okuma yarışması, Âkif'in ideali ve anma metinleri", "legalBasis": "İstiklâl Marşı'nın Kabul Edildiği Günü ve Mehmet Âkif Ersoy'u Anma Günü Yönetmeliği", "defaultAgenda": "1. Saygı duruşu ve İstiklâl Marşı.\n2. Mehmet Âkif Ersoy'un ahlakı, sanatı ve Millî Mücadele'deki rolü.\n3. İstiklâl Marşı'nı ezbere güzel okuma yarışması finalistlerinin sunumu.\n4. 'Asım'ın Nesli' temalı tiyatral oratoryo.\n5. Kapanış ve derece alan öğrencilerin ödüllendirilmesi.", "defaultDecisions": "1. Mehmet Âkif'in Safahat eseri ve bağımsızlık şuuru tüm sınıflarda işlenmiştir.\n2. Yarışma jürisi şeffaf puanlama ile okul birincisini ilan etmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "canakkale_18_mart", "title": "18 Mart Çanakkale Zaferi ve Şehitleri Anma Programı", "category": "Belirli Günler & Haftalar", "icon": "🎖️", "subtitle": "Kahramanlık destanı anma konuşması, türkü dinletisi ve anma tutanağı", "legalBasis": "Şehitler Günü ve Gaziler Günü Genelgesi", "defaultAgenda": "1. Aziz şehitlerimiz anısına saygı duruşu ve İstiklâl Marşı.\n2. Çanakkale Deniz Zaferi'nin tarihi ve manevi önemini belirten konuşma.\n3. Seyit Onbaşı ve 57. Alay canlandırma sahnesi.\n4. Çanakkale türküleri koro icrası.\n5. Şehitlerimize dua ve kapanış.", "defaultDecisions": "1. Programın vatan sevgisi ve fedakarlık erdemlerini pekiştirecek nitelikte icrası sağlanmıştır.\n2. Okul panosunda Çanakkale cephesi tarihi fotoğrafları sergilenmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "cocuk_bayrami_23_nisan", "title": "23 Nisan Ulusal Egemenlik ve Çocuk Bayramı Kutlama Programı", "category": "Belirli Günler & Haftalar", "icon": "🎈", "subtitle": "Okul bahçesi çocuk şenliği, geleneksel oyunlar, halk oyunları ve tören planı", "legalBasis": "Ulusal Bayramlar Genelgesi", "defaultAgenda": "1. Saygı duruşu, İstiklâl Marşı ve günün anlam konuşması.\n2. Geleneksel çocuk oyunları (Halat çekme, çuval yarışı, mendil kapmaca).\n3. Şiirler, korolar ve folklor gösterileri.\n4. Sınıflar arası dostluk müsabakaları ve resim sergisi.\n5. Bayram şenliği kapanışı.", "defaultDecisions": "1. Okul bahçesi bayraklarla süslenmiş, tüm öğrencilerin bayram neşesini yaşaması temin edilmiştir.\n2. Ses düzeni ve emniyet tedbirleri eksiksiz alınmıştır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "sinif_rehberlik_yillik_plan", "title": "Sınıf Rehberlik Yıllık Çalışma Planı (MEB ORGGM Uyumlu)", "category": "Sınıf Rehberlik", "icon": "🌱", "subtitle": "36 Haftalık MEB sınıf rehberlik programı öğrenme çıktıları ve etkinlikleri", "legalBasis": "MEB Özel Eğitim ve Rehberlik Hizmetleri Genel Müdürlüğü Sınıf Rehberlik Programı", "defaultAgenda": "1. Sınıf RİBA (Rehberlik İhtiyaçları Belirleme Anketi) uygulama takvimi.\n2. Okula uyum, sınıf kuralları ve aidiyet duygusunun pekiştirilmesi.\n3. Akran zorbalığını önleme, empati ve çatışma çözme becerileri.\n4. Verimli ders çalışma teknikleri, plan yapma ve zaman yönetimi rehberliği.\n5. Sağlıklı yaşam, dijital bağımlılıkla mücadele ve kişisel sınırlar.\n6. Mesleki ilgi ve yeteneklerin keşfi, üst öğretim kurumlarının tanıtımı.", "defaultDecisions": "1. Haftalık sınıf rehberlik saati etkinlikleri planlanan takvim doğrultusunda eksiksiz icra edilecektir.\n2. Risk grubunda görülen öğrenciler okul psikolojik danışmanıyla koordine edilerek bireysel görüşmeye yönlendirilecektir.\n3. Sınıf içi etkileşimi artırıcı etkinlikler düzenli olarak sınıf panosuna taşınacaktır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "ogrenci_tanima_fisi", "title": "Öğrenci Tanıma Fişi & Bireysel Gözlem Dosyası", "category": "Sınıf Rehberlik", "icon": "🗂️", "subtitle": "Aile, sağlık, ilgi, yetenek ve akademik geçmiş tanıma arşivi", "legalBasis": "MEB Rehberlik Hizmetleri Yönergesi", "defaultAgenda": "1. Öğrencinin Kimlik, İkamet ve İletişim Bilgileri.\n2. Aile Yapısı (Anne-baba sağ/öz/birlikte, kardeş sayısı, aile meslek durumu).\n3. Öğrencinin Kronik Rahatsızlıkları, Düzenli İlaç Kullanımı veya Alerjileri.\n4. Öğrencinin İlgi Alanları, Sanat ve Spor Kabiliyetleri, Hobileri.\n5. Öğrenme Stili (Görsel / İşitsel / Kinestetik) ve Çalışma Alışkanlıkları.", "defaultDecisions": "1. Elde edilen tüm veriler Kişisel Verilerin Korunması Kanunu (KVKK) ve etik rehberlik ilkelerine uygun olarak gizli tutulacaktır.\n2. Kronik sağlık sorunu olan öğrenciler nöbetçi öğretmenler ve okul idaresi ile gizlilikle paylaşılmıştır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "sinif_oturma_plani", "title": "Sınıf Oturma Planı ve Sosyal Dinamik Şeması", "category": "Sınıf Rehberlik", "icon": "🪑", "subtitle": "Boy, görme, işitme, kaynaştırma ve pedagojik eşleştirme yerleşim şeması", "legalBasis": "Sınıf İçi Yönetim ve Pedagojik Esaslar", "defaultAgenda": "1. Öğrencilerin fiziksel özellikleri (boy, görme/işitme cihazı kullanımı).\n2. Kaynaştırma (BEP) öğrencilerinin tahtaya ve öğretmene yakın konumu.\n3. Dikkat dağınıklığı yaşayan öğrencilerin pencere/kapı uzaklık ayarı.\n4. Akran desteği için olumlu modellerle çalışma gruplarının teşkili.\n5. Dönemlik oturma planı rotasyon periyodu.", "defaultDecisions": "1. Oturma düzeni pedagojik ihtiyaçlar doğrultusunda tanzim edilmiş, tahtayı görmekte zorlanan öğrenciler ön sıralara alınmıştır.\n2. Oturma planı her ay dengeli biçimde hafif revize edilerek sınıf içi kapsayıcılık korunacaktır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "sosyometri_raporu", "title": "Sosyometri Uygulama ve Akran İlişkileri Analiz Raporu", "category": "Sınıf Rehberlik", "icon": "🕸️", "subtitle": "Sınıf içi liderler, klikler, izole öğrenciler ve sosyal mesafe analizi", "legalBasis": "MEB Rehberlik Teknikleri Kılavuzu", "defaultAgenda": "1. Sosyometri testinin uygulanış tarihi ve katılan öğrenci sayısı.\n2. Sınıfın en çok tercih edilen (lider) öğrencileri.\n3. Tercih edilmeyen veya dışlanma riski taşıyan (izole) öğrenciler.\n4. Sınıf içerisindeki kapalı klikler ve kutuplaşmalar.\n5. Sınıf iklimini iyileştirecek pedagojik müdahale adımları.", "defaultDecisions": "1. Yalnız kalan öğrencilerin grup çalışmalarında etkin rol alması için ortak sorumluluklar verilmiştir.\n2. Akran kaynaşmasını artıracak sosyal projeler ve eğitici oyunlar sınıf içi saatlere dahil edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "riba_sinif_raporu", "title": "RİBA (Rehberlik İhtiyaçları Belirleme) Sınıf Değerlendirme Raporu", "category": "Sınıf Rehberlik", "icon": "📑", "subtitle": "Öğrenci, veli ve öğretmen anket sonuçlarının sınıf bazlı analizi", "legalBasis": "MEB ORGGM Rehberlik İhtiyaçları Belirleme Yönergesi", "defaultAgenda": "1. RİBA anketine katılan öğrenci ve veli oranı.\n2. Sınıf düzeyinde öne çıkan en yüksek rehberlik ihtiyaç alanları.\n3. Akademik, kariyer ve sosyal-duygusal gelişim alanlarındaki öncelikler.\n4. Okul Rehberlik ve Psikolojik Danışma Servisine sunulan sınıf eylem önerileri.", "defaultDecisions": "1. Sınıfın en temel ihtiyacının 'Sınav Kaygısı ve Zaman Yönetimi' olduğu tespit edilmiştir.\n2. Rehberlik servisinden bu konularda sınıfa yönelik seminer ve atölye çalışması talep edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "sinif_rehberlik_yil_sonu", "title": "Sınıf Rehberlik Yıl Sonu Faaliyet ve Sonuç Raporu", "category": "Sınıf Rehberlik", "icon": "🏁", "subtitle": "Yıllık rehberlik hizmetleri icra oranı, yönlendirmeler ve veli görüşmeleri", "legalBasis": "MEB Rehberlik Hizmetleri Yönetmeliği", "defaultAgenda": "1. Sınıf rehberlik planındaki 36 haftalık etkinliklerin tamamlanma düzeyi.\n2. Rehberlik servisine yönlendirilen öğrenci sayısı ve takip süreçleri.\n3. Yıl boyunca yapılan veli görüşmeleri sayısı ve ulaşılan neticeler.\n4. Gelecek öğretim yılında aynı şubeyi okutacak öğretmenlere pedagojik tavsiyeler.", "defaultDecisions": "1. Yıllık sınıf rehberlik programı %97 oranında başarıyla tamamlanmıştır.\n2. Sınıf rehberlik dosyası, öğrenci gözlem fişleri ve yıl sonu raporu okul idaresine teslim edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "sosyal_kulup_yillik_plan", "title": "Sosyal Kulüp Yıllık Çalışma Planı ve Görev Dağılımı", "category": "Sosyal Kulüp & Etkinlik", "icon": "🏆", "subtitle": "Kulüp danışman öğretmeni, öğrenci listesi ve aylık toplum hizmeti takvimi", "legalBasis": "MEB Sosyal Etkinlikler Yönetmeliği Madde 11", "defaultAgenda": "1. Kulübün adı, danışman öğretmeni ve üye öğrenci listesi.\n2. Kulübün genel amaçları ve öğrencilere sağlayacağı sosyal beceriler.\n3. Belirli gün ve haftalara yönelik kulüp sorumlulukları ve pano hazırlıkları.\n4. Yıllık planlanan toplum hizmeti çalışması (kitap toplama, çevre, fidan dikimi).\n5. Aylık toplanma takvimi ve bülten yayın planı.", "defaultDecisions": "1. Kulüp yıllık çalışma planı yönetmeliğe uygun olarak tanzim edilmiş ve okul müdürlüğünce onaylanmıştır.\n2. Kulüp toplantıları her ayın ilk çarşamba günü son ders saati icra edilecektir.\n3. Her ay okul ana panosunda kulüp çalışmaları sergilenecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "sosyal_kulup_secim_tutanagi", "title": "Sosyal Kulüp Yönetim Kurulu Seçim Tutanağı", "category": "Sosyal Kulüp & Etkinlik", "icon": "🗳️", "subtitle": "Kulüp başkanı, başkan yardımcısı, sayman ve denetçi seçim tutanağı", "legalBasis": "MEB Sosyal Etkinlikler Yönetmeliği", "defaultAgenda": "1. Açılış, yoklama ve kulüp amaçlarının üye öğrencilere aktarılması.\n2. Kulüp yönetim ve denetleme kurullarına adayların belirlenmesi.\n3. Gizli oy, açık tasnif usulüyle oy verme işleminin yürütülmesi.\n4. Oyların sayımı ve kulüp temsilcilerinin ilanı.", "defaultDecisions": "1. Kulüp başkanlığına en yüksek oyu alan öğrenci seçilmiş, yönetim kurulu asil ve yedek üyeleri belirlenmiştir.\n2. Seçim tutanağı kulüp karar defterine işlenerek danışman öğretmen ve öğrencilerce imzalanmıştır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "toplum_hizmeti_plani", "title": "Toplum Hizmeti Yıllık Çalışma Planı & Veli Muvafakatnamesi", "category": "Sosyal Kulüp & Etkinlik", "icon": "🤝", "subtitle": "Gönüllülük, çevre bilinci, kardeş okul ve sosyal sorumluluk projesi", "legalBasis": "MEB Sosyal Etkinlikler Yönetmeliği Toplum Hizmeti Esasları", "defaultAgenda": "1. Toplum hizmeti çalışmasının adı, teması ve gerekçesi.\n2. Projede görev alan öğrenci grubu ve rehber danışman öğretmenler.\n3. İlgili kurum ve sivil toplum kuruluşlarıyla (Kızılay, Tema vb.) işbirliği.\n4. Velilerden alınacak ıslak imzalı muvafakat belgeleri.\n5. Faaliyet takvimi ve sonuç raporlaştırması.", "defaultDecisions": "1. Toplum hizmeti çalışması 'Temiz Çevre, Yaşanabilir Okul' temasıyla uygulanacaktır.\n2. Projeye iştirak eden tüm öğrencilerin velilerinden izin dilekçesi eksiksiz toplanmıştır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "sosyal_kulup_yil_sonu", "title": "Sosyal Kulüp Yıl Sonu Faaliyet ve Değerlendirme Raporu", "category": "Sosyal Kulüp & Etkinlik", "icon": "📜", "subtitle": "İcra edilen etkinlikler, okul panoları ve e-Okul veri giriş beyanı", "legalBasis": "MEB Sosyal Etkinlikler Yönetmeliği", "defaultAgenda": "1. Yıl boyunca planlanan faaliyetlerin gerçekleşme oranı.\n2. Öğrencilerin sosyal sorumluluk, liderlik ve iletişim becerilerindeki erdem çıktıları.\n3. Gerçekleştirilen toplum hizmeti projesinin sonuçları.\n4. e-Okul Sosyal Etkinlik Modülüne veri girişlerinin tamamlanma durumu.", "defaultDecisions": "1. Kulüp yıllık çalışma programı %100 başarıyla tamamlanmıştır.\n2. Kulüp üyesi tüm öğrencilerin etkinlik belgeleri e-Okul Sosyal Etkinlik Modülü'ne kaydedilmiştir.\n3. Kulüp evrak dosyası ve karar defteri okul idaresine teslim edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "eokul_sosyal_etkinlik_cizelgesi", "title": "MEB e-Okul Sosyal Etkinlik Modülü Veri Giriş Çizelgesi", "category": "Sosyal Kulüp & Etkinlik", "icon": "💻", "subtitle": "Sanatsal, sportif, kültürel ve bilimsel faaliyetlerin öğrenci bazlı çizelgesi", "legalBasis": "MEB e-Okul Sosyal Etkinlik Yönergesi", "defaultAgenda": "1. Etkinlik Kategorisi (Merkezi / Mahalli / Okul İçi).\n2. Etkinlik Alanı (Bilimsel / Kültürel / Sanatsal / Sportif / Toplum Hizmeti).\n3. Öğrencinin Rolü (Katılımcı / Görevli / Derece Alan).\n4. Belge Türü (Katılım Belgesi / Başarı Belgesi / Teşekkür Belgesi).", "defaultDecisions": "1. Tüm öğrencilerin sosyal etkinlikleri belgelendirilmiş ve e-Okul sistemine onaylanmak üzere yüklenmiştir.\n2. Çizelge çıktısı okul idaresine imza karşılığı sunulmuştur.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "bep_bireysel_egitim_plani", "title": "RAM Uyumlu Bireyselleştirilmiş Eğitim Programı (BEP) Planı", "category": "BEP & Özel Eğitim", "icon": "🎯", "subtitle": "Özel eğitim ihtiyacı olan öğrenciler için uzun ve kısa dönemli çıktılar planı", "legalBasis": "MEB Özel Eğitim Hizmetleri Yönetmeliği Madde 62", "defaultAgenda": "1. Öğrencinin eğitsel tanısı, kaba değerlendirmesi ve mevcut performans düzeyi.\n2. Uzun Dönemli Amaçlar (UDA) ve Kısa Dönemli Amaçlar (KDA) tablosu.\n3. Ders içi kullanılacak özel yöntem, teknik ve materyal uyarlamaları.\n4. Yazılı ve uygulamalı sınavlarda yapılacak ortam, soru ve süre uyarlamaları.\n5. Rehberlik ve Araştırma Merkezi (RAM) koordinasyonu ve veli bilgilendirmesi.", "defaultDecisions": "1. Öğrencinin hazırbulunuşluk seviyesine uygun olarak basamaklandırılmış öğrenme çıktıları belirlenmiştir.\n2. Yazılı sınavlarda çoktan seçmeli, eşleştirmeli ve kısa cevaplı sorular tercih edilecek, karmaşık metinlerden kaçınılacaktır.\n3. Destek eğitim odasında haftada 2 saat birebir takviye eğitimi sürdürülecektir.", "docType": "BEP", "isBepSpecial": true, "defaultBepStudent": "Ali Can Yılmaz (No: 184) • Özel Öğrenme Güçlüğü (Disleksi)", "defaultBepAdaptations": "Sınav süresine +15 dk ek süre, büyük punto (14pt) açık yazı fontu, görsel şekil destekleri, okuma desteği sağlama"}, {"id": "bep_birimi_toplanti_tutanagi", "title": "BEP Geliştirme Birimi Toplantı Tutanağı ve Uyarlama Kararları", "category": "BEP & Özel Eğitim", "icon": "🧩", "subtitle": "Zümre, sınıf rehber öğretmeni, rehberlik servisi ve veli kurul kararları", "legalBasis": "Özel Eğitim Hizmetleri Yönetmeliği", "defaultAgenda": "1. BEP Geliştirme Biriminin toplanması ve kurul üyelerinin tanıtımı.\n2. Öğrencinin dönem içi ders takip ve sınıf içi uyum durumunun müzakeresi.\n3. Branş öğretmenlerinin ders bazlı uyarlama önerileri.\n4. Velinin görüş ve beklentileri, ev ortamındaki destek süreci.\n5. BEP planının onaylanması ve yürürlüğe konulması.", "defaultDecisions": "1. Hazırlanan BEP planı kurul üyeleri ve veli tarafından oy birliğiyle kabul edilmiştir.\n2. Öğrencinin ders içi başarısı süreç odaklı ölçeklerle takip edilecek, sınav ortamında sessizlik sağlanacaktır.\n3. Bir sonraki izleme toplantısının dönem ortasında yapılması kararlaştırılmıştır.", "docType": "BEP", "isBepSpecial": true, "defaultBepStudent": "Zeynep Kaya (No: 92) • Dikkat Eksikliği ve Hiperaktivite (DEHB)", "defaultBepAdaptations": "Kısa molalar verme, tahtayı doğrudan gören ön sıra konumu, görevleri parçalara ayırma"}, {"id": "bep_izleme_ve_gelisim_raporu", "title": "BEP Dönem Sonu / Yıl Sonu Gelişim ve İzleme Raporu", "category": "BEP & Özel Eğitim", "icon": "📊", "subtitle": "Hedeflenen bireyselleştirilmiş öğrenme çıktılarının gerçekleşme yüzdesi", "legalBasis": "Özel Eğitim Hizmetleri Yönetmeliği", "defaultAgenda": "1. Dönem başında belirlenen Kısa Dönemli Amaçların (KDA) gerçekleşme durumu.\n2. Öğrencinin gelişim gösterdiği beceri alanları.\n3. Güçlük çekilen ve tekrar edilmesi gereken öğrenme çıktıları.\n4. Bir sonraki dönem / eğitim yılı için RAM raporu yenileme tavsiyesi.", "defaultDecisions": "1. Planlanan 6 ana öğrenme çıktısından 5'ine başarıyla ulaşıldığı kaydedilmiştir.\n2. Sosyal etkileşim ve derse odaklanma süresinde belirgin artış gözlemlenmiştir.\n3. Gelişim raporu veli ve RAM ile paylaşılmak üzere dosyalanmıştır.", "docType": "BEP", "isBepSpecial": true, "defaultBepStudent": "Ahmet Demir (No: 305) • Hafif Düzey Otizm Spektrum", "defaultBepAdaptations": "Rutinlerin korunması, görsel yönerge kartları, sosyal hikayeler ile pekiştirme"}, {"id": "destek_egitim_odasi_plani", "title": "Destek Eğitim Odası Bireysel Çalışma Planı ve Takvimi", "category": "BEP & Özel Eğitim", "icon": "🚪", "subtitle": "Haftalık birebir ders saatleri, branş öğretmeni görevlendirmesi ve takvim", "legalBasis": "MEB Destek Eğitim Odası Kılavuzu", "defaultAgenda": "1. Destek eğitim odasından yararlanacak öğrencinin haftalık ders saatleri (Haftada 4 saat).\n2. Görevli branş öğretmenleri ve ders programı entegrasyonu.\n3. Temel beceri eksikliklerini gidermeye yönelik modüler çalışma planı.\n4. Devam-takip çizelgesi ve ders defteri tutma usulü.", "defaultDecisions": "1. Destek eğitim dersleri öğrencinin ana ders programını aksatmayacak şekilde planlanmıştır.\n2. Birebir eğitim sürecinde öğrencinin motivasyonu yüksek tutulmuş, ilerleme kayıt altına alınmıştır.", "docType": "BEP", "isBepSpecial": true, "defaultBepStudent": "Elif Yıldız (No: 114) • Özel Öğrenme Güçlüğü", "defaultBepAdaptations": "Birebir eğitim, somut matematik blokları, fonolojik farkındalık çalışmaları"}, {"id": "evde_egitim_takip_formu", "title": "Evde / Hastanede Eğitim Öğrenci Takip ve Gelişim Formu", "category": "BEP & Özel Eğitim", "icon": "🏡", "subtitle": "Sağlık tedbiriyle evde eğitim alan öğrencinin ders defteri ve veli imza föyü", "legalBasis": "MEB Evde veya Hastanede Eğitim Hizmetleri Yönergesi", "defaultAgenda": "1. İl/İlçe Özel Eğitim Hizmetleri Kurulu evde eğitim kararı ve hekim raporu.\n2. Haftalık evde eğitim ders programı ve saatleri.\n3. Öğrencinin sağlık durumuna göre uyarlanan ders öğrenme çıktıları.\n4. Aylık ders takip föyü ve veli imza onayı.", "defaultDecisions": "1. Dersler öğrencinin ikametgahında titizlikle yürütülmüş, ders saatleri eksiksiz tamamlanmıştır.\n2. Aylık devam takip çizelgesi ve ders defteri düzenli olarak okul idaresine teslim edilmiştir.", "docType": "BEP", "isBepSpecial": true, "defaultBepStudent": "Murat Aksoy (No: 72) • Evde Eğitim Kararlı", "defaultBepAdaptations": "Öğrencinin fiziksel konforu gözetilerek kısa ders blokları, sözlü anlatım, dijital araçlar"}, {"id": "rubrik_surec_odakli", "title": "Süreç Odaklı Dereceli Puanlama Anahtarı (Rubrik) - 4 Düzeyli", "category": "Ölçekler & Rubrik", "icon": "📏", "subtitle": "Akıl yürütme, eleştirel düşünme ve işbirliği analitik dereceli puanlama ölçeği", "legalBasis": "MEB Ölçme ve Değerlendirme Yönetmeliği Süreç Değerlendirme Kriterleri", "defaultAgenda": "1. Ölçülen Boyut 1: Akıl Yürütme ve Bilimsel Çıkarım (Başlangıç 1 - Gelişmekte 2 - Yetkin 3 - İleri Düzey 4).\n2. Ölçülen Boyut 2: Eleştirel Düşünme ve Problem Çözme Becerisi (1-4 Düzey).\n3. Ölçülen Boyut 3: İletişim, Fikir Paylaşımı ve Takım İşbirliği (1-4 Düzey).\n4. Ölçülen Boyut 4: Ürünün Özgünlüğü, Zaman Yönetimi ve Sunum Kalitesi (1-4 Düzey).", "defaultDecisions": "1. Öğrencilere görev öncesinde rubrik kriterleri açıklanmış, ne beklendiği somutlaştırılmıştır.\n2. Puanlama tek bir sınava bağlı kalmaksızın süreç boyunca gözlemlenen beceri düzeyine göre yapılmıştır.\n3. Rubrik sonuçları e-Portfolyo değerlendirme notu olarak sisteme işlenmiştir.", "docType": "OLCEK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "ders_ici_katilim_olcegi", "title": "Ders İçi Süreç ve Katılım Gözlem Ölçeği", "category": "Ölçekler & Rubrik", "icon": "📝", "subtitle": "Derse hazırlık, fikir üretme, dinleme nezaketi ve sorumluluk çetelesi", "legalBasis": "Maarif Modeli Ölçme ve Değerlendirme Yönergesi", "defaultAgenda": "1. Kriter 1: Derse zamanında ve materyalleriyle hazır gelme (20 Puan).\n2. Kriter 2: Ders esnasında soru sorma ve fikir geliştirme gayreti (25 Puan).\n3. Kriter 3: Arkadaşlarının fikirlerini nezaketle dinleme ve söz hakkına riayet (25 Puan).\n4. Kriter 4: Verilen ders içi bireysel ve grup görevlerini sorumlulukla tamamlama (30 Puan).", "defaultDecisions": "1. Katılım ölçeği dönem boyunca tarafsız ve düzenli olarak puanlanmıştır.\n2. Derse çekingen kalan öğrencilere küçük hedefler verilerek katılımları desteklenmiştir.", "docType": "OLCEK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "akran_ve_oz_degerlendirme", "title": "Öğrenci Akran ve Öz Değerlendirme Formu", "category": "Ölçekler & Rubrik", "icon": "🤝", "subtitle": "Grup çalışmalarında öğrencinin kendini ve çalışma arkadaşlarını değerlendirme anketi", "legalBasis": "Maarif Modeli Bütüncül Değerlendirme Yaklaşımı", "defaultAgenda": "1. Grup Çalışmasında Üzerime Düşen Görevi Zamanında Yaptım mı? (Her Zaman / Bazen / Geliştirilmeli).\n2. Grup Arkadaşlarımın Fikirlerine Saygı Gösterdim mi?\n3. Grup Arkadaşlarım Görevlerini Eşit Şekilde Paylaştı mı?\n4. Bu Çalışmada En İyi Yaptığımız Şey ve Bir Dahaki Sefere Daha İyi Yapabileceğimiz Husus.", "defaultDecisions": "1. Formlar öğrencilerce samimiyetle doldurulmuş, öz eleştiri ve sorumluluk bilinci pekiştirilmiştir.\n2. Öğretmen tarafından akran puanları grup dinamiğini geliştirmek üzere geri bildirimde kullanılmıştır.", "docType": "OLCEK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "gelisim_raporu_gorusleri", "title": "Gelişim Raporu Öğretmen Görüşleri Arşivi (Tüm Alanlar)", "category": "Ölçekler & Rubrik", "icon": "💬", "subtitle": "Dönem sonu karneleri için pedagojik, teşvik edici ve yapıcı öğretmen görüşleri", "legalBasis": "MEB e-Okul Karne ve Gelişim Raporu Yönergesi", "defaultAgenda": "1. Üstün Başarılı ve Çalışkan Öğrenciler İçin Pedagojik Görüş Örnekleri.\n2. Gayretli Ancak Desteklenmesi Gereken Öğrenciler İçin Teşvik Edici Cümleler.\n3. Derse Katılımı Çekingen Olan Öğrenciler İçin Cesaretlendirici İfadeler.\n4. Kitap Okuma Alışkanlığı ve Sosyal Becerileri Güçlü Öğrenciler İçin Veli Tavsiyeleri.\n5. Davranış ve Öz Düzenleme Desteği Gereken Öğrenciler İçin Yapıcı Geri Bildirimler.", "defaultDecisions": "1. Karne görüşlerinde öğrenciyi etiketleyici olumsuz ifadelerden kaçınılmış, güçlü yönleri vurgulanarak gelişim adımları belirtilmiştir.\n2. Tüm görüşler e-Okul karne modülüne kaydedilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "surec_odakli_degerlendirme_matrisi", "title": "Süreç Odaklı Değerlendirme Matrisi (Haftalık Beceri Çetelesi)", "category": "Ölçekler & Rubrik", "icon": "📊", "subtitle": "Haftalık öğrenme çıktıları bazında sınıf mevcudu beceri gözlem matrisi", "legalBasis": "MEB Süreç Odaklı İzleme Sistemi", "defaultAgenda": "1. Öğrenme Çıktısı Kodu ve İlgili Haftanın Beceri Tanımı.\n2. Öğrenci Listesi ve Gözlem Kriterleri (Gözlemlendi [+] / Geliştirilmeli [•] / Destek Gerekli [-]).\n3. Hata Yapılan Kavramlar ve Yanılgı Analizi.\n4. Hafta Sonu Telafi Geri Bildirimi.", "defaultDecisions": "1. Matris haftalık ders içi uygulamalar sırasında doldurulmuş, eksik kalan çıktılar için anında düzeltme yapılmıştır.\n2. Matris sonuçları zümre öğretmenler kurulu ara değerlendirmesinde paylaşılmıştır.", "docType": "OLCEK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "proje_performans_olcegi", "title": "Proje ve Performans Görevi Puanlama Ölçeği (MEB Uyumlu)", "category": "Ölçekler & Rubrik", "icon": "📐", "subtitle": "Bilimsel araştırma, içerik zenginliği, zamanlama ve sunum rubriği", "legalBasis": "MEB Ortaöğretim ve İlköğretim Kurumları Yönetmeliği Proje Değerlendirme Hükümleri", "defaultAgenda": "1. Araştırma ve Kaynak Tarama Becerisi (20 Puan).\n2. Bilimsel Yöntem, İçerik Zenginliği ve Özgünlük (30 Puan).\n3. Zamanlama, Taslak Kontrolü ve Planlamaya Riayet (20 Puan).\n4. Sunum, İfade Yeteneği ve Ürün Estetiği (30 Puan).", "defaultDecisions": "1. Öğrencilere proje konuları ve dereceli puanlama anahtarı dönem başında imza karşılığı teslim edilmiştir.\n2. Ara kontroller yapılarak öğrenciye yol gösterilmiş, nihai puanlama şeffaf olarak ilan edilmiştir.", "docType": "OLCEK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "okul_gezisi_onay_dosyasi", "title": "MEB Okul Gezisi Planı ve Kafile Onay Dosyası", "category": "Gezi & Egzersiz", "icon": "🚌", "subtitle": "Gezi güzergahı, kafile listesi, araç evrakları ve İlçe MEM onay dosyası", "legalBasis": "MEB Sosyal Etkinlikler Yönetmeliği Gezi Yönergesi", "defaultAgenda": "1. Gezinin amacı, güzergahı ve ders öğrenme çıktılarıyla pedagojik bağı.\n2. Gezi tarihi, hareket ve dönüş saatleri.\n3. Görevli kafile başkanı ve refakatçi öğretmen listesi.\n4. Katılımcı öğrenci sayısı ve veli izin dilekçelerinin tamamlanması.\n5. Ulaşım firması, TÜRSAB işletme belgesi, araç tescil ve zorunlu koltuk ferdi kaza sigortası.\n6. Gezi ilk yardım çantası ve emniyet tedbirleri.", "defaultDecisions": "1. Gezi planı tüm yasal şartları haiz olarak tanzim edilmiş ve okul müdürlüğünce onaylanmıştır.\n2. Gezi onay dosyası ilgili belgeler eklenerek İlçe Millî Eğitim Müdürlüğü onayına arz edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "gezi_veli_izin_belgesi", "title": "Gezi Veli İzin Muvafakat Belgesi (İmzalı Taahhütname)", "category": "Gezi & Egzersiz", "icon": "📝", "subtitle": "Velinin çocuğunun geziye katılmasına izin verdiğini gösterir yasal belge", "legalBasis": "MEB Sosyal Etkinlikler Yönetmeliği", "defaultAgenda": "1. Öğrencinin Adı, Soyadı, Sınıfı ve Okul Numarası.\n2. Düzenlenen Gezinin Tarihi, Yeri ve Ziyaret Edilecek Merkezler.\n3. Gezi Ücreti ve Kapsamı (Ulaşım, Giriş Ücretleri, Rehberlik).\n4. Velinin Açık İzin ve Beyan İfadesi, İletişim Numaraları ve Islak İmzası.", "defaultDecisions": "1. Islak imzalı veli izin belgesi bulunmayan hiçbir öğrenci gezi kafilesine dahil edilmeyecektir.\n2. Belgeler gezi dosyasına konularak arşivlenmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "gezi_guvenlik_sozlesmesi", "title": "Gezi Güvenlik, Ulaşım ve Sağlık Tedbirleri Sözleşmesi", "category": "Gezi & Egzersiz", "icon": "🛡️", "subtitle": "Gezi süresince emniyet, kural ihlali ve acil sağlık protokolü taahhüdü", "legalBasis": "MEB Gezi ve Seyahat Güvenlik Yönergesi", "defaultAgenda": "1. Öğrencilerin otobüs içinde ve gezi mekanlarında uyması zorunlu emniyet kuralları.\n2. Grup liderinden izinsiz kafileden ayrılmama taahhüdü.\n3. Acil sağlık durumlarında ilk yardım ve 112 Acil Çağrı protokolü.\n4. Taşımacı firmanın hız sınırlarına ve trafik kurallarına riayet sözleşmesi.", "defaultDecisions": "1. Güvenlik kuralları gezi başlangıcında öğrencilere ve görevlilere tebliğ edilmiştir.\n2. Gezi boyunca emniyet kurallarına tam riayet edilecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "satranc_egzersiz_plani", "title": "Satranç Dersi Dışı Eğitim (Egzersiz) Yıllık Çalışma Planı", "category": "Gezi & Egzersiz", "icon": "♟️", "subtitle": "Haftada 6 saatlik satranç egzersiz programı, açılışlar, taktikler ve turnuva", "legalBasis": "MEB Yönetici ve Öğretmenlerinin Ders ve Ek Ders Saatlerine İlişkin Karar Madde 17", "defaultAgenda": "1. Egzersizin Adı: Satranç Dersi Dışı Eğitim Çalışması (Haftalık 6 Ders Saati).\n2. Katılımcı öğrenci listesi, sınıf dağılımı ve veli izin formları.\n3. Egzersiz çalışma gün ve saatleri (Ders bitimi sonrası).\n4. Yıllık müfredat: Temel matlar, taktik motifler, açılış ilkeleri, oyun sonu stratejileri.\n5. Okul içi satranç ligi ve il/ilçe turnuvalarına katılım takvimi.", "defaultDecisions": "1. Egzersiz çalışma dosyası ve antrenörlük belgesi okul müdürlüğü aracılığıyla İlçe MEM'e sunulmuş ve onay alınmıştır.\n2. Dersler haftalık 3 gün 2'şer saat olarak icra edilecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "tiyatro_egzersiz_plani", "title": "Tiyatro / Drama Ders Dışı Egzersiz Yıllık Çalışma Planı", "category": "Gezi & Egzersiz", "icon": "🎭", "subtitle": "Diksiyon, beden dili, doğaçlama, metin ezberi ve sene sonu oyunu planı", "legalBasis": "MEB Ek Ders Kararı Madde 17", "defaultAgenda": "1. Egzersizin Adı: Tiyatro ve Sahne Sanatları Çalışması.\n2. Diksiyon, nefes, artikülasyon ve beden dili çalışmaları.\n3. Doğaçlama ve yaratıcı drama istasyonları.\n4. Sahnelenecek oyun metninin seçimi, rol dağılımı ve prova takvimi.\n5. Dekor, kostüm, ses ve ışık tasarımı komisyonları.\n6. Sene sonu tiyatro gösterimi ve okul prömiyeri.", "defaultDecisions": "1. Çalışmalar öğrencilerin özgüven ve hitabet becerilerini en üst düzeye çıkaracak şekilde planlanmıştır.\n2. Yıl sonunda okul salonunda veli ve öğrencilere yönelik prömiyer icra edilecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "tubitak_egzersiz_plani", "title": "TÜBİTAK 4006 & Bilim Fuarı Proje Egzersizi Çalışma Planı", "category": "Gezi & Egzersiz", "icon": "🚀", "subtitle": "Bilimsel yöntem, araştırma projeleri, deney tasarımı ve fuar hazırlığı", "legalBasis": "TÜBİTAK 4006 Bilim Fuarları Çağrı Metni ve MEB Ek Ders Esasları", "defaultAgenda": "1. Egzersizin Adı: Bilimsel Proje ve Araştırma Geliştirme Egzersizi.\n2. Proje ekiplerinin teşekkülü ve alt proje konularının (Araştırma / Tasarım / İnceleme) belirlenmesi.\n3. Literatür taraması, hipotez kurma, veri toplama ve deney aşamaları.\n4. Proje sonuç raporlarının yazımı ve poster sunumlarının hazırlanması.\n5. Okul TÜBİTAK 4006 Bilim Fuarı sergisinin açılışı.", "defaultDecisions": "1. Proje başvuruları TÜBİTAK portalına süresi içinde yüklenmiştir.\n2. Çalışmalar haftalık egzersiz takvimine uygun olarak laboratuvar ortamında yürütülecektir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "spor_izcilik_egzersiz_plani", "title": "Spor / İzcilik Ders Dışı Egzersiz Yıllık Çalışma Planı", "category": "Gezi & Egzersiz", "icon": "⚽", "subtitle": "Kondisyon, takım sporları, açık hava etkinlikleri ve kamp hazırlık planı", "legalBasis": "MEB Ek Ders Kararı Madde 17", "defaultAgenda": "1. Egzersizin Adı: Spor / İzcilik Eğitimi Çalışması.\n2. Temel kondisyon, ısınma hareketleri ve spor ahlakı (fair-play) ilkeleri.\n3. İzcilik andı, türesi, düğümler, yön bulma ve ilk yardım becerileri.\n4. Okul takımları hazırlık maçları ve ilçe ligi müsabakaları.\n5. Doğa yürüyüşü ve açık hava kamp faaliyeti.", "defaultDecisions": "1. Katılımcı öğrencilerin sağlık raporları ve veli muvafakatnameleri eksiksiz dosyalanmıştır.\n2. Spor salonu ve bahçe kullanım saatleri idareyle koordine edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "dilekce_mazeret_izni", "title": "Mazeret İzni Talep Dilekçesi (657 DMK 104. Madde)", "category": "Dilekçe", "icon": "✉️", "subtitle": "657 Sayılı Kanun 104. madde gereği mazeret izni talep resmi dilekçesi", "legalBasis": "657 Sayılı Devlet Memurları Kanunu Madde 104", "defaultAgenda": "Okulunuzda görev yapmakta olan öğretmenim. Aşağıda belirttiğim şahsi ve zorunlu mazeretim sebebiyle 657 Sayılı Devlet Memurları Kanunu'nun 104. maddesi gereğince tarafıma mazeret izni verilmesi hususunda gereğini müsaadelerinize arz ederim.\n\nMazeret Nedeni: Şahsi ve ailevi zorunlu işlerim dolayısıyla izin talep etmekteyim.\nİzin Başlangıç Tarihi: .../.../2026\nİzin Bitiş Tarihi: .../.../2026\nTalep Edilen Gün Sayısı: 2 (İki) Gün", "defaultDecisions": "İznimi geçireceğim adres ve irtibat numaram aşağıda belirtilmiştir. İzinli bulunduğum süre zarfında derslerimin telafisi zümre öğretmenim ile koordine edilecektir.\n\nGereğini bilgilerinize saygılarımla arz ederim.", "docType": "DILEKCE", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "dilekce_saglik_raporu", "title": "Hastalık Raporu Bildirim ve İzin Dilekçesi (657 DMK 105. Madde)", "category": "Dilekçe", "icon": "🏥", "subtitle": "Alınan sağlık istirahat raporunun resmi izne çevrilmesi dilekçesi", "legalBasis": "657 Sayılı DMK Madde 105 ve Devlet Memurlarına Verilecek Hastalık Raporları Yönetmeliği", "defaultAgenda": "Okulunuzdaki görevim esnasında rahatsızlanmam sebebiyle sağlık kuruluşuna müracaat etmiş bulunmaktayım. Muayenem neticesinde hekim tarafından tarafıma istirahat raporu tanzim edilmiştir.\n\nRaporu Tanzim Eden Kurum: Aile Sağlığı Merkezi / Devlet Hastanesi\nRapor Tarih ve Sayısı: .../.../2026 - No: ...\nİstirahat Süresi: ... Gün", "defaultDecisions": "Söz konusu istirahat raporum ilişikte sunulmuş olup 657 Sayılı Devlet Memurları Kanunu'nun 105. maddesi uyarınca hastalık iznine çevrilmesi hususunda gereğini arz ederim.", "docType": "DILEKCE", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "dilekce_ek_ders_itiraz", "title": "Ek Ders / Maaş Mutemetliği Düzeltme Dilekçesi", "category": "Dilekçe", "icon": "💰", "subtitle": "Eksik yatan ek ders ücreti veya maaş bordrosu düzeltme talep yazısı", "legalBasis": "MEB Yönetici ve Öğretmenlerinin Ek Ders Saatlerine İlişkin Karar", "defaultAgenda": "Okulunuzda görev yapmakta olduğum branşım gereği ... yılı ... ayına ait ek ders bordromu incelediğimde; fiilen girdiğim ders saatleri, nöbet görevi veya sınav görevime ilişkin ek ders ücretimin eksik hesaplandığı tespit edilmiştir.\n\nEksik Hesaplanan Görev: Nöbet Görevi / Kulüp Sosyal Etkinlik / Fiili Ders Saati\nEksik Tahakkuk Ettirilen Miktar: ... Saat", "defaultDecisions": "Ek ders çizelgemin ve ders defterimin mutemetlik kayıtlarıyla yeniden incelenerek hak ettiğim ek ders ücretimin geriye dönük olarak tarafıma ödenmesi hususunda gereğini arz ederim.", "docType": "DILEKCE", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "dilekce_hizmet_ici_egitim", "title": "Hizmet İçi Eğitim / Kurs Katılım Başvuru Dilekçesi", "category": "Dilekçe", "icon": "🎓", "subtitle": "MEBBİS mahalli veya merkezi hizmet içi eğitim faaliyetine katılım onay dilekçesi", "legalBasis": "MEB Hizmet İçi Eğitim Yönetmeliği", "defaultAgenda": "Millî Eğitim Bakanlığı Öğretmen Yetiştirme ve Geliştirme Genel Müdürlüğü / İl Millî Eğitim Müdürlüğü tarafından düzenlenecek olan hizmet içi eğitim faaliyetine katılmak istemekteyim.\n\nFaaliyet Adı: Türkiye Yüzyılı Maarif Modeli Öğretim Yöntemleri Semineri\nFaaliyet Kodu: 2026...\nFaaliyet Tarihleri: .../.../2026 - .../.../2026\nFaaliyet Yeri: Hizmet İçi Eğitim Enstitüsü / Mahalli Eğitim Merkezi", "defaultDecisions": "Bahse konu eğitime katılmam hususunda görevlendirmemin yapılması ve gerekli onayların verilmesini saygılarımla arz ederim.", "docType": "DILEKCE", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "dilekce_yolluk_yevmiye", "title": "Görev Yolluğu ve Seyahat Harcırahı Talep Dilekçesi", "category": "Dilekçe", "icon": "🧳", "subtitle": "Geçici görevlendirme, sınav görevi veya tayin harcırahı yolluk bildirimi", "legalBasis": "6245 Sayılı Harcırah Kanunu", "defaultAgenda": "Makamınızın ... tarih ve ... sayılı görevlendirme onayı gereğince ... görevini yerine getirmek üzere il dışı / ilçe dışı geçici görevlendirildim.\n\nGörev Yeri: ...\nGidiş-Dönüş Tarihi: .../.../2026 - .../.../2026\nUlaşım Aracı: Otobüs / Şahsi Araç / Uçak", "defaultDecisions": "Görev süresince yapmış olduğum yol, konaklama ve yevmiye giderlerimin 6245 Sayılı Harcırah Kanunu hükümleri gereğince hesaplanarak tarafıma ödenmesini arz ederim. Harcama belgelerim ve biletlerim ektedir.", "docType": "DILEKCE", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "dilekce_genel_basvuru", "title": "Okul Müdürlüğüne Genel Müracaat Dilekçesi", "category": "Dilekçe", "icon": "📄", "subtitle": "Her türlü idari talep, izin ve bilgilendirme için uyarlanabilir MEB dilekçesi", "legalBasis": "3071 Sayılı Dilekçe Hakkının Kullanılmasına Dair Kanun", "defaultAgenda": "Okulunuzda görev yapmakta olan ... branşı öğretmeniyim. \n\nMüracaat Konusu: ...\nGerekçe ve Açıklama: Yukarıda belirtilen hususla ilgili gerekli idari işlemlerin başlatılmasını ve tarafıma bilgi verilmesini talep etmekteyim.", "defaultDecisions": "Gereğini bilgilerinize saygılarımla arz ederim.", "docType": "DILEKCE", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "tutanak_sinav_evrak_teslim", "title": "Ortak Sınav Evrakı ve Cevap Kağıtları Teslim Tutanağı", "category": "Tutanak", "icon": "📦", "subtitle": "Sınav sonrası sınav zarfı, cevap kağıtları ve yoklama sirküsü teslim tutanağı", "legalBasis": "MEB Ölçme ve Değerlendirme Yönetmeliği Sınav Güvenliği Esasları", "defaultAgenda": "... tarihinde ... dersine ait ... ortak yazılı sınavı icra edilmiştir.\n\nSınavı Yapılan Ders: ...\nSınava Giren Öğrenci Sayısı: ...\nSınava Girmeyen Mazeretli Öğrenci Sayısı: ...\nTeslim Edilen Soru Kitapçığı / Kağıdı Sayısı: ...\nTeslim Edilen Cevap Kağıdı Sayısı: ...", "defaultDecisions": "Yukarıda nitelikleri yazılı ortak sınav evrakları, sınav salon yoklama imza çizelgesi ve cevap anahtarı kapalı ve mühürlü sınav zarfı içerisinde ders öğretmeni tarafından okul idaresine / sınav komisyonuna eksiksiz teslim edilmiş olup işbu tutanak mahallinde müştereken imza altına alınmıştır.", "docType": "TUTANAK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "tutanak_nobet_olay", "title": "Nöbet Defteri Olay / Vukuat Tespit Tutanağı", "category": "Tutanak", "icon": "🚨", "subtitle": "Teneffüste meydana gelen yaralanma, tartışma veya acil durum tespit tutanağı", "legalBasis": "MEB Eğitim Kurumları Nöbet Hizmetleri Yönergesi", "defaultAgenda": ".../.../2026 tarihinde saat ... sularında ... nöbet bölgesinde görevli bulunduğum esnada aşağıdaki olay meydana gelmiştir:\n\nOlayın Meydana Geldiği Yer: Okul Bahçesi / 2. Kat Koridoru\nOlaya Karışan Öğrenciler: ... (No: ...) ve ... (No: ...)\nOlayın Özeti: Teneffüs zili esnasında oyun oynarken çarpışma neticesinde hafif yaralanma meydana gelmiş / sözlü tartışma yaşanmıştır.", "defaultDecisions": "Olay yerine anında intikal edilmiş, ilk müdahale yapılarak revire / okul idaresine bilgi verilmiştir. Sağlık ve güvenlik tedbirleri alınmış olup işbu tutanak şahitler huzurunda imza altına alınmıştır.", "docType": "TUTANAK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "tutanak_demirbas_hasar", "title": "Okul Eşyasına / Taşınır Malına Zarar Verme Tespit Tutanağı", "category": "Tutanak", "icon": "🔨", "subtitle": "Sınıf akıllı tahtası, kapı veya sıraya verilen hasar ve veli rücu tutanağı", "legalBasis": "Taşınır Mal Yönetmeliği ve MEB Disiplin Hükümleri", "defaultAgenda": "... sınıfında yapılan incelemede kamu malı niteliğindeki okul eşyasına zarar verildiği tespit edilmiştir.\n\nHasar Gören Taşınır Mal: Akıllı Tahta / Sınıf Kapısı / Sıra-Masa\nZararın Boyutu ve Niteliği: Cihaz ekranında çatlak / mekanik kırılma\nHasara Sebep Olan Öğrenci(ler): ... (Sınıf: ... No: ...)\nOlay Saati ve Dersi: ...", "defaultDecisions": "Demirbaşa verilen hasarın tespiti yapılmış olup hasarın giderilmesi veya bedelinin veliye rücu edilmesi amacıyla durum okul idaresine intikal ettirilmiş, işbu tutanak tanzim edilmiştir.", "docType": "TUTANAK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "tutanak_disiplin_olay", "title": "Öğrenci Olumsuz Davranış ve Disiplin Tespit Tutanağı", "category": "Tutanak", "icon": "⚠️", "subtitle": "Sınıf düzenini bozan davranış ve şahitlerle ilk müdahale tutanağı", "legalBasis": "MEB Ortaöğretim / İlköğretim Kurumları Disiplin Maddeleri", "defaultAgenda": ".../.../2026 tarihinde ... dersinde ... sınıfı öğrencisi ... (No: ...) hakkında sınıf düzenini ve eğitim ortamını ihlal eden davranış gözlemlenmiştir.\n\nDavranışın Niteliği: Ders akışını sürekli engelleme / akranına kaba davranış / telefon kullanma\nUygulanan Pedagojik Uyarılar: Bireysel uyarı yapılmış, davranışın düzeltilmesi talep edilmiştir.", "defaultDecisions": "Davranışın tekerrür etmesi üzerine onarıcı disiplin anlayışıyla okul rehberlik servisine ve Okul Disiplin / Öğrenci Davranışlarını Değerlendirme Kuruluna sevk edilmek üzere tutanak imza altına alınmıştır.", "docType": "TUTANAK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "tutanak_devir_teslim", "title": "Derslik / Laboratuvar Sayım ve Devir Teslim Tutanağı", "category": "Tutanak", "icon": "🔑", "subtitle": "Dönem başı veya sonu fen laboratuvarı, atölye ve sınıf devir teslimi", "legalBasis": "Taşınır Mal Yönetmeliği Sayım İlkeleri", "defaultAgenda": "Okulumuz ... Laboratuvarı / Atölyesinde bulunan tüm cihaz, deney aleti, kimyasal madde ve mobilyaların fiziki sayımı yapılmıştır.\n\nSayımı Yapılan Demirbaş Sayısı: ... Kalem\nEksik / Kırık / Kullanım Ömrü Biten Malzemeler: ...\nMevcut ve Çalışır Durumdaki Malzemeler: ...\nLaboratuvar Anahtarları ve Güvenlik Donanımı: ...", "defaultDecisions": "Laboratuvar ortamı tertipli, temiz ve sayım dökümüne uygun olarak yeni görevli öğretmene imza karşılığı eksiksiz devir teslim edilmiştir.", "docType": "TUTANAK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "tutanak_telafi_sinavi", "title": "Mazeret / Telafi Sınavı Komisyon Tutanağı", "category": "Tutanak", "icon": "📑", "subtitle": "Sağlık raporlu veya mazeretli öğrencilerin telafi sınav komisyon tutanağı", "legalBasis": "MEB Ölçme ve Değerlendirme Yönetmeliği Telafi Sınavı Maddesi", "defaultAgenda": "Okul idaresine geçerli sağlık raporu veya mazeret dilekçesi ibraz eden ve mazereti kabul edilen öğrencilerin telafi sınavı icra edilmiştir.\n\nDersin Adı: ...\nTelafi Sınav Tarihi: .../.../2026\nSınava Giren Öğrenci Listesi: ...\nEşdeğer Soru Kitapçığı ve Cevap Anahtarı: Hazırlandı ve uygulandı.", "defaultDecisions": "Telafi sınavı mevzuata uygun şekilde tamamlanmış, sınav kağıtları komisyonca okunarak notlar e-Okul sistemine işlenmek üzere idareye teslim edilmiştir.", "docType": "TUTANAK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "edebiyat_kitap_okuma_takip", "title": "Türk Dili ve Edebiyatı Kitap Okuma Takip Çizelgesi", "category": "Türk Dili & Edebiyat", "icon": "📖", "subtitle": "Dönemlik okunan klasik eserler, sayfa sayısı ve tahlil değerlendirme ölçeği", "legalBasis": "Türk Dili ve Edebiyatı Dersi Öğretim Programı", "defaultAgenda": "1. Öğrenci Listesi ve Dönem Boyunca Okunması Zorunlu Klasik Eserler Listesi.\n2. Eser Tahlil Kriteri 1: Eserin teması, olay örgüsü ve karakter analizi (30 Puan).\n3. Eser Tahlil Kriteri 2: Eserdeki Türkçe zenginliği, kelime hazinesi ve deyimler (30 Puan).\n4. Eser Tahlil Kriteri 3: Sözlü sunum veya yazılı tahlil sınavı performansı (40 Puan).", "defaultDecisions": "1. Her öğrenci dönemde en az 3 klasik eser okuyup tahlil formunu teslim etmiştir.\n2. Kitap okuma notları ders içi süreç değerlendirme notu olarak e-Okul'a işlenmiştir.", "docType": "OLCEK", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "edebiyat_siir_dinletisi_plani", "title": "Şiir Dinletisi / Edebiyat Günü Hazırlık ve Uygulama Planı", "category": "Türk Dili & Edebiyat", "icon": "🎙️", "subtitle": "Şiir seçimi, fon müzikleri, sahne dekoru, sunuculuk ve prova takvimi", "legalBasis": "Sosyal Etkinlikler Yönetmeliği", "defaultAgenda": "1. Dinletinin Teması: 'Yunus'tan Âkif'e Gönül Coğrafyamız Şiirleri'.\n2. Şiir okuyacak öğrenci listesi ve ezberlenecek eserler.\n3. Arka plan fon müzikleri, slayt görselleri ve sahne ışıklandırması.\n4. Sunucu metinlerinin hazırlanması ve prova takvimi.\n5. Davetiye basımı ve okul salonu hazırlıkları.", "defaultDecisions": "1. Provalar haftada 2 gün ders dışı saatlerde icra edilmiş, diksiyon çalışmaları tamamlanmıştır.\n2. Dinleti veli ve öğrencilerin katılımıyla büyük bir coşkuyla icra edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "edebiyat_tiyatro_metin_inceleme", "title": "Tiyatro / Drama Metin İnceleme ve Sahneleme Çalışma Planı", "category": "Türk Dili & Edebiyat", "icon": "🎭", "subtitle": "Klasik Türk tiyatrosu metin analizi, roller, sahne akışı ve prova dosyası", "legalBasis": "Türk Dili ve Edebiyatı Tiyatro Ünitesi Uygulama Esasları", "defaultAgenda": "1. İncelenen Tiyatro Eseri: Şinasi (Şair Evlenmesi) / Turgut Özakman (Töre) vb.\n2. Metnin edebi değeri, çatışma unsurları, dönemin sosyal yapısı.\n3. Sınıf içi canlandırma için rol dağılımı ve tirat ezberleri.\n4. Sahneleme teknikleri, jest ve mimiklerin değerlendirilmesi.", "defaultDecisions": "1. Öğrencilerin edebi metinleri sahnede canlandırarak empati ve estetik beğeni edinmeleri temin edilmiştir.\n2. Çalışma süreci rubrikle puanlanarak performansa dahil edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "ogretmen_dosyasi_fihrist", "title": "Öğretmen Resmi Evrak Dosyası Fihristi ve Kontrol Listesi", "category": "Öğretmen Dosyası Arşivi", "icon": "🗄️", "subtitle": "MEB ve maarif müfettişi denetiminde dosyada bulunması gereken 24 zorunlu evrak", "legalBasis": "MEB Rehberlik ve Denetim Başkanlığı Teftiş Rehberi", "defaultAgenda": "1. 2026-2027 Yıllık Müfredat Çerçeve Planı ve İdare Onayı.\n2. Günlük / Haftalık Ders Planları ve Uygulama Notları.\n3. Zümre Öğretmenler Kurulu Tutanakları (Dönem Başı / 2. Dönem / Sene Sonu).\n4. Şube Öğretmenler Kurulu (ŞÖK) Tutanakları ve Bireysel Tedbir Formları.\n5. Sınıf Rehberlik Yıllık Planı, Oturma Planı ve Sosyometri Raporu.\n6. Sosyal Kulüp Yıllık Çalışma Planı ve Karar Defteri Sureti.\n7. Özel Eğitim / BEP Öğrenci Planları ve RAM İnceleme Raporları.\n8. Yazılı Sınav Evrakları, Madde Analizleri, Cevap Anahtarları ve Rubrikler.\n9. Proje ve Performans Görevi Puanlama Ölçekleri.\n10. Nöbet Görevi Çizelgesi ve Veli Toplantı Tutanakları.", "defaultDecisions": "1. Öğretmen dosyasındaki tüm evraklar güncel, tarihli ve ıslak / dijital imzalı olarak muhafaza edilmektedir.\n2. Dosya fihristi müfettiş incelemesine ve idari denetime hazır halde teslim edilmiştir.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}, {"id": "dijital_arsiv_cizelgesi", "title": "Dijital Öğretmen e-Portfolyo ve Dosya Arşiv Çizelgesi", "category": "Öğretmen Dosyası Arşivi", "icon": "☁️", "subtitle": "MEBBİS, e-Müfredat, DYS ve e-Okul sistemine yüklenen evrakların dijital arşivi", "legalBasis": "MEB Dijitalleşme ve e-Müfredat Yönergesi", "defaultAgenda": "1. e-Müfredat Sistemine Yüklenen Zümre ve Yıllık Plan Onay Numaraları.\n2. MEBBİS Hizmet İçi Eğitim Belgeleri ve Sertifika Portföyü.\n3. e-Okul Sosyal Etkinlik Modülü Veri Giriş Durumu.\n4. Bulut Yedekleme Tarihi ve Arşiv Klasör Hiyerarşisi.", "defaultDecisions": "1. Tüm resmi belgelerin dijital kopyaları PDF ve Word (.doc) formatında güvenli bulut deposunda yedeklenmiştir.\n2. Kağıt israfını önlemek amacıyla dijital arşivleme esas alınmıştır.", "docType": "KURUL_PLAN", "isBepSpecial": false, "defaultBepStudent": "", "defaultBepAdaptations": ""}];
window.PIRTIL_WISDOM_QUOTES = [{"title": "Günün Sözü", "text": "Öğretmenlik, para veya mevki işi değil; bir ruh sanatkârlığıdır. Mektep ise mabettir, orada talebeye hakikat üflenir.", "source": "Nurettin Topçu (Türkiye'nin Maarif Davası)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bize bir insan mektebi lazım. Bir mektep ki bizi kendi ruhumuza kavuştursun; her hareketimizin ahlaki değerini tanıtsın.", "source": "Nurettin Topçu (Türkiye'nin Maarif Davası)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Talebe, hakikatin aşığı ve arayıcısıdır. Muallim ise onu bu aşk yolunda meşale ile karşılayan kılavuzdur.", "source": "Nurettin Topçu (Maarif Davası)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Muallim, sadece bilgi aktaran bir vasıta değil; talebesinin şahsiyetini ilahi ve ahlaki değerlerle yoğuran bir sanatkârdır.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Mektebin gayesi, hafızası dolu fertler değil; iradesi kuvvetli, mesuliyet sahibi ve ahlaklı şahsiyetler yetiştirmektir.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hakiki ilim, insanı kibre değil; sonsuz bir tevazu ve hayrete sevk eden idraktir.", "source": "Nurettin Topçu (İslam ve İnsan)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İsyan ahlakı; kötülüğe, haksızlığa ve cehalete boyun eğmeyip ruhun hürriyetine sahip çıkmaktır.", "source": "Nurettin Topçu (İsyan Ahlakı)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir milletin mektebi bozulursa, ruhu da harabeye döner. Yeniden diriliş mektepten başlar.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hakikati arayan talebeye verilecek ilk ders; kendi nefsinin esiri olmaktan kurtulma cehdidir.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmen, dershanede sadece ders anlatmaz; hayatıyla, duruşuyla ve ahlakıyla canlı bir numune teşkil eder.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Büyük insanlar mekteplerin kürsülerinde değil, öğretmenlerin kalplerinde mayalanır.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sevgiyle yoğrulmamış hiçbir bilgi, insanın gönlünde kalıcı bir fazilet yeşertemez.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Düşünmek, bir çilenin ve hakikat arayışının mahsulüdür; kolay yoldan düşünce sahibi olunamaz.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir mektep ki talebeye merhameti ve adaleti öğretmez; orada verilen fennin hiçbir kıymeti yoktur.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Muallimin en büyük mükâfatı, yetiştirdiği talebenin hakikat ve erdem yolunda dimdik yürüdüğünü görmektir.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Milletlerin geleceğini tayin eden en mühim muharebe, mektep sıralarında cehalete karşı verilen mücadeledir.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kendi milli ve manevi köklerinden kopmuş bir maarif, ancak taklitçi ve silik nesiller üretir.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim amele dönüşmediği müddetçe, zihinde ağır bir yüktür; ahlaka dönüştüğünde ise kanattır.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmen talebesine sadece dünyayı değil, kendi içindeki sonsuz âlemi keşfetmeyi öğretmelidir.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gerçek hürriyet, arzuların kölesi olmak değil; hakikatin emrine girip iradeye sahip olmaktır.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Talebenin gönlüne girmeden beynine giremezsiniz. Önce sevgi, sonra bilgi.", "source": "İsmail Hakkı Baltacıoğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitim ancak hayatın içinde, yaparak ve yaşayarak gerçekleştiğinde hakiki manasını bulur.", "source": "İsmail Hakkı Baltacıoğlu (Talim ve Terbiyede İnkılap)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuğu kitapla boğmayınız; tabiatla, sanatla ve cemiyetle temas ettiriniz.", "source": "İsmail Hakkı Baltacıoğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Okul, toplumun minyatürü olmalı; orada yaşanan her an hayata canlı bir köprü kurmalıdır.", "source": "İsmail Hakkı Baltacıoğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Görerek, dokunarak ve üreterek öğrenmeyen zihin; ezberlediği bilgiyi ilk rüzgârda unutur.", "source": "İsmail Hakkı Baltacıoğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrenciye bilgi hamalı muamelesi yapmayınız; ona bilginin lezzetini tattırınız.", "source": "Hasan Âli Yücel", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir milletin kültür seviyesi, kütüphanelerindeki kitap sayısı ve okuyan insanlarının derinliği ile ölçülür.", "source": "Hasan Âli Yücel", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitimde gaye; hür fikirli, hür vicdanlı, kendi haysiyetine ve başkalarının hakkına saygılı insan yetiştirmektir.", "source": "Hasan Âli Yücel", "icon": "📜"}, {"title": "Günün Sözü", "text": "Klasikleri okumayan bir zihin, çağdaş dünyanın düşünce haritasını asla doğru okuyamaz.", "source": "Hasan Âli Yücel", "icon": "📜"}, {"title": "Günün Sözü", "text": "Cumhuriyet maarifinin en büyük zaferi, her köye ilmin ve medeniyetin meşalesini ulaştırmaktır.", "source": "Hasan Âli Yücel", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hars (kültür) bir milletin can damarıdır; medeniyet ise milletlerarası müşterek ilim ve fennin toplamıdır.", "source": "Ziya Gökalp (Türkçülüğün Esasları)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Milli şuurla aydınlanmamış bir terbiye, yabancı rüzgârların önünde savrulan bir yaprak gibidir.", "source": "Ziya Gökalp", "icon": "📜"}, {"title": "Günün Sözü", "text": "Vazifesini menfaatinin üstünde tutan nesiller, ancak disiplinli bir mektep terbiyesiyle yetişir.", "source": "Ziya Gökalp", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gençliği iyi yetiştiren bir milletin geleceği teminat altındadır; gençliğini ihmal eden millet ise yok olmaya mahkûmdur.", "source": "Ziya Gökalp", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitim hayata hazırlık değildir; eğitimin kendisi bizatihi hayatın ta kendisidir.", "source": "John Dewey (Demokrasi ve Eğitim)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrencilere bugünün yöntemleriyle dünün bilgilerini öğretirsek, onların yarınlarını çalmış oluruz.", "source": "John Dewey", "icon": "📜"}, {"title": "Günün Sözü", "text": "Deneyim ve eylem olmaksızın öğrenme gerçekleşmez; zihin ancak uygulayarak derinleşir.", "source": "John Dewey", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir problemle karşılaşmayan zihin düşünmeye başlamaz; merak ve çelişki öğrenmenin kıvılcımıdır.", "source": "John Dewey", "icon": "📜"}, {"title": "Günün Sözü", "text": "Demokratik bir toplum, ancak eleştirel düşünebilen ve bağımsız sorgulayabilen bireylerin eğitimiyle yaşatılabilir.", "source": "John Dewey", "icon": "📜"}, {"title": "Günün Sözü", "text": "Her çocuk, doğru ortam ve şefkat sağlandığında mucizeler oluşturabilecek bir tohumdur.", "source": "Maria Montessori (Çocuğun Keşfi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bana kendi başıma yapabilmem için yardım et; bağımsızlık çocuğun en büyük gelişim ihtiyacıdır.", "source": "Maria Montessori", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuğun oyunu onun en ciddi işidir; oynarken dünyayı ve kendi sınırlarını inşa eder.", "source": "Maria Montessori", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitimin amacı çocuğa bilgi yüklemek değil; onun içindeki öğrenme aşkını ve doğal merakı canlı tutmaktır.", "source": "Maria Montessori", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir öğretmenin başarısının en büyük ölçütü, 'Çocuklar sanki ben yokmuşum gibi şevkle çalışıyorlar' diyebilmesidir.", "source": "Maria Montessori", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuğun yapabildikleri ile bir rehberin yardımıyla yapabilecekleri arasındaki mesafe, onun gelişim alanıdır.", "source": "Lev Vygotsky (Yakınsal Gelişim Alanı Teorisi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Düşünce sadece sözcüklerle ifade edilmez; düşünce sözcüklerin içinde doğar ve gelişir.", "source": "Lev Vygotsky (Düşünce ve Dil)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrenme, sosyal bir süreçtir; çocuk akranlarıyla ve öğretmenleriyle iletişim kurdukça içselleştirir.", "source": "Lev Vygotsky", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir çocuk oyunda her zaman kendi yaşının ve günlük davranışlarının bir baş boy üstündedir.", "source": "Lev Vygotsky", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitimin temel gayesi, sadece başkalarının yaptıklarını tekrarlayan değil; yeni şeyler yapabilen insanlar yetiştirmektir.", "source": "Jean Piaget", "icon": "📜"}, {"title": "Günün Sözü", "text": "Zekâ, ne bildiğiniz değil; bilmediğiniz bir durumla karşılaştığınızda nasıl davrandığınızdır.", "source": "Jean Piaget", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir çocuğa bir şeyi erkenden öğretirseniz, onun bunu kendi başına keşfetme fırsatını elinden almış olursunuz.", "source": "Jean Piaget", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuk küçük bir yetişkin değildir; onun dünyayı algılama biçimi kendine has ve zengindir.", "source": "Jean Piaget", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitmek, dünyayı değiştirecek insanları değiştirmektir.", "source": "Paulo Freire (Ezilenlerin Pedagojisi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmek, bilginin aktarılması değil; öğrencinin kendi bilgisini üretmesi için olanak yaratmaktır.", "source": "Paulo Freire", "icon": "📜"}, {"title": "Günün Sözü", "text": "Diyalog olmadan otantik bir eğitim olamaz; öğretmen ve öğrenci birlikte öğrenirler.", "source": "Paulo Freire", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ezberci bankacı eğitim modeli zihinleri pasifleştirir; eleştirel problem tanımlayıcı eğitim ise özgürleştirir.", "source": "Paulo Freire", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kafayı eğitip kalbi ve elleri ihmal etmek, yarım insan yetiştirmektir.", "source": "Johann Heinrich Pestalozzi (Baş, Kalp ve El Metodu)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocukluk insanın köküdür; kök ne kadar sevgi ve tabiatla beslenirse, ağaç o kadar meyve verir.", "source": "Friedrich Fröbel (Anaokulunun Kurucusu)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tüm insanlara her şeyi öğretmek mümkündür; yeter ki doğru yöntem, sabır ve sevgiyle yaklaşılsın.", "source": "Jan Amos Comenius (Büyük Didaktika)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Herhangi bir konuyu, herhangi bir gelişim evresindeki herhangi bir çocuğa dürüst bir biçimde öğretmek mümkündür.", "source": "Jerome Bruner (Eğitim Süreci)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Keşfederek öğrenme, bilginin kalıcılığını ve problem çözme motivasyonunu en üst düzeye çıkarır.", "source": "Jerome Bruner", "icon": "📜"}, {"title": "Günün Sözü", "text": "Önemli olan kaç puan aldığınız değil; o öğrenme çıktısında neleri derinlemesine kavrayıp uygulayabildiğinizdir.", "source": "Benjamin Bloom (Öğrenme Taksonomisi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Uygun zaman ve nitelikli öğrenme koşulları sağlandığında, hemen her öğrenci hedeflenen başarıya ulaşabilir.", "source": "Benjamin Bloom (Tam Öğrenme Modeli)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Mesele ne kadar akıllı olduğun değil; hangi alanlarda ve nasıl akıllı olduğundur.", "source": "Howard Gardner (Çoklu Zekâ Kuramı)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrencilere 'Çok zekisin' demek yerine gösterdikleri çabayı övmek, onlarda gelişim zihniyetini besler.", "source": "Carol Dweck (Zihniyet - Mindset)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hatalar başarısızlık değil; beynin yeni sinirsel bağlar kurarak öğrendiğinin en somut kanıtıdır.", "source": "Carol Dweck", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yaratıcılık, okuryazarlık kadar önemlidir ve eğitimde aynı derecede ciddiyetle ele alınmalıdır.", "source": "Sir Ken Robinson (Yaratıcı Okullar)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Okullar fabrikatör mantığıyla tek tip insan yetiştirmekten vazgeçmeli; insan yeteneklerinin çeşitliliğini kucaklamalıdır.", "source": "Sir Ken Robinson", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bana bir harf öğretenin kırk yıl kölesi olurum.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim maldan hayırlıdır; çünkü ilim seni korur, sen ise malı korumak zorunda kalırsın.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuklarınızı kendi zamanınıza göre değil, onların yaşayacakları zamana göre yetiştiriniz.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim bir noktaydı, cahiller onu çoğalttı.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Cahilin yanında ilmin susması, hikmetin ta kendisidir.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Düşüncesi berrak olanın dili tatlı, muamelesi adil olur.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanın kıymeti, himmetinin yüceliği ve bilgiyi güzel amele dönüştürmesi kadardır.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Soruyu güzel sormak, ilmin yarısıdır.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Akıl gibi zenginlik, cehalet gibi yoksulluk, edep gibi miras yoktur.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hakkı tanı, hak ehlini de tanırsın. Hakkı kişilere göre değil; kişileri hakka göre değerlendir.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim amel etmek içindir; amel ise ihlas ile kıymet bulur. Amelsiz ilim meyvesiz ağaca benzer.", "source": "İmam Gazali (İhyâu Ulûmi'd-Dîn)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ey oğul! Bilgi amelle birleşmezse sana fayda sağlamaz; bilmek yetmez, yaşamak gerekir.", "source": "İmam Gazali (Eyyühe'l-Veled)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmen, şefkatli bir anne ve baba gibi talebesine muamele etmeli; ona kendi çocuğu gibi kol kanat germelidir.", "source": "İmam Gazali", "icon": "📜"}, {"title": "Günün Sözü", "text": "Şüphe etmeyen hakikati bulamaz; sorgulama ilmin ve basiretin ilk basamağıdır.", "source": "İmam Gazali (el-Munkızu mine'd-Dalâl)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kalp bir ayna gibidir; kötü ahlak ve gaflet pasını ilim, zikir ve tefekkür cilasıyla siliniz.", "source": "İmam Gazali", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir muallim ders verirken kendi menfaatini veya övülmeyi değil, talebesinin iki cihan saadetini gaye edinmelidir.", "source": "İmam Gazali", "icon": "📜"}, {"title": "Günün Sözü", "text": "Haset ve kibir ilmin zehridir; âlimin süsü ise tevazu ve hilimdir.", "source": "İmam Gazali", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim öğrenmek bir ibadettir; lakin o ilimle kibirlenmek şeytanın tuzağına düşmektir.", "source": "İmam Gazali", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrenciye ders anlatırken onun anlama seviyesini gözetiniz; her kaba ancak alabileceği kadar su dökülür.", "source": "İmam Gazali", "icon": "📜"}, {"title": "Günün Sözü", "text": "Felsefe ve mantık, aklı terbiye eden ve insanı doğru düşünmeye sevk eden mukaddes birer alettir.", "source": "Farabi (İhsâ'ül-Ulûm)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Erdemli bir toplum, ancak fertlerinin bilgiye, adalete ve karşılıklı yardımlaşmaya dayandığı toplumdur.", "source": "Farabi (El-Medinetü'l-Fâzıla)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Müziğin ve sanatın gayesi, ruhun taşkınlıklarını dizginleyip onu ahlaki dengeye ulaştırmaktır.", "source": "Farabi (Kitâbü'l-Mûsîka'l-Kebîr)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Doğru bir eğitim, önce ahlakı arındırmalı; ardından aklı hikmetle ve mantıkla donatmalıdır.", "source": "Farabi", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim ve sanat takdir edilmediği yerden göç eder; marifet ancak iltifata tabidir.", "source": "İbn Sina (El-Kânûn fî't-Tıbb)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dünya bir penceredir; her gelen bakar geçer. Mühim olan o pencereden hakikati görüp geride güzel bir iz bırakmaktır.", "source": "İbn Sina", "icon": "📜"}, {"title": "Günün Sözü", "text": "Şifanın en büyük kaynağı ümit, ilacın en tesirlisi tebessüm, koruyucusu ise dengeli bir ruhtur.", "source": "İbn Sina", "icon": "📜"}, {"title": "Günün Sözü", "text": "Aklın sınırı yoktur; fakat insan aklını kullanmadığı ölçüde kendi dar zindanına hapsolur.", "source": "İbn Sina", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tarih, sadece geçmiş vakaların hikâyesi değil; cemiyetlerin doğuş, yükseliş ve çöküş kanunlarını bildiren ilimdir.", "source": "İbn Haldun (Mukaddime)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Geçmiş geleceğe, suyun suya benzediğinden daha çok benzer. Tarihi bilen geleceği öngörür.", "source": "İbn Haldun", "icon": "📜"}, {"title": "Günün Sözü", "text": "Coğrafya kaderdir; lakin o kaderi ilim, adalet ve asabiyetle mamur etmek insanın iradesindedir.", "source": "İbn Haldun", "icon": "📜"}, {"title": "Günün Sözü", "text": "Devletler ve medeniyetler de tıpkı insanlar gibi doğar, büyür, olgunlaşır ve lüks içinde ihtiyarlayıp yıkılır.", "source": "İbn Haldun", "icon": "📜"}, {"title": "Günün Sözü", "text": "Talebeye aşırı baskı ve ceza uygulamak, onda yalanı, hileyi ve korkaklığı yeşertir; eğitim sevgi ve nezaketle yürür.", "source": "İbn Haldun", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim tahsilinde tek gaye hakikati bulmaktır; peşin hüküm ve tarafgirlik hakikatin en büyük düşmanıdır.", "source": "Biruni", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yeryüzü ve gökyüzü, aklını kullanan ve tefekkür eden bir insan için muazzam bir açık laboratuvardır.", "source": "Biruni", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gel, ne olursan ol yine gel; ister kâfir, ister mecusi, ister puta tapan ol yine gel.", "source": "Mevlânâ Celâleddîn-i Rûmî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir mum diğer mumu tutuşturmakla ışığından hiçbir şey kaybetmez.", "source": "Mevlânâ Celâleddîn-i Rûmî (Mesnevî)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dünle beraber gitti cancağızım, ne kadar söz varsa düne ait; şimdi yeni şeyler söylemek lazım.", "source": "Mevlânâ Celâleddîn-i Rûmî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Nice insanlar gördüm üzerinde elbise yok, nice elbiseler gördüm içinde insan yok.", "source": "Mevlânâ Celâleddîn-i Rûmî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Testide ne varsa dışına o sızar; insanın dili kalbinde saklı olanın tercümanıdır.", "source": "Mevlânâ Celâleddîn-i Rûmî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yolun ucunun nereye varacağını düşünmek beyhude bir çabadır. Sen sadece atacağın ilk adımı düşünmekle yükümlüsün.", "source": "Mevlânâ Celâleddîn-i Rûmî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Cahil kimsenin yanında kitap gibi sessiz ol; çünkü o bilginin değil, kibrinin peşindedir.", "source": "Mevlânâ Celâleddîn-i Rûmî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gönül kazanmak istersen sevgi tohumu ek; cennet gibi bir bahçe istersen herkese merhametle bak.", "source": "Mevlânâ Celâleddîn-i Rûmî", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim ilim bilmektir, ilim kendin bilmektir; sen kendini bilmezsin, ya nice okumaktır.", "source": "Yunus Emre", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bölüşürsek tok oluruz, bölünürsek yok oluruz.", "source": "Yunus Emre", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sevelim, sevilelim; dünya kimseye kalmaz.", "source": "Yunus Emre", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dervişlik dedikleri hırka ile taç değil; gönlün Hakk'a ermesi, kibrin yok olmasıdır.", "source": "Yunus Emre", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir kez gönül yıktın ise bu kıldığın namaz değil; yetmiş iki millet dahi elin yüzün yumaz değil.", "source": "Yunus Emre", "icon": "📜"}, {"title": "Günün Sözü", "text": "Okumaktan mana ne? Kişi Hakk'ı bilmektir; çün okudun bilmezsin, ha bir kuru emektir.", "source": "Yunus Emre", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eline, beline, diline sahip ol; aşına, işine, eşine sadık kal.", "source": "Hacı Bektaş-ı Veli (Makâlât)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlimden gidilmeyen yolun sonu karanlıktır.", "source": "Hacı Bektaş-ı Veli", "icon": "📜"}, {"title": "Günün Sözü", "text": "Düşünce karanlığına ışık tutanlara ne mutlu; arayış içinde olan asla mahrum kalmaz.", "source": "Hacı Bektaş-ı Veli", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kadınları okutunuz; annesi cahil olan bir toplumun çocukları aydınlık göremez.", "source": "Hacı Bektaş-ı Veli", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hikmet ile amel eden dervişler, gönüllere şifa ve aydınlık saçar.", "source": "Hoca Ahmet Yesevi (Divan-ı Hikmet)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Garip ve yetimleri sevindiriniz; Hakk'ın rızası mazlumların dualarındadır.", "source": "Hoca Ahmet Yesevi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ey oğul! İnsanlar vardır şafak vaktinde doğar, akşam ezanında ölürler. Unutma ki dünya geniştir ama ömür pek kısadır.", "source": "Şeyh Edebali (Osman Gazi'ye Nasihat)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hakikati söylemekten korkma; fakat söylerken edebi ve nezaketi elden bırakma.", "source": "Şeyh Edebali", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanı yaşat ki devlet yaşasın.", "source": "Şeyh Edebali", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitim, kafası bilgilerle dolu bir insan değil; doğru düşünen, sorgulayan ve ahlak üreten bir şahsiyet inşa etmektir.", "source": "Aliya İzzetbegoviç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Geleceğimizi geçmişimizde aramayacağız; geçmişimizden güç alarak geleceğimizi biz inşa edeceğiz.", "source": "Aliya İzzetbegoviç (Tarihe Tanıklığım)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bunu hiç unutma evlat! Batı hiçbir zaman adil olmadı; düşmanına benzediğin an savaşı kaybedersin.", "source": "Aliya İzzetbegoviç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yeryüzünün öğretmeni olabilmek için, gökyüzünün öğrencisi olmak gerekir.", "source": "Aliya İzzetbegoviç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Savaş ölünce değil, düşmana benzediğin zaman kaybedilir.", "source": "Aliya İzzetbegoviç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kur'an edebiyat değil, hayattır; dolayısıyla ona bir düşünce tarzı olarak değil, bir hayat tarzı olarak bakılmalıdır.", "source": "Aliya İzzetbegoviç (Doğu Batı Arasında İslam)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İslam medeniyeti, asırlarca dünya bilimine öncülük etmiştir; bu hakikati bilmek özgüvenimizin temel taşıdır.", "source": "Prof. Dr. Fuat Sezgin (İslam'da Bilim ve Teknik)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Günde 17-18 saat çalışmadan büyük bir ilim inşa edilemez; başarı zekâdan çok gayret ve sebat işidir.", "source": "Prof. Dr. Fuat Sezgin", "icon": "📜"}, {"title": "Günün Sözü", "text": "Aşağılık duygusundan kurtulup geçmişimizdeki bilimsel mirası keşfettiğimiz an, yeniden zirveye yürürüz.", "source": "Prof. Dr. Fuat Sezgin", "icon": "📜"}, {"title": "Günün Sözü", "text": "Her güçlüğün ardında bir kolaylık, her cehdin sonunda ilahi bir fetih vardır; yeter ki niyet pak olsun.", "source": "Akşemseddin (Fatih'in Hocası)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Talebenin zihnini şüphelerden arındırmak, ona sağlam bir inanç ve berrak bir hedef aşılamak hocanın borcudur.", "source": "Akşemseddin", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kainatın hendesesini (geometrisini) ve matematik düzenini anlamayan, hakiki manada hikmete eremez.", "source": "Ali Kuşçu (Fethiye)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Mizan ve adalet ölçüsüyle tartılmayan hiçbir fikir, cemiyette huzur ve dirlik kuramaz.", "source": "Katip Çelebi (Mîzânü'l-Hakk)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Geleceğin güvencesi sağlam temellere dayalı bir eğitime, eğitim ise fedakâr öğretmenlere bağlıdır.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dünyanın her tarafında öğretmenler insan topluluğunun en fedakâr ve saygıdeğer unsurlarıdır.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmenler! Yeni nesil sizin eseriniz olacaktır.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hayatta en hakiki mürşit ilimdir, fendir; ilim ve fenden başka yol gösterici aramak gaflettir, dalalettir, cehalettir.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "En büyük savaş, cehalete karşı yapılan savaştır.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir millet irfan ordusuna sahip olmadıkça, muharebe meydanlarında ne kadar parlak zaferler elde ederse etsin, o zaferlerin payidar neticeler vermesi mümkün değildir.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Milletleri kurtaranlar yalnız ve ancak öğretmenlerdir. Öğretmenden, eğiticiden mahrum bir millet, henüz bir millet adını alma kabiliyetini kazanamamıştır.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gençliği yetiştiriniz; onlara ilim ve irfanın müspet fikirlerini veriniz. Geleceğin aydınlığına onlarla kavuşacaksınız.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitimdir ki bir milleti ya hür, bağımsız, şanlı, yüksek bir cemiyet halinde yaşatır; ya da bir milleti esaret ve sefalete terk eder.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Cumhuriyet sizden fikri hür, vicdanı hür, irfanı hür nesiller ister.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Benim manevi mirasım ilim ve akıldır. Zaman süratle ilerliyor, milletlerin, cemiyetlerin, fertlerin saadet ve şekavet telakkileri bile değişiyor.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuklar geleceğimizin teminatı, yaşama sevincimizdir. Bugünün çocuğunu, yarının büyüğü olarak yetiştirmek hepimizin vazifesidir.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Okul genç beyinlere insanlığa hürmeti, millet ve memlekete muhabbeti, şerefi ve bağımsızlığı öğretir.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kitapsız yaşamak; kör, sağır, dilsiz yaşamaktır.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sanatsız kalan bir milletin hayat damarlarından biri kopmuş demektir.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Zafer, 'Zafer benimdir' diyebilenindir. Başarı ise, 'Başaracağım' diye başlayıp sonunda 'Başardım' diyebilenindir.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tarih yazmak, tarih yapmak kadar mühimdir; yazan yapana sadık kalmazsa değişmeyen hakikat insanlığı şaşırtacak bir mahiyet alır.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Biz cahil dediğimiz zaman, mektepte okumamış olanları kastetmiyoruz; hakikati göremeyenleri kastediyoruz.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Milli ahlakımız, medeni fikirlerle ve serbest düşünceyle beslenmeli ve takviye olunmalıdır.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dinlenmemek üzere yürümeye karar verenler, asla ve asla yorulmazlar.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Doğrudan doğruya Kur'an'dan alıp ilhamı, asrın idrakine söyletmeliyiz İslam'ı.", "source": "Mehmet Âkif Ersoy (Safahat)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Âsım'ın nesli diyordum ya nesilmiş gerçek; işte çiğnetmedi namusunu, çiğnetmeyecek!", "source": "Mehmet Âkif Ersoy (Safahat - Çanakkale Şehitlerine)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sahipsiz olan memleketin batması haktır; sen sahip olursan bu vatan batmayacaktır.", "source": "Mehmet Âkif Ersoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "Girmeden tefrika bir millete düşman giremez; toplu vurdukça yürekler onu top sindiremez.", "source": "Mehmet Âkif Ersoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "Biri eyyamı sayar, derbeder eyler ömrü; biri bir anı değerlendirir, ebedi kılar dünü.", "source": "Mehmet Âkif Ersoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bekleyenler var arkanda, uyan ey gafil! Çalışmak zamanı geldi, geçiyor bile vakit.", "source": "Mehmet Âkif Ersoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "İmandır o cevher ki ilahi ne büyüktür; imansız olan paslı yürek sinede yüktür.", "source": "Mehmet Âkif Ersoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ye's öyle bataktır ki düşersen boğulursun; ümide sarıl sımsıkı, seyret ne olursun!", "source": "Mehmet Âkif Ersoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hayır, hayal ile yoktur benim alışverişim; her ne demişsem görüp de söylemişim.", "source": "Mehmet Âkif Ersoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tarihi 'tekerrür' diye tarif ediyorlar; hiç ibret alınsaydı tekerrür mü ederdi?", "source": "Mehmet Âkif Ersoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hafıza bilginin bekçisidir; fakat tefekkür onun ruhudur.", "source": "Cemil Meriç (Bu Ülke)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kitap bir limandı benim için. Kitaplarda yaşadım ve kitaplardaki insanları sokaktakilerden çok daha çok sevdim.", "source": "Cemil Meriç (Bu Ülke)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kamus (sözlük) bir milletin hafızasıdır, yani kendisidir; kamusa uzanan el namusa uzanmıştır.", "source": "Cemil Meriç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Düşünce şüpheyle başlar; tecessüs (merak) ilmin anasıdır.", "source": "Cemil Meriç (Mağaradakiler)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İzm'ler idrakimize giydirilen deli gömlekleridir; hakikat hiçbir kalıba sığmayacak kadar geniştir.", "source": "Cemil Meriç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kültür, kaypak bir kelime; irfan ise ruhun bütün melekelerini aydınlatan nurdur.", "source": "Cemil Meriç (Kültürden İrfana)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Aydın olmak için önce kendi milletinin tarihine, acılarına ve inançlarına sadık kalmak gerekir.", "source": "Cemil Meriç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tefekkür, hürriyetin çocuğudur; yasakların başladığı yerde düşünce susar, papağanlık başlar.", "source": "Cemil Meriç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gençlere ilk öğretilecek şey, peşin hükümlerin kölesi olmadan hakikati arama cesaretidir.", "source": "Cemil Meriç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Okumak, iki ruh arasında kurulan en samimi ve en soylu köprüdür.", "source": "Cemil Meriç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yalanın fethettiği kaleleri ancak hakikatin meşalesi yerle bir edebilir.", "source": "Cemil Meriç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Diriliş nesli, kalbiyle inanan, aklıyla düşünen ve bileğiyle üreten bir medeniyet meşalesidir.", "source": "Sezai Karakoç (Diriliş Neslinin Âmentüsü)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Uzatma dünya sürgünümü benim; ülkendeki kuşlardan ne haber vardır?", "source": "Sezai Karakoç (Sürgün Ülkeden Başkentler Başkentine)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsan yenilince değil, pes edince ve ruhunu teslim edince tükenir.", "source": "Sezai Karakoç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Medeniyet, taşların üst üste konması değil; kalplerin Hakk'a ve hakikate bağlanmasıdır.", "source": "Sezai Karakoç (Yitik Cennet)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gelecek, inancını ve köklerini kaybetmeyen fedakâr gençlerin omuzlarında yükselecektir.", "source": "Sezai Karakoç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir genç yetiştirmek, bir çağı ve bir medeniyeti yeniden inşa etmektir.", "source": "Sezai Karakoç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kuşlar bile kaderle uçar; velhasıl imtihan dünyasındayız, sabır gerek.", "source": "Cahit Zarifoğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kalbin bir işi var: Sevmek. Aklın bir işi var: Anlamak. İkisini birleştiren ise hakiki insandır.", "source": "Cahit Zarifoğlu (Yaşamak)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuklarınıza bırakacağınız en kıymetli miras; berrak bir vicdan ve temiz bir ahlaktır.", "source": "Cahit Zarifoğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir değirmendir bu dünya; öğütür her şeyi, geriye sadece niyetler ve ameller kalır.", "source": "Cahit Zarifoğlu (Bir Değirmendir Bu Dünya)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Zaman bendedir ve mekân bana emanettir şuurunda bir gençlik!", "source": "Necip Fazıl Kısakürek (Gençliğe Hitabe)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Devler gibi eserler bırakmak için, karıncalar gibi çalışmak gerekir.", "source": "Necip Fazıl Kısakürek", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tohum saç, bitmezse toprak utansın! Hedefe varmayan mızrak utansın!", "source": "Necip Fazıl Kısakürek (Çile)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kökü mazide olan ati olacağız; geçmişini inkâr eden geleceğini kuramaz.", "source": "Yahya Kemal Beyatlı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Türkçe ağzımda annemin ak sütüdür; dilini kaybeden bir millet kimliğini de kaybeder.", "source": "Yahya Kemal Beyatlı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Geçmiş zaman, bugünün içindedir; onu duymak ve bugüne taşımak marifettir.", "source": "Ahmet Hamdi Tanpınar (Huzur)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ne içindeyim zamanın, ne de büsbütün dışında; yekpare, geniş bir anın parçalanmaz akışında.", "source": "Ahmet Hamdi Tanpınar", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kültürsüz ve idealsiz bir maarif, gençliği ruhen felç eder ve yabancılaşmaya iter.", "source": "Peyami Safa (Eğitim - Gençlik - Üniversite)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çoğu insan zekâya inanır; ben inanmıyorum. Bizi birbirimizden ayıran emektir, ben çalışmaya inanıyorum.", "source": "Prof. Dr. Aziz Sancar (Nobel Kimya Ödülü)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Memleket sevgisi olmadan yapılan hiçbir bilimsel başarı kalıcı bir ruh kazanamaz.", "source": "Prof. Dr. Aziz Sancar", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gençlerimize tavsiyem; çok okuyun, sebatla çalışın ve memleketinizi asla unutmayın.", "source": "Prof. Dr. Aziz Sancar", "icon": "📜"}, {"title": "Günün Sözü", "text": "Matematik esasında sabırdır; ezberlemek değil, keşfederek anlamaktır.", "source": "Ord. Prof. Cahit Arf (Arf Değişmezi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Matematiği anlayamazsanız hayatı da tam anlayamazsınız; çünkü kâinat matematik diliyle yazılmıştır.", "source": "Ord. Prof. Cahit Arf", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilim insanı olmak bir meslek değil; bir yaşam tarzı ve tükenmeyen bir meraktır.", "source": "Ord. Prof. Cahit Arf", "icon": "📜"}, {"title": "Günün Sözü", "text": "Türkçe giderse Türkiye gider! Bilim kendi anadilinle yapıldığında derinleşir ve halka mal olur.", "source": "Prof. Dr. Oktay Sinanoğlu (Bye Bye Türkçe)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir milletin bağımsızlığı, dilinin ve bilimsel düşünce kabiliyetinin bağımsızlığı ile başlar.", "source": "Prof. Dr. Oktay Sinanoğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir insanın anavatanı çocukluğudur; çocukluğunda sevgi ve saygı gören insan dünyayı güzelleştirir.", "source": "Prof. Dr. Doğan Cüceloğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmen bir cana dokunandır; o dokunuş bir insanın bütün kaderini değiştirebilir.", "source": "Prof. Dr. Doğan Cüceloğlu (Öğretmenim Bir Bakar Mısın?)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İletişim bilgi aktarımı değil; iki insanın birbirinin varlığını fark etmesi ve önemsemesidir.", "source": "Prof. Dr. Doğan Cüceloğlu (İletişim Donanımları)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Mükemmel çocuk yetiştirmeye çalışmayın; vicdanlı, sorumluluk sahibi ve mutlu insan yetiştirin.", "source": "Prof. Dr. Doğan Cüceloğlu (Geliştiren Anne-Baba)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İçindeki çocuğu kaybetmeyen bir öğretmen, sınıftaki her çocuğun dilinden anlar.", "source": "Prof. Dr. Üstün Dökmen", "icon": "📜"}, {"title": "Günün Sözü", "text": "Empati, karşındakinin ayakkabılarını giymek değil; onun kalbindeki sancıyı kendi içinde hissedebilmektir.", "source": "Prof. Dr. Üstün Dökmen", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kelimeler düşüncenin evidir; kelime hazinesi dar olanın düşünce ufku da daralır.", "source": "Alev Alatlı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Her yasal hak helal değildir; ahlak ve vicdan terazisi yasalardan her zaman daha hassastır.", "source": "Alev Alatlı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hayal gücü bilgiden daha önemlidir. Bilgi sınırlıdır; hayal gücü ise bütün dünyayı kuşatır ve ilerlemeye kapı aralar.", "source": "Albert Einstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrenmeyi bıraktığınız an ölmeye başlarsınız. Merak, var olmanın en temel gayesidir.", "source": "Albert Einstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Özel bir yeteneğim yok; sadece tutkulu bir meraklıyım.", "source": "Albert Einstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir problemi onu oluşturan bilinç düzeyiyle çözemezsiniz; daha üst bir kavrayışa sıçramalısınız.", "source": "Albert Einstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hiç hata yapmamış bir insan, yeni hiçbir şey denememiş demektir.", "source": "Albert Einstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir şeyi altı yaşındaki bir çocuğa basitçe anlatamıyorsanız, siz de onu tam anlamamışsınız demektir.", "source": "Albert Einstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmenin en yüce sanatı, yaratıcı ifadenin ve bilginin verdiği sevinci uyandırmaktır.", "source": "Albert Einstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitim, okulda öğrenilen her şey unutulduktan sonra geriye kalan şeydir.", "source": "Albert Einstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Önyargıları parçalamak, atom çekirdeğini parçalamaktan daha zordur.", "source": "Albert Einstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Evrende en anlaşılmaz şey, evrenin anlaşılabilir olmasıdır.", "source": "Albert Einstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğer daha ileriyi görebildiysem, bu devlerin omuzlarında durduğum içindir.", "source": "Sir Isaac Newton", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ben sadece hakikat okyanusunun sahilinde pürüzsüz çakıl taşları ve güzel deniz kabukları bulan küçük bir çocuk gibiyim.", "source": "Sir Isaac Newton", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir insana hiçbir şey öğretemezsiniz; sadece içindeki hakikati keşfetmesine yardımcı olabilirsiniz.", "source": "Galileo Galilei", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kâinat kitabı, matematik diliyle yazılmıştır; sembolleri üçgenler, daireler ve diğer geometrik şekillerdir.", "source": "Galileo Galilei (Il Saggiatore)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hayatta hiçbir şeyden korkulmamalıdır, sadece anlaşılmalıdır. Şimdi daha çok anlama zamanıdır, böylece daha az korkarız.", "source": "Marie Curie (Nobel Fizik ve Kimya Ödülleri)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanlığın bilimsel keşiflere ve merakını gidermeye ihtiyacı vardır; bilimin güzelliği ruhumuzu aydınlatır.", "source": "Marie Curie", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bırakın gelecek gerçeği söylesin ve herkesi eserine göre değerlendirsin. Şimdiki zaman onların olabilir ama gelecek benimdir.", "source": "Nikola Tesla", "icon": "📜"}, {"title": "Günün Sözü", "text": "Evrenin sırlarını bulmak istiyorsanız; enerji, frekans ve titreşim cinsinden düşünün.", "source": "Nikola Tesla", "icon": "📜"}, {"title": "Günün Sözü", "text": "Zihin yalnızken daha keskindir. Yalnız kalın, düşünün; icatların sırrı yalnızlıkta saklıdır.", "source": "Nikola Tesla", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlk prensip: Kendinizi kandırmamalısınız; zira kandırılması en kolay insan bizzat kendinizsiniz.", "source": "Richard Feynman (Nobel Fizik Ödülü)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir şeyi başka bir dilde veya kendi cümlelerinizle yeniden açıklayamıyorsanız, onu ezberlemişsiniz ama öğrenmemişsinizdir.", "source": "Richard Feynman", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilim, uzmanların cehaletine inanmaktır; yani her otoriteyi deney ve akılla yeniden sınamaktır.", "source": "Richard Feynman", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir yerlerde inanılmaz bir şey keşfedilmeyi bekliyor.", "source": "Carl Sagan (Cosmos)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilim sadece bir bilgi bütünü değil; bir düşünme ve sorgulama biçimidir.", "source": "Carl Sagan", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bizler yıldız tozuyuz; evrenin kendi kendini anlama ve tefekkür etme yoluyuz.", "source": "Carl Sagan", "icon": "📜"}, {"title": "Günün Sözü", "text": "Zekâ, değişime uyum sağlama yeteneğidir.", "source": "Stephen Hawking", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ayaklarınıza değil, gökyüzündeki yıldızlara bakın. Gördüğünüz şeyleri anlamlandırmaya çalışın ve evrenin varoluşunu sorgulayın.", "source": "Stephen Hawking", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilim hakikatin peşindedir, inanç ise anlamın peşindedir; ikisi de insan ruhunun tamamlayıcı kanatlarıdır.", "source": "Max Planck (Kuantum Teorisi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir fizik yasasını anlamak, doğanın fısıltısını duymak gibidir.", "source": "Niels Bohr", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrenmek zihni asla tüketmez; tam tersine onu daha da bileyip zenginleştirir.", "source": "Leonardo da Vinci", "icon": "📜"}, {"title": "Günün Sözü", "text": "Basitlik en yüksek gelişmişlik düzeyidir.", "source": "Leonardo da Vinci", "icon": "📜"}, {"title": "Günün Sözü", "text": "Pratiksiz teori boş bir hevestir; teorisiz pratik ise pusulasız gemi gibidir.", "source": "Leonardo da Vinci", "icon": "📜"}, {"title": "Günün Sözü", "text": "Düşünüyorum, öyleyse varım.", "source": "René Descartes (Yöntem Üzerine Konuşma)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sağduyu dünyada en adil paylaştırılmış şeydir; çünkü herkes onda payına düşenden razıdır.", "source": "René Descartes", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kalbin öyle mantıkları vardır ki akıl onları asla kavrayamaz.", "source": "Blaise Pascal (Düşünceler)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsan bir saz gibidir, tabiatın en zayıf sazı; ama o düşünen bir sazdır.", "source": "Blaise Pascal", "icon": "📜"}, {"title": "Günün Sözü", "text": "En güçlü olan tür değil, en zeki olan da değil; değişime en iyi uyum sağlayan tür hayatta kalır.", "source": "Charles Darwin", "icon": "📜"}, {"title": "Günün Sözü", "text": "Şans ancak hazırlıklı zihinlere güler.", "source": "Louis Pasteur", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilim sınır tanımaz; çünkü bilgi tüm insanlığın ortak mirası ve dünyayı aydınlatan meşalesidir.", "source": "Louis Pasteur", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ben başarısız olmadım; sadece işe yaramayan 10.000 yol buldum.", "source": "Thomas Edison", "icon": "📜"}, {"title": "Günün Sözü", "text": "Deha yüzde bir ilham, yüzde doksan dokuz alın teridir.", "source": "Thomas Edison", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bana anlatırsan unuturum, öğretirsen hatırlarım, beni dâhil edersen öğrenirim.", "source": "Benjamin Franklin", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilgiye yapılan yatırım en yüksek faizi öder.", "source": "Benjamin Franklin", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilgisayar bilimi sadece sayılarla ilgili değildir; düşüncenin sembolik mimarisini inşa etmektir.", "source": "Ada Lovelace (İlk Bilgisayar Programcısı)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bazen hiç kimsenin hayal edemediği şeyleri, hiç kimsenin hayal edemediği insanlar yapar.", "source": "Alan Turing (Modern Bilgisayarın Babası)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bildiğim tek şey, hiçbir şey bilmediğimdir.", "source": "Sokrates", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sorgulanmamış bir hayat, yaşanmaya değer değildir.", "source": "Sokrates (Savunma)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretim, zihne bilgi tıkıştırmak değil; zihinde saklı olan hakikati doğurtmaktır.", "source": "Sokrates (Maiötik Yöntem)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kimseye bir şey öğretemem; sadece onların düşünmesini sağlayabilirim.", "source": "Sokrates", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuğun aklı doldurulacak bir testi değil, tutuşturulacak bir meşaledir.", "source": "Plutarkhos", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitimin amacı, insanı güzeli sevmeye ve adalete saygı duymaya yöneltmektir.", "source": "Platon (Devlet)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocukları zorla ve baskıyla değil; sevdikleri oyunlarla eğitiniz ki ruhlarındaki gizli cevher parlasın.", "source": "Platon", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanın kendi kendini fethetmesi, zaferlerin en büyüğü ve en şereflisidir.", "source": "Platon", "icon": "📜"}, {"title": "Günün Sözü", "text": "Karanlıktan korkan bir çocuğu kolayca affedebilirsiniz; hayatın gerçek trajedisi, yetişkinlerin ışıktan korkmasıdır.", "source": "Platon", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitimin kökleri acı, fakat meyveleri pek tatlıdır.", "source": "Aristoteles", "icon": "📜"}, {"title": "Günün Sözü", "text": "Zihni eğitip kalbi eğitmemek, hiç eğitim vermemek demektir.", "source": "Aristoteles (Nikomakhos'a Etik)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Biz neyi sürekli yapıyorsak oyuz; bu yüzden mükemmellik bir eylem değil, bir alışkanlıktır.", "source": "Aristoteles", "icon": "📜"}, {"title": "Günün Sözü", "text": "Umut, uyanık insanın rüyasıdır.", "source": "Aristoteles", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dostluk, iki ayrı bedende yaşayan tek bir ruhtur.", "source": "Aristoteles", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir yıl sonrasını düşünüyorsan tohum ek; on yıl sonrasını düşünüyorsan ağaç dik; yüz yıl sonrasını düşünüyorsan insan eğit.", "source": "Konfüçyüs", "icon": "📜"}, {"title": "Günün Sözü", "text": "Düşünmeden öğrenmek emek israfıdır; öğrenmeden düşünmek ise son derece tehlikelidir.", "source": "Konfüçyüs (Konuşmalar)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilgiye sahipseniz onu başkalarıyla paylaşın; bu ölümsüzlüğün tek yoludur.", "source": "Konfüçyüs", "icon": "📜"}, {"title": "Günün Sözü", "text": "Karanlığa küfredeceğine bir mum yak.", "source": "Konfüçyüs", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hata yapıp da onu düzeltmemek, işte asıl hata odur.", "source": "Konfüçyüs", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bin millik bir yolculuk bile tek bir adımla başlar.", "source": "Lao Tzu (Tao Te Ching)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Başkalarını bilen kimse bilgili, kendini bilen kimse ise bilgedir.", "source": "Lao Tzu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Suyun yumuşaklığı ve sabrı, en sert kayaları bile zamanla oyar.", "source": "Lao Tzu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir şeyi bilmek onu sevmenin, bir şeyi sevmek ise ona kendini adamanın yerini tutamaz.", "source": "Konfüçyüs", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretirken öğreniriz; başkasına aktarılan bilgi hafızada derin izler bırakır.", "source": "Seneca (Ahlak Mektupları)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Rüzgârın hangi yönden estiği değil, yelkenlerini nasıl açtığın önemlidir.", "source": "Seneca", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hayat bir tiyatro sahnesi gibidir; mühim olan oyunun uzunluğu değil, ne kadar iyi oynandığıdır.", "source": "Seneca", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sabah kalktığında hayatta olmanın, nefes almanın, düşünmenin ve sevmenin ne büyük bir ayrıcalık olduğunu hatırla.", "source": "Marcus Aurelius (Kendime Düşünceler)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Seni inciten şey dış olaylar değil; o olaylara yüklediğin kendi yargılarındır.", "source": "Marcus Aurelius", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanları üzen şey başlarına gelen hadiseler değil; o hadiseler hakkında besledikleri fikirlerdir.", "source": "Epiktetos (Söylevler)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yalnızca eğitimli olanlar gerçekten hürdür.", "source": "Epiktetos", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hedefi olmayan bir gemiye hiçbir rüzgâr yardım edemez.", "source": "Montaigne (Denemeler)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuğa bilgi yüklemek yerine, onda sağlam ve dürüst bir muhakeme kabiliyeti geliştirmek gerekir.", "source": "Montaigne (Çocukların Eğitimi Üzerine)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilgi güçtür.", "source": "Francis Bacon (Meditationes Sacrae)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Okumak insanı olgunlaştırır, konuşmak çevikleştirir, yazmak ise kusursuzlaştırır.", "source": "Francis Bacon (Denemeler)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Aklını kendin kullanma cesaretini göster! (Sapere Aude)", "source": "Immanuel Kant (Aydınlanma Nedir?)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsan ancak eğitimle insan olabilir; o ne ise eğitim onu öyle yapmıştır.", "source": "Immanuel Kant (Eğitim Üzerine)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocukluk, aklın ve bedenin kendi doğal ritminde büyümesi gereken mukaddes bir dönemdir.", "source": "Jean-Jacques Rousseau (Emile)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Doğa insanı iyi yaratmıştır; onu yozlaştıran yanlış kurumlar ve yapay terbiye anlayışıdır.", "source": "Jean-Jacques Rousseau", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tüm muhteşem hikâyeler iki şekilde başlar: Ya bir insan bir yolculuğa çıkar ya da şehre bir yabancı gelir.", "source": "Lev Tolstoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bütün mutlu aileler birbirine benzer; her mutsuz ailenin ise kendine has bir mutsuzluğu vardır.", "source": "Lev Tolstoy (Anna Karenina)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanı bedenen ameliyat etmek için bayıltmak gerekir; ruhen ameliyat etmek için ise uyandırmak gerekir.", "source": "Lev Tolstoy (İtiraflarım)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dünyayı değiştirmek isteyen çoktur; ama hiç kimse önce kendini değiştirmeyi düşünmez.", "source": "Lev Tolstoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dünyayı güzellik kurtaracak; bir insanı sevmekle başlayacak her şey.", "source": "Fyodor Dostoyevski (Budala)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Cehennem, sevmeyi beceremediğin ve sevgiden mahrum kaldığın yerdir.", "source": "Fyodor Dostoyevski (Karamazov Kardeşler)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Akıllı olmak tek başına bir işe yaramaz; onu doğru ve ahlaklı kullanacak bir yürek lazımdır.", "source": "Fyodor Dostoyevski (Suç ve Ceza)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilgi ancak paylaşıldığında bereketlenir; bilip de susmak zihinsel bir cimriliktir.", "source": "Anton Çehov", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gelecek, bugünden ona hazırlanan ve rüyalarına inanan cesur ruhlara aittir.", "source": "Victor Hugo (Sefiller)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir okul açan, bir hapishane kapatır.", "source": "Victor Hugo", "icon": "📜"}, {"title": "Günün Sözü", "text": "Fikri olgunlaşmış bir düşünceye karşı dünyadaki hiçbir ordu duramaz.", "source": "Victor Hugo", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilmek yetmez, uygulamak gerekir; istemek yetmez, yapmak gerekir.", "source": "Johann Wolfgang von Goethe", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir insanı olduğu gibi kabul ederseniz öyle kalır; olabileceği gibi muamele ederseniz o seviyeye yükselir.", "source": "Johann Wolfgang von Goethe", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuklarınıza bırakabileceğiniz sadece iki kalıcı miras vardır: Biri kökler, diğeri ise kanatlardır.", "source": "Johann Wolfgang von Goethe", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kendine güvenen bir ruh, imkânsızı mümkün kılar.", "source": "Friedrich Schiller", "icon": "📜"}, {"title": "Günün Sözü", "text": "Olmak ya da olmamak, işte bütün mesele bu.", "source": "William Shakespeare (Hamlet)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Altın parıldayan her şey cevher değildir; hakikat dış görünüşte değil özde saklıdır.", "source": "William Shakespeare", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuklarınız sizin çocuklarınız değildir; onlar bizzat Hayat'ın kendine olan özleminin oğulları ve kızlarıdır.", "source": "Halil Cibran (Ermiş - Çocuklar Üzerine)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmen, kendi bilgeliğinin evine girmeye zorlamaz; talebesini kendi aklının eşiğine götürür.", "source": "Halil Cibran (Ermiş - Öğretme Üzerine)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kelimelerin gücünü anlamadan insanların ve dünyanın gidişatını anlayamazsınız.", "source": "Halil Cibran", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ders verirken sadece bilgi vermeyiniz; hayatın ahengini ve doğanın şiirini hissettiriniz.", "source": "Rabindranath Tagore (Nobel Edebiyat Ödülü)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bulutlar hayatıma artık yağmur veya fırtına getirmek için değil, batan güneşime renk katmak için süzülüyor.", "source": "Rabindranath Tagore", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir insanın arkasında ne olduğu veya önünde ne olduğu hiç önemli değildir; asıl mühim olan içinde ne olduğudur.", "source": "Ralph Waldo Emerson", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitimin bütün sırrı, öğrenciye saygı duymakta yatar.", "source": "Ralph Waldo Emerson", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kendi yolunda cesaretle yürüyen bir insan, bütün dünyaya yeni bir patika açar.", "source": "Henry David Thoreau (Walden)", "icon": "📜"}, {"title": "Günün Sözü", "text": "En iyi hükümet en az hükmedendir; en iyi eğitim ise bireyin kendi iç disiplinini uyandırandır.", "source": "Henry David Thoreau", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gülün adı değişse de kokusu aynı kalır; hakikatin peşinden koşan isimlere değil öze bakar.", "source": "Antoine de Saint-Exupéry (Küçük Prens)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsan ancak yüreğiyle baktığı zaman doğruyu görebilir; gerçeğin mayası gözle görülmez.", "source": "Antoine de Saint-Exupéry (Küçük Prens)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gemi yapmak istiyorsan insanlara odun toplamayı ve iş bölüşmeyi öğretme; onlara uçsuz bucaksız denizin özlemini aşıla.", "source": "Antoine de Saint-Exupéry (Kale)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Her insanın hayatı, onu kendine ulaştıran mukaddes bir patikadır.", "source": "Hermann Hesse (Demian)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilgelik başkasına devredilemez; bir bilgenin aktarmaya çalıştığı bilgelik her zaman kulağa bir delilik gibi gelir.", "source": "Hermann Hesse (Siddhartha)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Düşünceler kelimeleri şekillendirir; kelimeler ise düşünceleri bozar veya aydınlatır.", "source": "George Orwell (1984)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Geçmişi kontrol eden geleceği kontrol eder; bugünü kontrol eden geçmişi kontrol eder.", "source": "George Orwell", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dünyanın en tehlikeli şeyi, samimi bir cehalet ve vicdansız bir zekâdır.", "source": "Martin Luther King Jr.", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitim kafayı doldurmak değil, zihni özgürleştirmektir.", "source": "Robert Maynard Hutchins", "icon": "📜"}, {"title": "Günün Sözü", "text": "Akıl bir meşaledir, kör için göz; ölü vücut için can, dilsiz için sözdür.", "source": "Yusuf Has Hacib (Kutadgu Bilig)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilgisiz insan meyvesiz ağaca benzer; ne gölgesi fayda verir ne meyvesi.", "source": "Yusuf Has Hacib (Kutadgu Bilig)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kişi bilgiyi öğrenmekle yücelir; bilgisiz insan ise baş köşede otursa dahi aşağıdadır.", "source": "Yusuf Has Hacib", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dilini gözet, başın esen kalsın; sözünü bilerek söyle, itibarın artsın.", "source": "Yusuf Has Hacib", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanın değeri edeptir; edep ise aklın dışarıdan görünen suretidir.", "source": "Yusuf Has Hacib", "icon": "📜"}, {"title": "Günün Sözü", "text": "Türk dili ve terbiyesi, asırları aşıp gelen kadim bir irfanın pınarıdır.", "source": "Kaşgarlı Mahmud (Divânu Lugâti't-Türk)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sözü bilerek söyleyen kemale erer; cahilin gevezeliği ise ancak kendine ziyan getirir.", "source": "Edip Ahmet Yükneki (Atabetü'l-Hakayık)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eski pamuk bez olmaz, eski düşman dost olmaz; mert olan sözünde durur.", "source": "Dede Korkut Kitabı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gönül Çalab'ın tahtı, Çalap gönüle baktı; iki cihan bedbahtı bir gönül yıkar ise.", "source": "Yunus Emre", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hükümdar adil olmalı, vezir ilim ehlini el üstünde tutmalı; mektepleri mamur olan memleket zeval bulmaz.", "source": "Nizamülmülk (Siyasetnâme)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir devletin ayakta kalması ilim ehlinin meclislerine ve adaletin terazisine bağlıdır.", "source": "Nizamülmülk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Usul esastan mukaddemdir; yöntemi yanlış olanın doğru neticeye ulaşması tesadüftür.", "source": "Ahmet Cevdet Paşa (Mecelle-i Ahkâm-ı Adliye)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tarih bilmeyen bir devlet adamı, pusulası olmayan kaptana benzer; gemiyi kayalıklara çarpar.", "source": "Ahmet Cevdet Paşa (Tarih-i Cevdet)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Def-i mefâsid celb-i menâfiden evlâdır; kötülüğü ve cehaleti defetmek, menfaat aramaktan önce gelir.", "source": "Ahmet Cevdet Paşa (Mecelle Kaideleri)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bütün ilimler bir tek hakikatin pencereleridir; tabiatı anlamak da insanı tanımak da hikmete çıkar.", "source": "Taşköprülüzâde (Miftâhu's-Sa'âde)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Talebe, hocasının ilmine hürmet etmeli; lakin hakikati hocasından da aziz bilmelidir.", "source": "Taşköprülüzâde", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kitaplar olmasaydı, insanlık asırların tecrübesini her nesilde yeniden aramak zorunda kalırdı.", "source": "Katip Çelebi (Keşfü'z-Zunûn)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gezdim dünyayı gördüm, hikmetin başı tevazu ve insana hizmettir.", "source": "Evliya Çelebi (Seyahatnâme)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlimsiz şiir harcı haramsız divar gibidir, bi-itibardır; temelinde ilim olmayan söz çöker.", "source": "Fuzûlî (Dîvân Mukaddimesi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dost bî-vefâ, felek bî-rahm, devrân bî-sükûn; dert çok, hem-dert yok, düşman kavî, tâli' zebûn.", "source": "Fuzûlî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Âvâzeyi bu âleme Dâvûd gibi sal; bâkî kalan bu kubbede bir hoş sadâ imiş.", "source": "Bâkî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hoşça bak zâtına kim zübde-i âlemsin sen; merdüm-i dîde-i ekvân olan âdemsin sen.", "source": "Şeyh Gâlib (Hüsn ü Aşk)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kişi noksanını bilmek gibi irfan olmaz; kendini bilen haddini de bilir.", "source": "Nâbî (Hayriyye)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Cehle sabretmek gibi güç dert olmaz; cahilin sohbeti ruhu soldurur.", "source": "Nâbî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Halk içinde muteber bir nesne yok devlet gibi; olmaya devlet cihanda bir nefes sıhhat gibi.", "source": "Kanuni Sultan Süleyman (Muhibbî)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Göz odur ki daima hakkı göre; akıl odur ki daima hayrı düşüne.", "source": "Süleyman Çelebi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmenlik, Anadolu'nun en ücra köyünde bile bir çocuğun gözündeki ışığı yakma sevdasıdır.", "source": "Reşat Nuri Güntekin (Çalıkuşu)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsan bir kere bir çocuğun kalbine dokundu mu, artık bütün dünya onun ailesi olur.", "source": "Reşat Nuri Güntekin (Acımak)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir milleti bölmek isteyenler önce tarihini ve değerlerini unutturmaya çalışır.", "source": "Tarık Buğra (Küçük Ağa)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmenler sınıflarında sadece ders anlatmaz; milletin birliğini ve dirliğini örer.", "source": "Tarık Buğra (Osmancık)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İçimizdeki şeytan pek de kurnaz değildir; o sadece bizim tembelliğimizden ve gafletimizden beslenir.", "source": "Sabahattin Ali (İçimizdeki Şeytan)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir kitabı okurken geçen iki saat, ömrümün en bereketli ve en derin saatleridir.", "source": "Sabahattin Ali (Kürk Mantolu Madonna)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yazmak, içimdeki sevgiyi ve insanlara olan muhabbeti paylaşmanın tek yoluydu.", "source": "Sait Faik Abasıyanık", "icon": "📜"}, {"title": "Günün Sözü", "text": "Milleti terakki ettirmenin (ilerletmenin) tek yolu, mektepleri çoğaltmak ve okuma şevkini yaymaktır.", "source": "Ahmet Mithat Efendi (Hace-i Evvel)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hakiki vatanperver, gençliği cehaletten kurtarmak için gece gündüz kalem oynatandır.", "source": "Namık Kemal", "icon": "📜"}, {"title": "Günün Sözü", "text": "Fikri hür, irfanı hür, vicdanı hür bir şair olarak ancak hakkın emrindeyim.", "source": "Tevfik Fikret (Haluk'un Defteri)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Türkçe bizim can damarımızdır; onu yabancı kaidelerin esaretinden kurtarmak milli borçtur.", "source": "Ömer Seyfettin (Yeni Lisan)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tarih, milletlerin hafızasıdır; hafızasını kaybeden milletler kimliğini de kaybeder.", "source": "Prof. Dr. Halil İnalcık (Tarihçilerin Kutbu)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Geleceği doğru kurmak istiyorsanız arşivlere ve belgelere hürmet ediniz; hamasetle tarih yazılmaz.", "source": "Prof. Dr. Halil İnalcık", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir kütüphane bir milletin hafızasıdır. Kütüphanesiz üniversite, ordusuz devlete benzer.", "source": "Prof. Dr. İlber Ortaylı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Okumayan nesil düşünemez; düşünemeyen nesil ise her propagandanın kurbanı olur.", "source": "Prof. Dr. İlber Ortaylı (Bir Ömür Nasıl Yaşanır?)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuklarınıza yabancı dil öğretmeden önce kendi Türkçelerini doğru, zengin ve kusursuz konuşmayı öğretin.", "source": "Prof. Dr. İlber Ortaylı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Matematik ve felsefe olmadan derin bir medeniyet tasavvuru inşa edilemez.", "source": "Prof. Dr. İhsan Fazlıoğlu (Kendini Aramak)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Soru sormasını bilmeyen bir zihin, ancak başkalarının ürettiği cevapların bekçisi olur.", "source": "Prof. Dr. İhsan Fazlıoğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitim bir kalıp dökme işi değil; fıtratı keşfedip onu en güzel surette inkişaf ettirme sanatıdır.", "source": "Prof. Dr. Sadettin Ökten (İçimde Ahenk Dolu)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Şehir insanın aynasıdır; medeni insan, yaşadığı mekânı güzelleştiren ve orada ruh inşa edendir.", "source": "Prof. Dr. Sadettin Ökten", "icon": "📜"}, {"title": "Günün Sözü", "text": "Felsefe-bilim, varlığı bir bütün olarak anlama ve ahlaki sorumlulukla hayata geçirme cehdidir.", "source": "Prof. Dr. Teoman Duralı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kendi kavramlarıyla düşünmeyen bir millet, başka medeniyetlerin zihinsel sömürgesi olmaktan kurtulamaz.", "source": "Prof. Dr. Teoman Duralı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kelamın güzelliği dinleyenin kalbinde, amelın güzelliği ise başkasına verdiği huzurda saklıdır.", "source": "Prof. Dr. Mahmut Erol Kılıç", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ahlak bilinci olmadan edinilen her akademik unvan, insanı ancak kibirde ve bencillikte derinleştirir.", "source": "Prof. Dr. Kenan Gürsoy", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gül yetiştiren insan, eline diken battı diye güle küsmez; öğretmen de öğrencisinden asla vazgeçmez.", "source": "Rasim Özdenören (Gül Yetiştiren Adam)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kafası karışık olan insan hakikati arıyor demektir; tehlikeli olan, körü körüne ezbere bağlanan zihindir.", "source": "Rasim Özdenören (Kafası Karışıklar İçin Kılavuz)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sevgiyle atılmayan hiçbir tohum, tarihin toprağında asırlık bir çınar olamaz.", "source": "İskender Pala (Katre-i Matem)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kitaplar sessiz öğretmenlerdir; kırmadan, incitmeden en derin sırları fısıldarlar.", "source": "İskender Pala", "icon": "📜"}, {"title": "Günün Sözü", "text": "Şiir kelimelerin musikisi, dilin ise en zarif doruk noktasıdır.", "source": "Hilmi Yavuz", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gizli bahçenizde açan çiçekleri fark etmek ve onları sulamak öğretmenin en asil vazifesidir.", "source": "Behçet Necatigil", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ne hasta bekler sabahı, ne taze ölüyü mezar; ne de şeytan bir günahı, seni beklediğim kadar.", "source": "Necip Fazıl Kısakürek (Beklenen)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Anlamak sevgiyi doğurur; sevgisiz bilgi ise ruhu kurutan bir kum fırtınasıdır.", "source": "Cahit Zarifoğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gökyüzüne bakmayı unutan nesiller, yeryüzünün çamuruna esir olurlar.", "source": "Erdem Bayazıt", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sana şahdamarından daha yakın bir Yaradan varken, kederlenmek ve ümitsizliğe düşmek niye?", "source": "Nuri Pakdil (Bağlanma)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yürüyüşümüz hakikate doğrudur; durmak yok, yola devam!", "source": "Nuri Pakdil", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğer bahçeniz ve kütüphaneniz varsa, ihtiyaç duyacağınız her şeye sahipsiniz demektir.", "source": "Cicero", "icon": "📜"}, {"title": "Günün Sözü", "text": "Minnettarlık sadece erdemlerin en büyüğü değil, aynı zamanda diğer bütün erdemlerin de anasıdır.", "source": "Cicero", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir vatanın geleceği, gençlerinin alacağı terbiye ve eğitime bağlıdır.", "source": "Cicero", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmen talebesine bir baba gibi şefkat göstermeli, ne aşırı sert ne de laubali olmalıdır.", "source": "Marcus Fabius Quintilianus (Institutio Oratoria)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çocuklara dinlenme ve oyun fırsatı tanıyınız; çünkü sürekli gerilen yay kırılır.", "source": "Quintilianus", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanlar doğmaz, eğitimle insan olurlar; terbiye ham madeni cevhere dönüştürür.", "source": "Desiderius Erasmus (Çocukların Eğitimi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Körler diyarında tek gözlü adam kral olur; cehaletin yaygın olduğu yerde küçük bir bilgi bile parlar.", "source": "Erasmus (Deliliğe Övgü)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ağlamamak, öfkelenmemek, nefret etmemek; sadece anlamak gerekir.", "source": "Baruch Spinoza (Etika)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Barış, savaşın olmaması demek değildir; o ruhun erdeminden doğan bir kuvvettir.", "source": "Baruch Spinoza", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yeni doğan bir çocuğun zihni boş bir levhadır (tabula rasa); tecrübe ve eğitim o levhayı doldurur.", "source": "John Locke (İnsan Anlığı Üzerine Bir Deneme)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sağlam kafa sağlam vücutta bulunur; eğitimin temeli beden sağlığı ve disiplinli bir alışkanlıktır.", "source": "John Locke (Eğitim Üzerine Düşünceler)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmenin en büyük marifeti, öğrencinin dikkatini zorlamadan diri tutabilmesidir.", "source": "John Locke", "icon": "📜"}, {"title": "Günün Sözü", "text": "Başkalarının hatalarından ders alınız; zira hepsini bizzat kendiniz yapacak kadar uzun yaşayamazsınız.", "source": "Eleanor Roosevelt", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanoğlunun en derin arzusu, takdir edilmek ve önemsenmektir.", "source": "William James (Öğretmenlerle Konuşmalar)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir düşünce ekersiniz bir eylem biçersiniz; bir eylem ekersiniz bir alışkanlık biçersiniz; bir alışkanlık ekersiniz bir karakter biçersiniz; bir karakter ekersiniz bir kader biçersiniz.", "source": "William James", "icon": "📜"}, {"title": "Günün Sözü", "text": "Korkunun ve endişenin en büyük panzehiri, şevkle bir eyleme girişmektir.", "source": "William James", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dünyanın sorunu, akıllılar şüpheyle doluyken aptalların kendilerinden son derece emin olmalarıdır.", "source": "Bertrand Russell", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitimin amacı dogma aşılamak değil; zihni bağımsız ve eleştirel sorgulamaya alıştırmaktır.", "source": "Bertrand Russell (Eğitim ve İyi Yaşam)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hiçbir zaman inançlarım için ölemem; çünkü yanılıyor olabilirim.", "source": "Bertrand Russell", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dilimin sınırları, dünyamın sınırlarıdır.", "source": "Ludwig Wittgenstein (Tractatus Logico-Philosophicus)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Üzerinde konuşulamayan konuda susmalı; susulan yerde ise tefekkür başlamalıdır.", "source": "Ludwig Wittgenstein", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gerçek cehalet bilginin yokluğu değil; onu öğrenmeyi reddetmektir.", "source": "Karl Popper (Açık Toplum ve Düşmanları)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir teorinin bilimsel olmasının tek kriteri, yanlışlanabilir olmasıdır.", "source": "Karl Popper", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kendini bilmek bütün bilgeliğin başlangıcıdır.", "source": "Aristoteles", "icon": "📜"}, {"title": "Günün Sözü", "text": "Cebir, bilinmeyeni bilinenler vasıtasıyla aydınlığa kavuşturma sanatıdır.", "source": "Hârizmî (El-Cebr ve'l-Mukâbele)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sıfır bir hiçlik değil; bütün sayıların değerini katlayan ve yerini belirleyen muazzam bir dengedir.", "source": "Hârizmî (Hint Hesabı Üzerine)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Işık düz çizgiler halinde yayılır; görme, gözden çıkan ışınla değil, cisimden gelen ışığın göze girmesiyle olur.", "source": "İbnü'l-Heysem (Kitâbü'l-Menâzır - Optik Kitabı)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hakikati arayan kimse, okuduğu her kitaba karşı kendini bir hâkim gibi konumlandırmalı, her iddiayı delille sınamalıdır.", "source": "İbnü'l-Heysem", "icon": "📜"}, {"title": "Günün Sözü", "text": "Mekanik düzenekler ve su saatleri, insanın aklıyla tabiatın güçlerini birleştirmesinin eseridir.", "source": "El-Cezerî (Kitâb-ül-Hiyel - Robotik Öncüsü)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tatbikata (uygulamaya) dönüştürülmeyen her teknik ilim, doğru ile yanlış arasında asılı kalır.", "source": "El-Cezerî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bana bir dayanak noktası verin, dünyayı yerinden oynatayım.", "source": "Arşimet", "icon": "📜"}, {"title": "Günün Sözü", "text": "Geometriye giden kestirme bir kral yolu yoktur; sebatla ve terle öğrenilir.", "source": "Öklid (Elementler)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sayılar evreni yönetir; her şey sayıdır ve evrende matematiksel bir armoni hüküm sürer.", "source": "Pisagor", "icon": "📜"}, {"title": "Günün Sözü", "text": "Düşünme hakkınızı koruyunuz; zira yanlış düşünmek bile hiç düşünmemekten evladır.", "source": "Hypatia (İskenderiyeli Matematikçi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yıldızların yörüngesini hesaplamak, ilahi nizamın kusursuzluğunu matematik diliyle tasdik etmektir.", "source": "Uluğ Bey (Zîc-i Uluğ Bey)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Güneş merkezdedir ve gezegenler elips şeklinde yörüngelerde döner; kâinatın geometrisi kusursuzdur.", "source": "Johannes Kepler (Göklerin Harmonisi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tabiatta hiçbir şey yoktan var olmaz, hiçbir şey de vardan yok olmaz; her şey sadece dönüşür.", "source": "Antoine Lavoisier (Modern Kimyanın Babası)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Elektrik ve manyetizma birbirini doğuran tek bir kuvvettir; tabiatın kanunları hayranlık uyandırıcı bir sadeliktedir.", "source": "Michael Faraday", "icon": "📜"}, {"title": "Günün Sözü", "text": "Çalış, bitir, yayınla; bilimin en temel üç kuralı budur.", "source": "Michael Faraday", "icon": "📜"}, {"title": "Günün Sözü", "text": "Işık, elektromanyetik bir dalgadır; denklemlerin zarafeti gerçeğin ta kendisini fısıldar.", "source": "James Clerk Maxwell", "icon": "📜"}, {"title": "Günün Sözü", "text": "Rüyamda elementlerin belirli bir nizam içinde sıralandığı bir tablo gördüm; uyandığımda bunu kâğıda döktüm.", "source": "Dmitri Mendeleyev (Periyodik Tablo)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Matematik bilimlerin kraliçesidir, sayılar teorisi ise matematiğin kraliçesidir.", "source": "Carl Friedrich Gauss", "icon": "📜"}, {"title": "Günün Sözü", "text": "Az ama olgun; bir bilim insanının eserleri sayıca çok değil, nitelikçe mükemmel olmalıdır.", "source": "Carl Friedrich Gauss", "icon": "📜"}, {"title": "Günün Sözü", "text": "Körleştiğimde daha az dikkat dağıtıcı unsur olacak dedim; zihnim matematiğin aydınlığında ışıldamaya devam etti.", "source": "Leonhard Euler", "icon": "📜"}, {"title": "Günün Sözü", "text": "Matematik, farklı şeylere aynı ismi verme sanatıdır.", "source": "Henri Poincaré", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilemeyiz, bilmek zorundayız! Bilim asla durmayacak ve araştırmaya devam edecektir.", "source": "David Hilbert", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanın elinden her şeyini alabilirsiniz; sadece bir şeyi alamazsınız: Her koşulda kendi tavrını seçme özgürlüğü.", "source": "Viktor Frankl (İnsanın Anlam Arayışı)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yaşamak için bir 'neden'i olan insan, hemen her 'nasıl'a katlanabilir.", "source": "Viktor Frankl (Nietzsche'den Alıntıyla)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Başarıyı hedeflemeyin; başarı, bir amaca adanmanın kendiliğinden gelen bir yan ürünüdür.", "source": "Viktor Frankl", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sevgi bir duygu değil, bir sanattır; bilgi, çaba ve sürekli bir olgunlaşma gerektirir.", "source": "Erich Fromm (Sevme Sanatı)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğitim çocuğa kendi potansiyelini gerçekleştirmeyi öğretmeli; onu başkalarının kopyası yapmamalıdır.", "source": "Erich Fromm", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir insan ancak koşulsuz kabul edildiğini ve anlaşıldığını hissettiğinde değişmeye ve gelişmeye başlar.", "source": "Carl Rogers (Kişi Olmaya Dair)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İyi bir hayat bir varış noktası değil, devam eden dinamik bir süreçtir.", "source": "Carl Rogers", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir insan ne olabiliyorsa, o olmalıdır; kendini gerçekleştirme insanın en temel içsel güdüsüdür.", "source": "Abraham Maslow (İnsan Motivasyonu Kuramı)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Elinizde sadece bir çekiç varsa, her şeyi bir çivi gibi görmeye başlarsınız.", "source": "Abraham Maslow", "icon": "📜"}, {"title": "Günün Sözü", "text": "Duygusal zekâ, IQ'dan çok daha belirleyicidir; kendi duygularını yöneten ve empati kuran insan hayatta başarılı olur.", "source": "Daniel Goleman (Duygusal Zekâ)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrenmenin gerçekleşmesi için önce çocuğun duygusal beyninin (amigdala) kendini güvende hissetmesi gerekir.", "source": "Daniel Goleman", "icon": "📜"}, {"title": "Günün Sözü", "text": "Akış (Flow) hali, insanın yetenekleriyle görevin zorluğu tam dengelendiğinde ortaya çıkan en üst odaklanmadır.", "source": "Mihaly Csikszentmihalyi (Akış)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dünyayı değiştirmek için kullanabileceğiniz en güçlü silah eğitimdir.", "source": "Nelson Mandela", "icon": "📜"}, {"title": "Günün Sözü", "text": "Özgür olmak sadece birinin zincirlerini kırmak değil; başkalarının özgürlüğüne saygı duyacak şekilde yaşamaktır.", "source": "Nelson Mandela", "icon": "📜"}, {"title": "Günün Sözü", "text": "Örnek olmak başkalarını etkilemenin en iyi yolu değildir; tek yoludur.", "source": "Albert Schweitzer (Nobel Barış Ödülü)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hayatta en güzel şey, bir başkasının yükünü hafifletebilmektir.", "source": "Albert Schweitzer", "icon": "📜"}, {"title": "Günün Sözü", "text": "Karakter kolay ve sessiz yoldan gelişemez; ancak çile ve ıstırapla ruh kuvvetlenir, vizyon netleşir.", "source": "Helen Keller", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dünyadaki en güzel ve en değerli şeyler ne görülebilir ne de dokunulabilir; onlar sadece kalple hissedilir.", "source": "Helen Keller", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir çocuk, bir öğretmen, bir kitap ve bir kalem bütün dünyayı değiştirebilir.", "source": "Malala Yousafzai (Nobel Barış Ödülü)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Karanlığı karanlıkla kovamazsınız, bunu ancak ışık yapabilir. Nefreti nefretle kovamazsınız, bunu ancak sevgi yapabilir.", "source": "Martin Luther King Jr.", "icon": "📜"}, {"title": "Günün Sözü", "text": "Eğer uçamıyorsan koş, koşamıyorsan yürü, yürüyemiyorsan sürün; ama ne yaparsan yap ilerlemeye devam et.", "source": "Martin Luther King Jr.", "icon": "📜"}, {"title": "Günün Sözü", "text": "Göz göze misilleme yapmak bütün dünyayı kör eder.", "source": "Mahatma Gandhi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dünyada görmek istediğin değişimin kendisi ol.", "source": "Mahatma Gandhi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Yarın ölecekmiş gibi yaşa, hiç ölmeyecekmiş gibi öğren.", "source": "Mahatma Gandhi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sözleriniz inançlarınızı, inançlarınız düşüncelerinizi, düşünceleriniz eylemlerinizi, eylemleriniz ise kaderinizi belirler.", "source": "Mahatma Gandhi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ağaç yaş iken eğilir; çocuk yaşta verilen ahlak ve edep bir ömür boyu silinmez.", "source": "Kadim Türk Atasözü", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bin bilsen de bir bilene danış; istişare aklın zekâtıdır.", "source": "Kadim Türk Atasözü", "icon": "📜"}, {"title": "Günün Sözü", "text": "İşleyen demir ışıldar; tembellik pas, gayret ise cevher üretir.", "source": "Kadim Türk Atasözü", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tatlı dil yılanı deliğinden çıkarır; nezaket kalplerin anahtarıdır.", "source": "Kadim Türk Atasözü", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim rütbesi rütbelerin en yücesidir; zira diğer rütbeler zamanla solar, ilim ise ebedidir.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kendini başkalarıyla kıyaslama; sadece dünkü halinle bugünkü halini kıyasla.", "source": "Jordan Peterson", "icon": "📜"}, {"title": "Günün Sözü", "text": "Merak bir kas gibidir; kullandıkça güçlenir ve derinleşir.", "source": "Ian Leslie (Merak)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Zorluklar insanı yıldırmamalı; elmas yüksek basınç altında parıldamaya başlar.", "source": "Anonim Hikmet", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sabır boyun eğmek değil; mücadelenin ve ümidin zamana yayılmış adıdır.", "source": "İmam Şafiî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrenciye bir pusula veriniz; haritayı kendisi çizsin.", "source": "Modern Eğitim İlkesi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gülümsemek, iki insan arasındaki en kısa mesafedir.", "source": "Victor Borge", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir öğretmenin bıraktığı etki sonsuzluğa uzanır; nerede biteceğini asla kestiremezsiniz.", "source": "Henry Adams", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir çocuğun kalbinde yaktığınız meşale, karanlık çağları bile aydınlatacak kadar güçlüdür.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bu vatan toprağın kara bağrında, sıradağlar gibi duranlarındır; bir tarih boyunca onun uğrunda, kendini tarihe verenlerindir.", "source": "Orhan Şaik Gökyay (Bu Vatan Kimin)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bize güç ver cihat meydanını pehlivansız bırakma Allah'ım! Bizi sen sevgisiz, susuz, havasız ve vatansız bırakma Allah'ım!", "source": "Arif Nihat Asya (Dua)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ey mavi göklerin beyaz ve kızıl süsü, kız kardeşimin gelinliği, şehidimin son örtüsü...", "source": "Arif Nihat Asya (Bayrak)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir milletin dili o milletin evidir; dili tahrip olan bir milletin düşüncesi de vatanı da tehlikededir.", "source": "Prof. Dr. Necmettin Hacıeminoğlu (Türkçenin Karanlık Günleri)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Milli kültür, bir milletin asırlar boyunca biriktirdiği ahlak, sanat, inanç ve düşünce nizamıdır.", "source": "Prof. Dr. Erol Güngör (Kültür Değişmesi ve Milliyetçilik)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlmi zihniyet, peşin hükümleri bir kenara bırakıp hadiseleri tarafsız bir tenkit süzgecinden geçirmektir.", "source": "Prof. Dr. Mümtaz Turhan (Maarifimiz ve Gayesi)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gezmek insanı dilsiz bırakır, sonra da en iyi hikâye anlatıcısına dönüştürür.", "source": "İbn Battuta (Seyahatnâme)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Düşünmek direnmektir; kendi aklını ve vicdanını başkalarının ipoteğine vermemektir.", "source": "Ali Şeriati (Kendini Devrimci Yetiştirmek)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanın en büyük trajedisi, kendi elleriyle yaptığı putlara sonra bizzat secde etmesidir.", "source": "Ali Şeriati (İnsanın Dört Zindanı)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Batı medeniyeti maddi araçlarda devleşirken, insani ve ahlaki değerlerde cüceleşti.", "source": "Roger Garaudy (Geleceğimizde İslam Var)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gerçek hayat karşılaşmadır; iki insan birbiriyle kalpten ve samimiyetle karşılaştığında hakikat tecelli eder.", "source": "Martin Buber (Ben ve Sen)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bilim gerçeğin ta kendisini arar; çünkü kurgulanmış yalanlar er ya da geç çökmeye mahkûmdur.", "source": "Neil deGrasse Tyson (Astrofizik)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Merak duygusu bir çocuğun en değerli hazinesidir; onu söndüren her eğitim sistemi iflas etmiştir.", "source": "Neil deGrasse Tyson", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir çocuk soru sormayı bıraktığı gün, ruhu yaşlanmaya başlar.", "source": "Anonim Eğitim Özdeyişi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tahtaya yazılan bir denklem silinir, fakat öğrencinin kalbine yazılan şefkat silinmez.", "source": "Maarif İlkesi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrenciye dersi değil, öğrenmeyi öğretiniz; o zaman hayat boyu kendi yolunu kendisi aydınlatır.", "source": "Pedagojik Düstur", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gülümseyen bir öğretmenin sınıfında çiçekler erken açar.", "source": "Öğretmenlik Hikmeti", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hatalar, başarıya giden merdivenin basamaklarıdır; basamaksız yukarı çıkılamaz.", "source": "Öğrenme Psikolojisi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sabırla dinlemek, en güzel cevabın ve en derin muhabbetin anahtarıdır.", "source": "İletişim Sanatı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kelimeler birer tohumdur; gönül toprağına düşerse yeşerir, taşa düşerse kurur.", "source": "Kadim Hikmet", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmenlik, geçmişin mirasını geleceğin ümidine bağlayan en sağlam köprüdür.", "source": "Türkiye Maarif Modeli", "icon": "📜"}, {"title": "Günün Sözü", "text": "Adalet olmadıkça mektep kışlaya, ilim zulme, söz ise dedikoduya döner.", "source": "Şeyh Edebali", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir insana yardım ettiğinde onun yüzünde beliren sevinç, yeryüzünün bütün hazinelerinden daha kıymetlidir.", "source": "Yunus Emre", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kendi kusurunu gören insan, başkalarının hatasını araştırmaya vakit bulamaz.", "source": "Hz. Ali (r.a.)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim talebi beşikten mezara kadar süren kutlu bir seferdir.", "source": "İslam Maarif Anlayışı", "icon": "📜"}, {"title": "Günün Sözü", "text": "Büyük idealler küçük fedakârlıklarla gerçekleşmez; büyük hedeflere ancak sarsılmaz bir sebatla ulaşılır.", "source": "Ziya Gökalp", "icon": "📜"}, {"title": "Günün Sözü", "text": "Kitaplar olmasaydı, insan kendi asrının dar sokaklarında hapsolup kalırdı.", "source": "Ahmet Hamdi Tanpınar", "icon": "📜"}, {"title": "Günün Sözü", "text": "Vicdan, insanın içindeki ilahi adaletin sesidir.", "source": "İmam Gazali", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sevgi emekti; emek ise fedakârlık ve karşılıksız adanmışlıktı.", "source": "Cengiz Aytmatov (Selvi Boylum Al Yazmalım)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsan için en zor şey, her gün insan kalabilmektir.", "source": "Cengiz Aytmatov (Gün Olur Asra Bedel)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Köklerini unutan mankurtlar, efendilerinin kölesi olmaktan öteye gidemezler.", "source": "Cengiz Aytmatov", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir milletin edebiyatı o milletin vicdanıdır; edebiyatı susturulan milletin vicdanı da sağırlaşır.", "source": "Aleksandr Soljenitsin (Nobel Konuşması)", "icon": "📜"}, {"title": "Günün Sözü", "text": "Cesaret, korkunun olmaması değil; korkuya rağmen hakikat yolunda ilerleyebilme erdemidir.", "source": "Mark Twain", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gelecek, bugünden ona hazırlanan ve ideallerine inananlara aittir.", "source": "Eleanor Roosevelt", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğrenmenin sınırları ancak insanın kendi hayal gücünün sınırları kadardır.", "source": "Arthur C. Clarke", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlerlemenin sırrı, başlamaktır. Başlamanın sırrı ise karmaşık ve ezici görevleri küçük, yönetilebilir parçalara bölmektir.", "source": "Mark Twain", "icon": "📜"}, {"title": "Günün Sözü", "text": "Ne kadar bilirsen bil, söylediklerin karşındakinin anlayabileceği kadardır.", "source": "Mevlânâ Celâleddîn-i Rûmî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Dert insana yol gösterir; acı çeken ruh hakikatin kapısını daha çabuk aralar.", "source": "Mevlânâ Celâleddîn-i Rûmî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Sükûtun da bir sesi vardır; onu ancak gönül kulağı açık olanlar işitebilir.", "source": "Şems-i Tebrîzî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Hakk'ın karşına çıkardığı değişimlere direnmek yerine teslim ol. Nereden biliyorsun hayatın altının üstünden daha iyi olmadığını?", "source": "Şems-i Tebrîzî (Kırk Kural)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İlim insanın ufkunu açar, ahlak ise adımlarını sağlamlaştırır.", "source": "Hasan Âli Yücel", "icon": "📜"}, {"title": "Günün Sözü", "text": "Tarihini bilmeyen bir nesil, rüzgârın önündeki kuru yaprak gibi savrulmaya mahkûmdur.", "source": "Halil İnalcık", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gözünü hedeften ayırmayan okçu, rüzgârın uğultusuna aldırış etmez.", "source": "Kadim Okçuluk Risalesi", "icon": "📜"}, {"title": "Günün Sözü", "text": "Her yeni gün, temiz bir sayfa ve tertemiz bir başlangıçtır; onu en güzel amellerle nakşediniz.", "source": "İmam Rabbani (Mektubat)", "icon": "📜"}, {"title": "Günün Sözü", "text": "İnsanın kıymeti aradığı şey kadardır; hakikati arayan hakikat olur, dünyayı arayan dünya.", "source": "Mevlânâ Celâleddîn-i Rûmî", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gençlik bir kere yaşanır; onu ilimle, ahlakla ve memleket sevgisiyle taçlandırmak gerek.", "source": "Mustafa Kemal Atatürk", "icon": "📜"}, {"title": "Günün Sözü", "text": "Öğretmen sınıfa girdiğinde karanlıklar aydınlığa, cehalet ise yerini edep ve idrake bırakır.", "source": "Nurettin Topçu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Milletimizin mektepleri, medeniyetimizin tüten en sıcak ocaklarıdır.", "source": "Ziya Gökalp", "icon": "📜"}, {"title": "Günün Sözü", "text": "Bir çocuğa verilebilecek en büyük hediye, ona güvenmek ve ona inanmaktır.", "source": "Doğan Cüceloğlu", "icon": "📜"}, {"title": "Günün Sözü", "text": "Gönülden gönüle bir yol vardır görülmez; o yol ancak samimi muhabbetle yürünür.", "source": "Neşet Ertaş (Bozkırın Tezenesi)", "icon": "📜"}];
window.PIRTIL_WISDOM_TIPS = [{"title": "Günün Bilgisi", "text": "Türkiye Yüzyılı Maarif Modeli'nde daima 'Öğrenme Çıktısı' esastır. Amaç ezber bilgi depolamak değil; bilgiyi beceriye, beceriyi erdemli eyleme dönüştürmektir.", "source": "Maarif Modeli Temel Yaklaşımı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Erdem-Değer-Eylem Döngüsü: Maarif modelinde değerler izole bir ders olarak değil; tüm disiplinlerin içine yedirilmiş eylemsel tutumlar olarak işlenir.", "source": "Maarif Modeli Değerler Çerçevesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kavramsal Beceriler: Öğrencilerin sadece 'ne' olduğunu değil; 'nasıl', 'neden' ve 'hangi bağlamda' sorularını cevaplayabilmesi hedeflenir.", "source": "Maarif Modeli Beceri Çerçevesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Alan Becerileri ve Temel Kabiliyetler: Her dersin kendine has düşünme yöntemi (tarihsel empati, matematiksel modelleme, bilimsel sorgulama) ders içi eylemlere entegre edilir.", "source": "Maarif Modeli Program Tasarımı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Bütüncül (Holistik) Gelişim: Öğrencinin sadece zihinsel kapasitesi değil; ahlaki, duygusal, bedensel ve estetik boyutları bir bütün olarak geliştirilir.", "source": "Maarif Modeli Felsefesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Farklılaştırılmış Öğretim Yolu: Her sınıfta öğrenme hızları ve ilgileri farklıdır. Zenginleştirme (ileri düzey) ve destekleme (pekiştirme) rotalarıyla her öğrenci kendi zirvesine taşınır.", "source": "Öğretim Tasarımı İlkesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenme Çıktısı Hiyerarşisi: Bilgiyi hatırlama en alt basamaktır. Analiz, sentez, eleştirel değerlendirme ve özgün ürün ortaya koyma ise asıl hedeflenen üst düzey öğrenme çıktılarıdır.", "source": "Maarif Program Ölçütleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sosyo-Duygusal Beceriler (SDB): Öz farkındalık, öz yönetim, sosyal farkındalık, ilişki becerileri ve sorumlu karar verme; akademik başarı kadar hayat başarısını belirler.", "source": "Sosyo-Duygusal Öğrenme Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yerelden Evrensele Köprü: Kendi kültürel köklerini, Türkçesini ve medeniyet mirasını derinlemesine bilmeyen bir fert, evrensel bilim ve sanata özgün katkı sunamaz.", "source": "Maarif Kültür Tasavvuru", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Disiplinlerarası Geçişlilik: Matematik dersindeki bir grafik yorumlama becerisi, fen dersindeki veri analiziyle ve coğrafyadaki nüfus piramidiyle doğrudan ilişkilendirilir.", "source": "Bütünleşik Müfredat İlkesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Görsel Okuryazarlık: Günümüz öğrencisi metinden önce görseli tarar. Ders materyallerinde infografikler, şemalar ve zihin haritaları kullanmak kalıcılığı %60 artırır.", "source": "Çağdaş Materyal Tasarımı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Gelişim Zihniyeti (Growth Mindset): Öğrencilere beynin çalışan bir kas gibi pratik yaptıkça geliştiğini anlatın; zekânın doğuştan sabit bir sınır olmadığını kavrayan çocuk pes etmez.", "source": "Eğitim Psikolojisi Notu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenci Merkezli Keşif: Öğretmenin 40 dakika aralıksız konuştuğu derslerde öğrenme verimi %20'ye düşer. Öğretmen rehber, öğrenci ise aktif araştırmacı olmalıdır.", "source": "Aktif Öğretim Stratejisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öz Düzenlemeli Öğrenme: Öğrenciye haftalık hedeflerini kendisinin belirlemesi, planını takip etmesi ve gün sonunda kendini puanlaması alışkanlığını kazandırın.", "source": "Öğrenmeyi Öğrenme İlkesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Meta-biliş (Bilişüstü) Farkındalık: Öğrenciye 'Bu problemi çözerken kafanda ilk hangi adımı attın?' diye sorarak kendi düşünme sürecini fark etmesini sağlayın.", "source": "Bilişsel Pedagoji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Adalet Değeri Eğitimi: Sınıfta kuralların herkese eşit ve istisnasız uygulandığını gören çocuklarda adalet duygusu içselleşir.", "source": "Değerler Eğitimi Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Merhamet ve Yardımlaşma: Başarılı öğrencilerin zorlanan arkadaşlarına ders anlatmasını sağlayan akran koçluğu, iki tarafın da empati ve bilgisini pekiştirir.", "source": "Sosyal Değerler Notu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sorumluluk Bilinci: Sınıftaki küçük görevler (tahta temizliği, kütüphane düzeni, bitki bakımı) öğrencilere dönüşümlü verilerek aidiyet ve sorumluluk inşa edilir.", "source": "Sınıf İklimi Oluşturma", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tasarruf ve Çevre Bilinci: Kağıt israfını önleme, atıkları ayrıştırma ve ışıkları söndürme alışkanlığı derslerde somut uygulamalarla pekiştirilmelidir.", "source": "Sürdürülebilir Maarif", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Vatanseverlik ve Milli Üretim: Fen ve bilişim derslerinde yerli teknoloji projeleri (TÜBİTAK, TEKNOFEST, TUA) örnek verilerek öğrencilere özgüven aşılanmalıdır.", "source": "Milli Teknoloji Hamlesi Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Estetik ve Zarafet Eğitimi: Ders defterlerinin düzeninden sınıf panosunun renk uyumuna kadar her ayrıntı, çocuğun estetik beğenisini şekillendirir.", "source": "Sanatsal Duyarlılık Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dürüstlük ve Akademik Etik: Ödevlerde kaynak gösterme ve kopya çekmeme bilinci ilkokuldan itibaren bir onur meselesi olarak işlenmelidir.", "source": "Akademik Dürüstlük İlkeleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sabır ve Sebat (Grit): Zorlu bir matematik problemi veya uzun bir araştırma projesinde pes etmeden devam edebilme gücü, başarının en temel anahtarıdır.", "source": "Angela Duckworth - Azim Kuramı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Saygı ve Nezaket Dili: Sınıfta 'Lütfen', 'Teşekkür ederim', 'Özür dilerim' ifadelerini öğretmen ne kadar sık kullanırsa, sınıfın genel dili o kadar nezaketle bezenir.", "source": "Model Olma Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kritik Düşünme Egzersizi: Öğrencilere okudukları bir haber veya metinde 'Yazarın amacı ne? Hangi kanıtları sunuyor? Başka hangi bakış açıları olabilir?' sorularını sordurun.", "source": "Eleştirel Düşünme Becerisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Problem Çözme Basamakları: Sorunu tanımla -> Verileri topla -> Alternatif hipotezler kur -> Çözümü dene -> Sonucu test et. Bu döngü her disiplinde geçerlidir.", "source": "Bilimsel Yöntem Metodolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Soru Sorma Sanatı: Öğrencilerinize 'Anladınız mı?' diye sormak yerine 'Bu konuda kafanızı en çok ne karıştırdı?' diye sorun. İlk soruya herkes evet der, ikinci soru düşünmeyi başlatır.", "source": "Etkili Soru Sorma Stratejisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ters Yüz Edilmiş Öğrenme (Flipped Classroom): Temel teorik bilgiyi kısa bir video veya okuma parçasıyla eve verip, sınıf saatini tamamen tartışma ve problem çözmeye ayırın.", "source": "Harmanlanmış Öğrenme Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenme İstasyonları: Sınıfta farklı öğrenme stillerine hitap eden masalar kurun (Görsel İstasyon, Metin Analizi İstasyonu, Uygulama İstasyonu). Gruplar dönüşümlü çalışsın.", "source": "Farklılaştırılmış Eğitim Metodu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Oyunlaştırma (Gamification): Derse küçük puanlama sistemleri, görev rozetleri ve seviye atlama dinamikleri eklemek içsel motivasyonu ve odaklanmayı katbekat artırır.", "source": "Eğitimde Oyunlaştırma", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenme Günlüğü (Reflection Journal): Haftanın son dersinde öğrencilere 5 dakika 'Bu hafta öğrendiğim en şaşırtıcı şey neydi?' diye yazdırın; öğrenilenler kalıcı belleğe geçer.", "source": "Yansıtıcı Düşünme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çoklu Zekâ Dokunuşu: Bir konuyu sadece sözel anlatmayın; görsel bir şema, sayısal bir mantık, ritmik bir vurgu veya bedensel bir canlandırma ile destekleyin.", "source": "Howard Gardner Yaklaşımı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ön Bilgileri Harekete Geçirme: Yeni bir konuya girmeden önce K-W-L (Biliyorum - Merak Ediyorum - Öğrendim) tablosu doldurtmak zihni yeni bilgiye açar.", "source": "Bilişsel Köprü Kurma", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Anlamlı Öğrenme (David Ausubel): Yeni bilginin kalıcı olması için öğrencinin mevcut bilişsel yapısındaki eski bilgilerle sağlam bağlar kurması şarttır.", "source": "Bilişsel Öğrenme Kuramı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenme Çıktısı Odaklı Rubrik: Not verirken öğrencinin kişiliğini değil, rubrikte tanımlanan somut ölçütleri esas alın; böylece öğrenci neyi geliştirmesi gerektiğini net görür.", "source": "Objektif Değerlendirme İlkesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Gelişim Dosyası (Portfolyo): Öğrencinin dönem başından sonuna kadar yaptığı en iyi çalışmaları bir dosyada toplaması, kendi ilerleyişini görmesini sağlar ve özsaygısını yükseltir.", "source": "Bütüncül Değerlendirme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Açık Uçlu Sınav Analizi: Yazılı sınavlarda sadece doğru cevaba puan vermeyin; çözüm yolundaki mantıklı adımlara ara puan vererek süreci ödüllendirin.", "source": "MEB Ölçme ve Değerlendirme Kılavuzu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kendini Değerlendirme (Self-Assessment): Öğrenci kendi ödevini teslim etmeden önce belirlenen kontrol listesiyle kontrol ederse, otokontrol ve sorumluluk becerisi gelişir.", "source": "Öz Değerlendirme Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dönüt Zamanlaması: Yapılan bir sınav veya ödevin geri bildirimi ne kadar gecikirse etkisi o kadar azalır. En etkili dönüt, ilk 24-48 saat içinde verilen dönüttür.", "source": "Geri Bildirim Psikolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Grup Çalışmasında Rol Dağılımı: Grup ödevlerinde herkesin somut bir rolü olsun (Lider, Sözcü, Zaman Tutucu, Raportör, Materyal Sorumlusu); böylece bir kişinin sırtına yük binmez.", "source": "İşbirlikçi Öğrenme Dinamiği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hata Odaklı Öğrenme: Sınıfta yapılan hataları kınamak yerine 'Bu harika bir hata, çünkü bize çok önemli bir kuralı hatırlattı' diyerek sınıfta psikolojik güvenlik alanı oluşturun.", "source": "Pozitif Öğrenme İklimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Disiplinlerarası STEM Tasarımı: Bir köprü modeli yaptırtırken hem fen (kuvvet-denge), hem matematik (açı-uzunluk), hem teknoloji hem de sanat unsurlarını birleştirin.", "source": "Bütünleşik STEM Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kavram Karikatürü ile Başlama: Tahtaya iki farklı görüş savunan iki karikatür karakteri çizin ve öğrencilere 'Sizce hangisi haklı, neden?' diye sorarak tartışma başlatın.", "source": "Kavram Karikatürleri Metodu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf İçi Demokrasi Kültürü: Sınıf kurallarını sene başında öğretmen tek başına dikte etmemeli; öğrencilerle birlikte tartışarak ortak kararla panoya asmalıdır.", "source": "Demokratik Sınıf Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenciye İsmiyle Hitap Etmek: İsmiyle hitap edilen öğrencinin beyninde limbik sistem güven sinyali üretir; bağ kurma ve dinleme isteği anında artar.", "source": "Nöro-Pedagoji Notu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dijital Ayak İzi Farkındalığı: Öğrencilere sosyal medyada paylaştıkları her bilginin kalıcı bir dijital iz bıraktığını ve ilerideki hayatlarını etkileyebileceğini kavratın.", "source": "Dijital Vatandaşlık Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kütüphane Kültürü: Ayda en az bir dersi okul kütüphanesinde işleyin; rafların arasında kitap kokusunu içine çeken çocukta kitap sevgisi somutlaşır.", "source": "Okuma Kültürü İnşası", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Bilinçli Teknoloji Kullanımı: Akıllı tahta bir TV ekranı değildir; interaktif simülasyonlar, 3D modeller ve keşif araçları için kullanılmalıdır.", "source": "Eğitim Teknolojileri İlkesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sosyal Sorumluluk Projeleri: Öğrencileri bir huzurevi ziyareti, fidan dikimi veya sokak hayvanlarına yardım projesine dâhil etmek kalplerinde merhamet filizlendirir.", "source": "Toplumsal Hizmet Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kültürel Miras Gezileri: Tarih ve medeniyet derslerini sınıftan çıkarıp müzelere, tarihi camilere ve ören yerlerine taşımak bilgiyi somut ve unutulmaz kılar.", "source": "Mekân Odaklı Öğrenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Bilişsel Yük Kuramı: Bir derste öğrencilerin çalışma belleğine aynı anda 4-5 yeni kavramdan fazlasını yüklemek öğrenmeyi kilitler. Bilgiyi mikro parçalara (chunking) bölerek sunun.", "source": "John Sweller - Bilişsel Yük Kuramı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Aralıklı Tekrar (Spaced Repetition): Bir konuyu tek seferde saatlerce çalışmak yerine, 1 gün, 3 gün, 1 hafta ve 1 ay arayla 10'ar dakika tekrar etmek kalıcılığı 4 kat artırır.", "source": "Hermann Ebbinghaus Unutma Eğrisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Geri Çağırma Pratiği (Retrieval Practice): Notları tekrar tekrar okumak pasif bir yanılsamadır. Asıl öğrenme, zihni zorlayıp bilgiyi hafızadan geri çağırmaya çalışırken (mini testler, boş kağıda hatırladıklarını yazma) gerçekleşir.", "source": "Bilişsel Bellek Araştırmaları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çift Kodlama Teorisi (Dual Coding): Bilgi hem sözel (kelimeler) hem de görsel (şema, resim, grafik) olarak sunulduğunda beyinde iki ayrı kanaldan kodlanır ve hatırlanması kolaylaşır.", "source": "Allan Paivio - Çift Kodlama", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çapraz Öğrenme (Interleaving): Aynı tip matematik problemlerini art arda çözmek yerine, farklı problem türlerini karışık çözmek öğrencilerin hangi stratejiyi seçeceğini ayırt etmesini sağlar.", "source": "Robert Bjork - İstenen Zorluklar", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Bekleme Süresi (Wait Time): Sınıfa soru sorduktan sonra en az 3 ila 5 saniye sessizce bekleyin. Araştırmalar, bekleme süresi tanındığında cevap kalitesinin ve çekingen öğrencilerin katılımının 3 kat arttığını göstermektedir.", "source": "Mary Budd Rowe Araştırması", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İlgi Çekici Başlangıç (The Hook): Derse asla doğrudan 'Kitapları açın sayfa 40' diyerek başlamayın. Bir merak uyandırıcı soru, 30 saniyelik bir görsel veya günlük hayattan şaşırtıcı bir tezat ile başlayın.", "source": "Sınıf Yönetimi & Motivasyon", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çıkış Kartı (Exit Ticket): Dersin son 3 dakikasında tahtaya iki soru yazın: 'Bugün en iyi anladığın şey neydi?' ve 'Hala kafanı kurcalayan soru nedir?'. Birer kağıda yazdırıp çıkarken toplayın.", "source": "Biçimlendirici Değerlendirme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akran Öğrenmesi (Peer Tutoring): Bir konuyu en iyi öğrenme yolu, onu bir başkasına anlatmaktır. Bir öğrenme çıktısını kavrayan öğrencileri eşleştirerek mini rehberlik rolü verin.", "source": "İşbirlikçi Öğrenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Düşün-Eşleş-Paylaş (Think-Pair-Share): Soru sorduktan sonra tüm sınıfa doğrudan söz vermek yerine 30 sn sessiz düşünme, 1 dk yanındakiyle tartışma ve ardından ortak paylaşım yaptırın. Katılım %100'e çıkar.", "source": "Aktif Öğrenme Teknikleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Priming (Zihinsel Hazırlık): Gelecek haftanın konusunun anahtar bir kavramını bu haftadan tahtanın köşesine bir bilmece gibi asın; zihin farkında olmadan arka planda kavramı taramaya başlar.", "source": "Bilişsel Psikoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Pomodoro Tekniği: Zihinsel odaklanma 25 dakikadan sonra düşüşe geçer. 25 dakika yoğun çalışma ve 5 dakika zihinsel dinlenme döngüsü bilişsel tazelik sağlar.", "source": "Zaman Yönetimi Metodu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hikâyeleştirme Etkisi (Storytelling): Beyin izole formülleri ve maddeleri unutur; fakat bir hikâyenin kahramanını, çatışmasını ve çözümünü asla unutmaz. Bilgiyi bir hikâye örgüsü içine yerleştirin.", "source": "Nöro-Anlatı Bilimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mnemonic (Hafıza Çivileri): Karmaşık sıralamaları veya listeleri akılda tutmak için akrostişler, tekerlemeler ve görsel benzetmeler kullanmak hafızanın yükünü hafifletir.", "source": "Hafıza Teknikleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Uyku ve Bellek Konsolidasyonu: Gün içinde öğrenilen bilgiler gece derin uykuda (özellikle REM ve yavaş dalga uykusunda) geçici bellekten kalıcı kortekse aktarılır. Uykusuzluk öğrenmeyi siler.", "source": "Nöro-Biyoloji Notu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Amigdala ve Öğrenme Bağı: Korku, tehdit veya alay edilme riski altındaki bir sınıfta amigdala alarm verir ve prefrontal kortekse giden kan akışı kesilir. Tehdit altındaki beyin öğrenemez.", "source": "Duygusal Nörobilim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dopamin ve Merak: Bir öğrenci merak ettiği bir sorunun cevabını keşfettiğinde beyin dopamin salgılar; bu hormon hem öğrenme zevkini artırır hem de o anki sinirsel bağlantıyı mühürler.", "source": "Nöro-Kimyasal Öğrenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Görsel Hiyerarşi (Figma ve Tasarım İlkesi): Tahtaya yazı yazarken ana başlıkları büyük ve renkli, alt maddeleri girintili ve maddeler halinde yazmak gözün bilgiyi tarama hızını 2 katına çıkarır.", "source": "Görsel Ergonomi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Feynman Tekniği: Bir konuyu gerçekten anlayıp anlamadığınızı test etmek için, konuyu hiç bilmeyen 10 yaşındaki bir çocuğa hiç yabancı terim kullanmadan anlatmaya çalışın.", "source": "Richard Feynman Öğrenme Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Bilişsel Çatışma (Cognitive Dissonance): Öğrencilerin bildiğini sandığı bir konuda şaşırtıcı bir tezat veya beklenmedik bir deney sonucu gösterin; zihindeki merak ateşi anında alevlenir.", "source": "Jean Piaget - Dengeleme Süreci", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sokratik Çürütme: Yanlış bir cevap veren öğrenciye doğrudan 'Yanlış' demek yerine, 'Peki böyle düşünürsek şu durumda ne olur?' diyerek kendi hatasını kendi mantığıyla buldurun.", "source": "Sokratik Diyalog Yöntemi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kavram Yanılgılarını Teşhis Etme: Yeni konuya başlamadan önce 3 maddelik mini teşhis testi yapın; öğrencilerin kafasındaki hatalı ön kabuller düzeltilmeden üzerine doğru bilgi inşa edilemez.", "source": "Teşhis Edici Değerlendirme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Açıklayıcı Sorgulama (Elaborative Interrogation): Öğrenciye bir olguyu ezberletmek yerine 'Bu neden doğrudur? Neden bu şekilde gerçekleşir?' diye sordurarak derin anlamlandırma sağlayın.", "source": "Bilişsel Stratejiler", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kendi Kendine Açıklama (Self-Explanation): Bir matematik problemini çözerken öğrencinin her adımda 'Şimdi bunu yapıyorum çünkü...' diyerek sesli düşünmesini sağlayın.", "source": "Metakognitif Pratik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Üretim Etkisi (Generation Effect): Boşluk doldurma veya bir cümleyi tamamlayarak üretilen bir kelime, sadece hazır okunan bir kelimeden %30 daha iyi hatırlanır.", "source": "Bellek Araştırmaları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Test Etkisi (Testing Effect): Test olmak sadece ölçme aracı değildir; bizzat kendisi en güçlü öğrenme ve hafıza güçlendirme aracıdır.", "source": "Roediger & Karpicke Araştırması", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Von Restorff Etkisi: Bir listede veya tahtada diğerlerinden farklı renk veya boyutta yazılan sıra dışı bir kavram, hafızada anında öne çıkar ve ilk hatırlanan olur.", "source": "Bilişsel Psikoloji İlkesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zeigarnik Etkisi: İnsan zihni tamamlanmamış işleri tamamlananlara göre çok daha diri tutar. Dersin sonunda bir soruyu askıda bırakarak bir sonraki derse kadar merakı diri tutun.", "source": "Bluma Zeigarnik Kuramı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Seri Konum Etkisi (Primacy and Recency): Dersin ilk 10 dakikası ve son 5 dakikası en yüksek hatırlama oranına sahiptir. En kritik kavramları bu zaman dilimlerine yerleştirin.", "source": "Bellek Psikolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenilmiş Çaresizlikten Kurtarma: Sürekli 'Ben matematikten anlamam' diyen öğrenciye küçük, kolay başarılabilir mikro görevler vererek başarı duygusunu yeniden tattırın.", "source": "Martin Seligman Kuramı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İçsel Motivasyon vs Dışsal Ödül: Sürekli çikolata veya maddi ödül vermek içsel öğrenme merakını öldürür. Asıl ödül, problemin çözümünden duyulan keşif hazzıdır.", "source": "Öz Belirleme Kuramı (Deci & Ryan)", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ayna Nöronlar: Öğretmenin derse olan heyecanı, yüz ifadesi ve tutkusu öğrencilerin ayna nöronlarını uyarır. Şevksiz bir öğretmenin sınıfında şevkli öğrenci bulunamaz.", "source": "Sosyal Nörobilim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Oksitosin ve Güven Ortamı: Sınıfta koşulsuz kabul ve samimiyet gören öğrencilerde oksitosin salgılanır; bu da sınıf içi işbirliğini ve paylaşma arzusunu tetikler.", "source": "Pozitif Sınıf İklimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Stres ve Kortizol: Kronik sınav kaygısı yaşayan çocukta kortizol hormonu hipokampusu küçültür ve bellek fonksiyonlarını zayıflatır. Sınavları bir yarış değil, öğrenme durağı olarak konumlandırın.", "source": "Stres Biyolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hareket ve Öğrenme: Ders esnasında 20 dakikada bir öğrencileri ayağa kaldırıp kısa bir esneme veya el çırpma ritmi yaptırmak beyne giden kan akışını anında %15 artırır.", "source": "Kinestetik Öğrenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Su Tüketiminin Zihne Etkisi: Vücuttaki %2'lik bir susuzluk bile odaklanma ve kısa süreli bellek kapasitesinde %10'a varan düşüşe yol açar. Masada su bulundurulmalıdır.", "source": "Fizyolojik Pedagoji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Doğal Işık ve Sirkadiyen Ritim: Doğal gün ışığı alan sınıflarda öğrencilerin matematik ve okuma başarılarının karanlık sınıflara göre %20 daha yüksek olduğu kanıtlanmıştır.", "source": "Mekân Psikolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çalışma Ortamında Dikkat Dağıtıcılar: Masada ders dışı eşyaların (açık telefon, oyuncak vb.) bulunması çalışma belleğinde sürekli mikro dikkat kaçışlarına yol açar.", "source": "Dikkat Ekonomisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zihin Haritası (Mind Mapping): Doğrusal not tutmak yerine merkezden dallara ayrılan renkli zihin haritaları çizmek beynin iki yarım küresini birden aktive eder.", "source": "Tony Buzan Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akronim Oluşturma: Karmaşık bir konunun maddelerinin ilk harflerinden anlamlı veya komik bir kelime türetmek hafızada kalıcı bir şifreleme sağlar.", "source": "Mnemonik Bellek Tekniği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Benzerlik ve Analoji Kurma: Elektrik akımını su borularındaki su akışına benzetmek gibi somut analojiler, soyut kavramların zihinde kolayca modellenmesini sağlar.", "source": "Bilişsel Analoji Teorisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Açık Uçlu Düşünme: Öğrencilere tek doğru cevabı olan test soruları yerine 'Eğer yerçekimi yarıya inseydi dünyada neler değişirdi?' gibi senaryolar sorarak yaratıcılığı kışkırtın.", "source": "Yaratıcı Problem Çözme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hata Analiz Defteri: Öğrencilerin denemelerde yanlış yaptığı soruları kesip bir deftere yapıştırması ve altına 'Neden yanlış yaptım? Doğru mantık ne?' yazması net artışının en hızlı yoludur.", "source": "Bilişsel Hata Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Odaklanma Süresi Kuralı: Bir çocuğun tek bir noktaya kesintisiz odaklanma süresi ortalama yaşı artı 2-3 dakikadır (Örn: 10 yaşındaki bir çocuk için yaklaşık 12-15 dakika). Anlatımı blok halinde tutmayın.", "source": "Gelişimsel Nöroloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çoklu Duyusal Öğrenme (VARK Modeli): Bir dersi hem kulağa (işitsel), hem göze (görsel), hem de dokunmaya (kinestetik) hitap edecek materyallerle zenginleştirin.", "source": "Neil Fleming Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenme Döngüsü (Kolb): Somut Deneyim -> Yansıtıcı Gözlem -> Soyut Kavramsallaştırma -> Aktif Deneme. Dört aşamayı da içeren bir ders tam öğrenmeyi sağlar.", "source": "David Kolb Deneyimsel Öğrenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zihinsel Prova (Mental Rehearsal): Bir sunum veya sınav öncesi süreci zihinde baştan sona sakin ve başarılı bir şekilde hayal etmek kaygıyı azaltır ve performansı artırır.", "source": "Spor ve Eğitim Psikolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öncelik-Sonralık Hatırlama Eğrisi: Dersin tam ortasındaki 15 dakikalık bölüm en az hatırlanan bölümdür; bu bölümde pasif dinleme değil, grup çalışması ve uygulama yaptırın.", "source": "Bilişsel Ritim Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çalışırken Müzik Dinleme Gerçeği: Sözlü müzikler çalışma belleğinde sözel kodlamayı bozar; odaklanma için sözsüz, düşük tempolu barok veya enstrümantal müzikler tercih edilmelidir.", "source": "Bilişsel Müzikoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenciye Söz Hakkı Vermede Rastlantısallık: Hep aynı parmak kaldıranlara söz vermek yerine isim çubukları veya dijital çark kullanmak sınıftaki herkesin tetikte ve derse bağlı kalmasını sağlar.", "source": "Sınıf İçi Eşit Katılım Kuralı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sandviç Geri Bildirim Formülü: Öğrenciye geri bildirim verirken önce güçlü yönünü övün (Ekmek), sonra geliştirilmesi gereken öğrenme çıktısını somutlaştırın (İçerik), ardından güven aşılayarak bitirin (Ekmek).", "source": "Ölçme & Değerlendirme Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Övgünün Gücü (Süreç Odaklı Övgü): Öğrenciye 'Çok zekisin' demek sabit zihniyet üretir. Bunun yerine 'Bu zor problemde gösterdiğin sabır ve denediğin yöntem harikaydı' demek gelişim zihniyetini (Growth Mindset) besler.", "source": "Carol Dweck - Zihniyet Kuramı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Olumlu Davranış Pekiştirme (4'e 1 Kuralı): Sınıfta bir olumsuz davranışı düzeltmeden önce, en az 4 olumlu davranışı fark edip takdir etmeyi alışkanlık haline getirin. Sınıf iklimi hızla sakinleşir.", "source": "Pozitif Sınıf İklimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Göz Teması ve Sınıfta Dolaşım (Proximity Control): İstenmeyen bir davranış başladığında dersi bölüp bağırmak yerine, konuşmanızı sürdürerek sakince o öğrencinin sırasının yanına doğru yürüyün. Davranış kendiliğinden durur.", "source": "Proaktif Disiplin", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kırık Camlar Teorisi Sınıfta: Sınıftaki küçük bir düzensizlik (yerdeki çöpler, eğri sıralar, tahtadaki karalamalar) hemen düzeltilmezse, öğrencilerde 'Burada kural yok' algısı oluşur ve disiplin hızla bozulur.", "source": "Sınıf Ekolojisi Notu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Topluluk Önünde Öv, Baş Başa Uyar: Bir öğrenciyi asla bütün sınıfın önünde azarlamayın; bu onu savunmaya ve kibre iter. Olumsuz davranışı teneffüste sakince ve göz göze konuşun.", "source": "Öğrenci Onuru ve İletişim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sözsüz İşaretler ve Ritim: Gürültüyü bastırmak için bağırmak yerine, iki kere el çırpıp tek bir ritim tutturun; öğrencilerin size aynı ritimle cevap vermesini isteyin. Sınıf saniyeler içinde sessizleşir.", "source": "Sınıf Yönetimi Ritüeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Net ve Pozitif Yönergeler: 'Koşma!', 'Konuşma!' gibi negatif komutlar yerine 'Yavaş yürüyelim', 'Sessizce dinleyelim' gibi yapılması istenen davranışı pozitif ifade edin.", "source": "Davranışsal Dil Kalıpları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Seçenek Sunma Mimarisi: Ders çalışmak istemeyen bir öğrenciye 'Çalışacaksın!' demek inatlaşma doğurur. 'Önce birinci sorudan mı başlamak istersin yoksa üçüncüden mi?' diyerek ona kontrol hissi verin.", "source": "Çatışmasız Yönetim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ben Dili Kullanımı: 'Çok saygısızsın, dersi kaynatıyorsun' (Sen dili) yerine 'Söz kesildiğinde dikkatim dağılıyor ve anlatmak istediklerimi aktaramadığım için üzülüyorum' (Ben dili) demek savunma duvarlarını indirir.", "source": "Thomas Gordon - Etkili Öğretmenlik Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Geçiş Ritüelleri (Transitions): Bir dersten diğerine veya anlatımdan grup çalışmasına geçerken net bir zaman sınırı ve sesli bir sayaç kullanın (Örn: 'Kitapları açıp 3. sayfaya geçmek için 30 saniyemiz var').", "source": "Zaman Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Davranışın Altındaki İhtiyacı Okuma: Sürekli dersi bölen çocuk ya dikkat çekmeye çalışıyordur, ya görevden kaçıyordur ya da güç savaşı veriyordur. Nedeni çözmeden davranışı çözemezsiniz.", "source": "Alfred Adler Bireysel Psikoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenci ile Göz Hizasına İnme: İlkokul ve ortaokulda bir öğrenciyle konuşurken ayakta tepeden bakmak korku yaratır; yanına çöküp göz hizasına inmek güven ve eşitlik mesajı verir.", "source": "Gelişimsel Beden Dili", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sakin Kalma Kuralı (Bulaşıcı Sakinlik): Öfke bulaşıcıdır; fakat sakinlik de bulaşıcıdır. Bir öğrenci taşkınlık yaptığında öğretmenin ses tonunu yükseltmek yerine daha da fısıltıya yaklaştırması ortamı yatıştırır.", "source": "Duygusal Öz Düzenleme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf İçi Görev Panosu: Her öğrencinin sınıf düzeninde bir sorumluluğu olsun. Hiçbir işe yaramadığını düşünen haylaz bir öğrenciye yoklama kağıdını taşıma veya tahtayı silme görevi vermek onu aidiyete bağlar.", "source": "Sosyal Sorumluluk Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Veli İletişiminde İlk Arama Kuralı: Bir veliyi sadece çocuğu yaramazlık yaptığında veya notu düştüğünde aramayın. Dönemin ilk haftalarında çocuğun güzel bir davranışını övmek için arayın; güven bağı kurulur.", "source": "Veli İşbirliği Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Haftalık Sınıf Meclisi: Cuma gününün son 15 dakikasında 'Bu hafta sınıfımızda ne iyi gitti, neyi daha iyi yapabiliriz?' gündemiyle mini bir meclis toplamak aidiyeti zirveye taşır.", "source": "Demokratik Okul Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Duygu Termometresi: Kapı girişine öğrencilerin sabah gelirken nasıl hissettiklerini (Mutlu, Yorgun, Kızgın, Heyecanlı) işaretleyebilecekleri bir termometre asın; ruh halini bilmek öğretimi kolaylaştırır.", "source": "Sosyo-Duygusal Farkındalık", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Masa Düzeni ve Pedagoji: Düz sıralar bireysel çalışmaya, U düzeni tartışmaya, küme (ada) düzeni ise işbirlikçi proje çalışmalarına uygundur. Amacınıza göre oturma planını esnetin.", "source": "Sınıf Ergonomisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ders Giriş Ritüeli: Zilin çalmasıyla ders anında başlamaz. Masaların toplanması, 3 saniyelik derin bir nefes alma ve ortak bir selamlama zihinsel bir eşik ritüelidir.", "source": "Odaklanma Protokolü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Söz Kesmeden Dinleme Kuralı: Sınıf tartışmalarında elinde 'Söz Nesnesi' (küçük bir top veya maskot) olan konuşur, diğerleri dinler. Dinleme saygısı bu şekilde somutlaşır.", "source": "Aktif Dinleme Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İnatlaşmayı Durdurma Tekniği: Öğrenci 'Yapmayacağım!' dediğinde 'Şu an öfkelisin, bunu 5 dakika sonra konuşalım' diyerek tartışmayı anında erteleyin; seyirci önünde güç savaşı vermeyin.", "source": "Kriz Yönetimi İlkesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ders Bölünmelerine Karşı 'Soru Kutusu': Dersin ortasında konu dışı soru soran meraklı öğrencilere 'Bu harika bir soru, bunu dersin sonundaki Soru Kutusu'na bırakalım' diyerek akışı koruyun.", "source": "Ders Akış Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tutarlılık İlkesi: Bir kural bir gün uygulanıp ertesi gün gevşetilirse, kuralların hiçbir inandırıcılığı kalmaz. Disiplinin temeli katılık değil, mutlak tutarlılıktır.", "source": "Sınıf Yönetimi Esasları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf Dışı Teneffüs Sohbetleri: Teneffüste nöbet tutarken bir öğrenciyle hobileri, tuttuğu takım veya sevdiği kitap hakkında ayaküstü 1 dakika konuşmak, sınıftaki 40 dakikalık dersten daha derin bağ kurar.", "source": "İlişki Odaklı Pedagoji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Teşekkür Kartları: Beklenmedik bir anda sırasına 'Bugün dersteki katkın için teşekkür ederim' yazılı mini bir yapışkanlı not bırakılan bir öğrenci, o dersin en sadık dinleyicisi olur.", "source": "Pozitif Güçlendirme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Beden Dilinde Açık Duruş: Kollarınızı göğsünüzde bağlamak bilinçaltında savunma ve mesafe sinyali verir. Açık avuçlar ve dik, rahat bir duruş güven ve otorite hissettirir.", "source": "Beden Dili Psikolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İçeriğe Uygun Ses Tonu: Monoton bir ses tonu hipnotize edici bir uyku etkisi yapar. Sesinizi bir müzik eseri gibi kimi yerde yükseltin, kimi yerde önemli bir sır verircesine fısıldayın.", "source": "Vokal Dinamizm", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfın Ortak Şakası: Sınıfça paylaşılan masum ve neşeli bir espri veya ders içi küçük bir anekdot, grubu birleştiren en güçlü sosyal çimentodur.", "source": "Mizah ve Öğrenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kural Sayısını Az Tutma Kuralı: 20 maddelik bir sınıf kuralı listesi kimse tarafından hatırlanmaz. 3 ila 5 temel, pozitif ilke belirleyin (Örn: Birbirimize saygılıyız, Çaba gösteririz, Güvenliği koruruz).", "source": "Kural Mimarisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akran Dışlanmasını Önleme: Grup çalışmalarında öğrencilerin birbirini seçmesine izin verirseniz hep aynı çocuklar dışarıda kalır. Grupları öğretmen adil ve dengeli kurmalıdır.", "source": "Kapsayıcı Sınıf Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Özel Eğitim ve Kaynaştırma Hassasiyeti: BEP'li bir öğrencinin sınıf içindeki küçük bir başarısını fark edip onaylamak, diğer öğrencilerin de ona destek olmasını teşvik eder.", "source": "Özel Eğitim ve Kaynaştırma", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sessizlik Molası (Brain Break): Yorucu ve yoğun bir problem çözümünün ardından 60 saniyelik gözleri kapatıp derin nefes alma molası zihni sıfırlar.", "source": "Bilişsel Dinlenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dedikodu ve İspiyonculuğu Ayırt Etme: Öğrencilere 'Biri zarar görüyor veya tehlikedeyse haber vermek yardımdır; ama birinin açığını yakalayıp anlatmak dedikodudur' farkını öğretin.", "source": "Ahlaki Gelişim Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ders Sonu Toparlanma Disiplini: Zilin çalması dersin bittiği anlamına gelmez; dersi öğretmen bitirir. Sıraların düzenlenmesi ve vedalaşma olmadan sınıftan çıkılmamalıdır.", "source": "Sınıf Rutinleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenci Günlüğü Gizliliği: Eğer öğrencilere duygu veya öğrenme günlüğü yazdırıyorsanız, onların rızası olmadan asla yüksek sesle okumayın; güven bir kez kırılırsa telafisi imkânsızdır.", "source": "Etik Pedagoji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf Panosunu Güncel Tutma: 6 ay önce asılmış sararmış kağıtlar sınıfta ilgisizlik hissi yaratır. Panolar her ay öğrencilerin yeni ürünleriyle yenilenmelidir.", "source": "Görsel Öğrenme Ortamı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Her Çocuğun Bir Güçlü Yönünü Keşfetme: Akademik olarak zayıf bir öğrencinin çizim yeteneği, tamir becerisi veya spor kabiliyeti olabilir; o yönünü sınıfta öne çıkararak özsaygısını kurtarın.", "source": "Bütüncül Başarı Anlayışı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf İçi Anlaşmazlıklarda 'Tamir Masası': İki öğrenci kavga ettiğinde onları suçlamak yerine 'Gelin bunu Tamir Masası'nda konuşalım; ne oldu ve birbirimizden ne bekliyoruz?' diye çözdürün.", "source": "Onarıcı Adalet Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ödül Panosunda Bireysel Yarış Değil Sınıf Hedefi: 'En çok yıldızı kim alacak?' yerine 'Tüm sınıf olarak hedefimize ulaştığımızda hep birlikte ne yapacağız?' demek dayanışmayı güçlendirir.", "source": "İşbirlikçi İklim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tehlikeli Durumlarda Sakin Tahliye Refleksi: Deprem, yangın veya acil durumlarda öğretmenin sesi paniksiz ve emir kipiyle net olmalıdır; çocuklar rehberin sakinliğini taklit eder.", "source": "Okul Güvenliği Protokolü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ders İçi Söz Alma İşaretleri: Parmak kaldırmak yerine 'Başparmak yukarı' (Katılıyorum), 'Başparmak aşağı' (Farklı düşünüyorum) gibi sessiz el işaretleri tüm sınıfın aynı anda fikrini bildirir.", "source": "Sözsüz Katılım Araçları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrencinin İsmini Doğru Telaffuz Etmek: İsmi zor veya farklı olan bir öğrencinin adını doğru söylemek için çaba göstermek, onun kültürel kimliğine ve ailesine duyulan en derin saygıdır.", "source": "Kültürel Duyarlılık", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mazeretleri Anlayışla Karşılama Sınırı: Bir defalık ödev unutmayı anlayışla karşılayıp 'Bugünlük telafi et ama yarın bekliyorum' demek şefkattir; alışkanlık haline gelmesini engellemek ise disiplindir.", "source": "Şefkatli Sınır Koyma", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Veli Toplantısında 'Kelle Sayımı' Yapmama: Veli toplantılarında sadece not listesi okumayın; çocukların karakter gelişimini, erdemlerini ve sınıftaki dostluklarını paylaşın.", "source": "Nitelikli Veli Diyaloğu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tahta Başında Utandırmama: Bir öğrenciyi bilemeyeceğini bildiğiniz bir soru için tahtaya kaldırıp mahcup etmeyin; tahtaya kaldırmak başarıyı kutlamak için olmalıdır.", "source": "Öğrenci Ruh Sağlığı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfta Mizahın Dozu: Mizah dersi canlı tutar; fakat asla bir öğrencinin fiziksel özelliği, soyadı veya eksikliği üzerinden şaka yapılmamalıdır.", "source": "Öğretmenlik Etiği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Derse Vaktinde Başlama Disiplini: Öğretmen derse 5 dakika geç girerse, öğrencilerden dakiklik bekleyemez. En iyi model, bizzat vaktinde orada olmaktır.", "source": "Zaman Etiği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenciye Güven Vermek: 'Sana inanıyorum, bu konunun üstesinden gelebileceğini biliyorum' cümlesi, bir çocuğun hayatında yıllar sonra bile yankılanan bir tılsımdır.", "source": "Pygmalion Etkisi (Beklenti Kuramı)", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Vedalaşırken Göz Teması: Ders bittiğinde kapıdan çıkan her öğrenciye sıcak bir tebessümle 'İyi günler, yarın görüşürüz' demek günü güzellikle mühürler.", "source": "Öğretmen Zarafeti", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Jigsaw (Ayrılıp Birleşme) Tekniği: Konuyu 4 parçaya bölün. Her gruptan birer temsilci 'Uzman Grubu' kurup o konuyu çalışır, sonra ana gruplarına dönüp arkadaşlarına öğretir.", "source": "İşbirlikçi Öğrenme Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İstasyon Tekniği: Sınıfı 3-4 farklı istasyona bölün (Şiir/Yazma İstasyonu, Deney İstasyonu, Kavram Haritası İstasyonu). Gruplar 10'ar dakika arayla istasyon değiştirerek önceki grubun bıraktığı işi tamamlar.", "source": "Farklılaştırılmış Öğretim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Balık Kılçığı (Ishikawa) Diyagramı: Karmaşık bir problemin kök nedenlerini analiz ederken omurgaya ana sorunu, yan kılçıklara ise insan, yöntem, çevre gibi faktörleri yazarak derinlemesine analiz yaptırın.", "source": "Kök Neden Analizi Yöntemi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Altı Şapkalı Düşünme Tekniği (Edward de Bono): Beyaz (Veriler), Kırmızı (Duygular), Siyah (Riskler), Sarı (Fırsatlar), Yeşil (Yaratıcılık), Mavi (Yönetim). Bir konuyu tüm yönleriyle ele aldırır.", "source": "Düşünme Becerileri Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Köşelenme Tekniği: Bir tartışma sorusunda sınıfa 'Katılıyorum', 'Kararsızım', 'Katılmıyorum' köşeleri belirleyin. Herkes savunduğu köşeye gitsin ve grup adına argümanını sunsun.", "source": "Tartışma Teknikleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kartopu Tekniği: Önce öğrenci 1 dakika kendi başına düşünür -> Sonra yanındakiyle 2 kişi olur -> Sonra 4 kişi -> En son 8 kişilik grup ortak karara varır. Fikirler kartopu gibi büyür.", "source": "Aktif Öğrenme Metodolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Pazar Yeri (Gallery Walk) Tekniği: Gruplar hazırladıkları afiş veya projeleri sınıf duvarlarına asar. Bir kişi stand başında kalıp anlatır, diğerleri gezerek sorular sorar ve yapışkan notla geri bildirim bırakır.", "source": "Görsel Sunum ve Paylaşım", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sokratik Çember (Fishbowl): İç çemberde 5-6 öğrenci derin bir konuyu tartışırken, dış çemberdeki öğrenciler sessizce onları dinleyip argümanlarını not alır. Sonra roller değişir.", "source": "Derinlemesine Tartışma Metodu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kavram Ağları (Semantic Maps): Bir kavramın zihindeki çağrışımlarını, alt türlerini ve zıt anlamlılarını tahtada ağ şeklinde modellemek sözcük dağarcığını ve kavram derinliğini katlar.", "source": "Dil ve Anlam Bilgisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Venn Şeması ile Karşılaştırma: İki farklı tarihi olayı, canlı türünü veya edebi eseri kesişen iki küme içinde inceletmek analitik mukayese becerisini hızla geliştirir.", "source": "Görsel Karşılaştırma Aracı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Konuşma Halkası Tekniği: Duygusal veya ahlaki bir ikilem içeren hikâyenin ardından sınıfça çember olunur; eline konuşma nesnesi gelen çocuk hikâye kahramanının yerine geçip hislerini paylaşır.", "source": "Duygusal Empati Becerisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akvaryum Tekniği: İçteki sandalyeye oturan öğrenci bir tez savunur; dinleyicilerden biri karşı tez sunmak istediğinde boş sandalyeye oturup münazaraya dahil olur.", "source": "Dinamik Tartışma Sanatı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Rulman (Top Taşıma) Tekniği: İç içe iki daire oluşturulur; yüz yüze bakan öğrenciler 2 dakika konuyu tartışır. Süre bitince dış daire 1 adım kayar ve yeni eşle tartışma başlar.", "source": "Hızlı Fikir Alışverişi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dedikodu Tekniği (Pedagojik Dedikodu): İkişerli başlayan tartışmada öğrenciler edindikleri fikirleri bir sonraki eşleşmede 'Arkadaşım bu konuda şöyle ilginç bir nokta söyledi' diyerek aktarır.", "source": "Fikir Yayılım Metodu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tereyağı-Ekmek Tekniği: Bir soru sorulur; öğrenci önce tek başına düşünür (tereyağı), sonra yanındakiyle tartışıp fikirleri kaynaştırır (ekmek). Fikirler sağlamlaşır.", "source": "Hızlı Düşünme Tekniği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kart Eşleştirme (Flashcards): Bir yüzde kavram, diğer yüzde tanım veya problem olan kartlarla yapılan 5 dakikalık oyunlar ezber bozan bir geri çağırma pratiğidir.", "source": "Bellek Güçlendirme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Münazara Kuralları: Münazara bir kavga değil, argüman ve delil yarışıdır. Öğrencilere karşı tarafın fikrine değil, kanıtlarına odaklanma nezaketi öğretilmelidir.", "source": "Retorik ve Mantık", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mahkeme Simülasyonu: Tarihteki veya edebiyattaki tartışmalı bir karakteri (Örn: Brütüs, Lale Devri Sadrazamı vb.) sınıfta hâkim, savcı, avukat ve jüri rolleriyle yargılatıp karar verdirin.", "source": "Hukuki ve Tarihsel Muhakeme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Rol Oynama ve Canlandırma (Drama): Soyut bir tarihi olayı veya fen bilimlerindeki atomun hareketini öğrencilere bedenleriyle canlandırtmak konuyu zihne kazır.", "source": "Yaratıcı Drama Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Beyin Fırtınası (Brainstorming) Altın Kuralı: Fikir üretme aşamasında asla ve asla eleştiri yapılamaz! En çılgın fikir bile tahtaya yazılır; eleme ve analiz aşaması sonraya bırakılır.", "source": "Alex Osborn - Yaratıcılık Kuralı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ters Beyin Fırtınası: 'Bu projeyi nasıl başarılı yaparız?' yerine 'Bu projeyi mahvetmek için neler yapmalıyız?' diye sordurun; gizli riskleri görmek çok daha kolaylaşır.", "source": "Yaratıcı Problem Çözme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "SCAMPER Tekniği: Bir nesneyi veya fikri geliştirmek için 7 soru: Yerine koy (S), Birleştir (C), Uyarla (A), Değiştir (M), Başka amaçla kullan (P), Yok et (E), Tersine çevir (R).", "source": "Bob Eberle Yaratıcılık Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kavram Karikatürü Oluşturma: Öğrencilerin kendi el yazılarıyla iki karakter çizip konuya dair yaygın bir yanılgıyı ve doğrusunu konuşturmasını isteyin.", "source": "Yansıtıcı Çizim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kelime İlişkilendirme Testi (KİT): Anahtar bir kelime verip öğrencilerden 30 saniye içinde akıllarına gelen ilk 5 kavramı yazmalarını istemek bilişsel yapıyı anında röntgenler.", "source": "Kavramsal Haritalama", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Güdümlü Okuma (Guided Reading): Uzun bir metni tek seferde okutmak yerine, her paragrafta durup 'Burada ne oldu? Bir sonraki paragrafta ne olabilir?' diye tahmin ettirin.", "source": "Okuduğunu Anlama Stratejisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Metinlerarası İlişki Kurma: Okunan bir şiiri dönemin tarihi olaylarıyla, resim sanatıyla veya günümüzün bir toplumsal meselesiyle bağdaştırmak öğrenciyi derinleştirir.", "source": "Edebiyat ve Kültür Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Problem Temelli Öğrenme (PBL): Derse doğrudan konuyu anlatarak değil, gerçek hayatta karşılaşılabilecek karmaşık bir vaka senaryosuyla (Örn: 'Şehirdeki su kirliliği nasıl çözülür?') başlayın.", "source": "Yapılandırmacı Öğrenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Proje Tabanlı Öğrenme: Öğrencilerin haftalar süren bir araştırma sonunda somut bir ürün (maket, broşür, web sitesi, podcast) ortaya koyması kalıcı sahiplenme üretir.", "source": "Ürün Odaklı Maarif", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Matematikte Hata Avcılığı: Tahtaya baştan sona çözülmüş fakat kasıtlı olarak 3. satırında işlem hatası yapılmış bir soru yazın; öğrencilerin dedektif gibi hatayı bulmasını isteyin.", "source": "Analitik Dikkat Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kendi Sorunu Kendin Yaz: Dersin sonunda öğrencilere 'Eğer yarın sınavı sen hazırlasaydın bugünkü konudan nasıl bir soru sorardın?' dedirtip birer soru yazdırın.", "source": "Üst Düzey Bilişsel Soru Yazımı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenci Sunumlarında 5 Kuralı: Bir slaytta en fazla 5 satır, her satırda en fazla 5 kelime olmalı; slayt bir kitap sayfası değil, konuşmacının feneri olmalıdır.", "source": "Etkili Sunum Teknikleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mikro Deneyler (Kitchen Science): Fen derslerinde pahalı laboratuvar yerine bir bardak su, tuz, sirke veya karbonatla yapılabilecek basit ev deneyleri bilimi tabana yayar.", "source": "STEM ve Günlük Hayat", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tarihsel Empati: 'Fatih Sultan Mehmet'in yerinde olsaydınız gemileri karadan yürütme kararını hangi stratejik gerekçelerle alırdınız?' sorusu tarihi ezberden çıkarır.", "source": "Tarih Öğretimi Metodolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Coğrafyada 'Yerinde Gözlem': Okul bahçesindeki bir ağacın gölge boyunu günün farklı saatlerinde ölçtürmek mevsim ve güneş açısı konusunu tahtadaki çizimden 100 kat daha iyi kavratır.", "source": "Uygulamalı Coğrafya", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kelime Avı ve Sözlük Keşfi: Haftada bir gün öğrencilere Kubbealtı veya TDK sözlüğünden hiç bilmedikleri güzel bir Türkçe kelime seçtirip bunu bir cümlede kullandırmak lügat zenginliği kazandırır.", "source": "Dilimizin Zenginlikleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yaratıcı Yazarlık Kutusu: Bir kutunun içine rastgele 3 kelime (Örn: 'Pusula', 'Yağmur', 'Eski bir mektup') atın; öğrencilerden bu 3 kelimenin geçtiği 1 sayfalık bir öykü yazmalarını isteyin.", "source": "Yazma Becerisi Atölyesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Bilişimde 'Bilgisayarsız Kodlama' (Unplugged): Algoritma mantığını bilgisayar olmadan kağıt bardaklar, yön okları ve labirent oyunlarıyla öğretmek soyut mantığı somutlaştırır.", "source": "Algoritmik Düşünme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Müzikle Hafıza Köprüsü: Formülleri veya kronolojik sıralamaları basit ve akılda kalıcı bir melodiye uyarlamak öğrencilerin sınav anında melodiyi hatırlayarak soruyu çözmesini sağlar.", "source": "Ritmik Öğrenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sessiz Sinema ile Kavram Anlatımı: Fen veya sosyal derslerindeki bir kavramı hiç konuşmadan sadece jest ve mimiklerle arkadaşlarına anlattırmak kavramın özünü kavratır.", "source": "Eğitici Oyunlar", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tabu Oyunu ile Tanımlama: 'Hücre' kelimesini anlatırken 'sitoplazma, çekirdek, zar' kelimelerini kullanmayı yasaklayın; öğrenci kavramı ezber kalıpların dışında kendi kelimeleriyle ifade etmeye zorlanır.", "source": "Kavramsal Esneklik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf Gazetesi / Bülteni Çıkarma: Öğrencilerin dönem boyunca öğrendikleri konuları bir gazete haberi gibi tasarlayıp okul panosuna asması yazılı ifade becerisini taçlandırır.", "source": "Medya Okuryazarlığı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Röportaj Tekniği: Tarihi bir şahsiyet veya meslek erbabı hakkında bilgi toplarken bir öğrencinin muhabir, diğerinin o şahsiyet olduğu canlandırmalı röportajlar yapmak konuyu canlandırır.", "source": "Sözlü Tarih ve İletişim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Görsel Okuma ve Karikatür Analizi: Derse bir karikatürle başlayıp 'Çizer burada hangi toplumsal yaraya parmak basmış? Hangi sembolleri kullanmış?' diye sormak eleştirel gözü keskinleştirir.", "source": "Görsel Eleştiri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çapraz Sorgu Münazarası: Klasik münazara yerine takımların birbirine doğrudan soru sorup 60 saniye içinde delilli cevap beklediği format, dikkati en üst düzeye çıkarır.", "source": "Retorik ve Savunma", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kavram Haritası Bağlaçları: Kavram haritasında sadece iki kutuyu çizgiyle bağlamak yetmez; çizginin üzerine '... neden olur', '... bir parçasıdır' gibi bağlaç ifadeleri yazılmalıdır.", "source": "Joseph Novak Kavram Haritası", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tersine Mühendislik (Reverse Engineering): Öğrencilere bitmiş, mükemmel bir kompozisyon veya proje gösterip 'Bunu yapan kişi ilk hangi adımla başlamış olabilir?' diye parçalara ayırttırın.", "source": "Analitik Ayrıştırma", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Merak Duvarı: Sınıfın bir köşesine boş bir pano asın; öğrenciler ders esnasında akıllarına gelen fakat derste soramadıkları ilginç soruları yapışkanlı kağıtla buraya assın. Haftada bir cevaplayın.", "source": "Sorgulayan Sınıf İklimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hızlı Kroki Çizimi: Coğrafya dersinde tahtaya bakmadan Türkiye haritasının ana hatlarını veya bir dağ sırasını 30 saniyede şematik çizmeyi öğretmek mekânsal zekâyı uçurur.", "source": "Mekânsal Haritalama", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hikâye Çemberi: Öğretmen bir cümlenin girişini söyler, yanındaki öğrenci bir cümle ekler; 30 kişilik sınıfın sonunda ortaya ortak ve yaratıcı bir öğrenme öyküsü çıkar.", "source": "Kolektif Yaratıcılık", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ders Sonu 1 Cümle Özeti: Zilden 2 dakika önce her öğrenciye bugünkü dersin özünü tek bir cümleye sığdırma görevi verin; sentez yapabilme becerisinin en pratik antrenmanıdır.", "source": "Bilişsel Sentez Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Açık Uçlu Soru Hazırlama Kuralı: Sorularınız ezber bilgi ('... nedir?') yerine transfer ve analiz düzeyinde ('... olursa ne gibi sonuçlar doğar, neden?') olmalıdır. MEB ortak yazılı baremleri bu düzeydedir.", "source": "Bloom Taksonomisi & MEB ÖDSGM", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Biçimlendirici (Formative) vs Düzey Belirleyici (Summative) Değerlendirme: Çorbayı aşçı tadarsa bu biçimlendirici değerlendirmedir (tuzunu ayarlar); müşteri tadarsa bu düzey belirleyicidir. Ders esnasında sürekli aşçı gibi tadım yapın.", "source": "Paul Black & Dylan Wiliam Araştırması", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "3-2-1 Özeti: Bir ünitenin sonunda öğrencilerden şu 3 maddeyi yazmasını isteyin: Öğrendiğim 3 yeni bilgi, ilginç bulduğum 2 ayrıntı, hala aklımı kurcalayan 1 soru.", "source": "Hızlı Değerlendirme Aracı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Trafik Işıkları Değerlendirmesi: Öğrencilere yeşil (Tam anladım), sarı (Biraz kafam karışık), kırmızı (Hiç anlamadım) kartları verin; konunun sonunda kartları kaldırtarak sınıfın nabzını 3 saniyede ölçün.", "source": "Görsel Geri Bildirim Sistemi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Holistik (Bütüncül) Rubrik: Karmaşık ve yaratıcı bir kompozisyon veya proje ödevini tek bir genel başarı baremiyle (Çok İyi, Orta, Geliştirilmeli) değerlendirmek için idealdir.", "source": "Ölçme Değerlendirme Teknikleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Analitik Rubrik: Öğrencinin çalışmasını içerik, organizasyon, dil bilgisi ve kaynakça gibi alt boyutlara ayırıp her boyut için ayrı puan tanımlamak öğrenciye nerede eksik olduğunu tam gösterir.", "source": "Analitik Değerlendirme Standardı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İki Yıldız Bir Dilek (Two Stars and a Wish): Akran değerlendirmesinde öğrenci arkadaşının ödevine önce beğendiği 2 güçlü yönü (Yıldız), sonra geliştirmesini önerdiği 1 somut tavsiyeyi (Dilek) yazar.", "source": "Akran Geri Bildirim Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Soru Kökünde 'Değildir' ve 'Ulaşılamaz' Vurgusu: Çoktan seçmeli sorularda olumsuz ifadeler mutlaka koyu ve altı çizili yazılmalı; soru kökü karmaşık değil yalın olmalıdır.", "source": "Test Yazım Standartları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çeldirici Yazma Sanatı: Çoktan seçmeli bir soruda iyi bir çeldirici, öğrencilerin en sık düştüğü kavram yanılgısına dayanmalıdır; rastgele uydurulan bir şık çeldirici niteliği taşımaz.", "source": "Madde Analizi İlkesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ayırt Edicilik İndeksi: Bir soruyu üst başarı grubundaki (%27) tüm öğrenciler doğru yapıp, alt gruptaki (%27) tüm öğrenciler yanlış yapıyorsa o soru mükemmel ayırt edicidir.", "source": "Psikometri ve İstatistik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Soru Güçlük İndeksi (p değeri): Bir testteki soruların ortalama güçlüğü 0.50 civarında olmalıdır; ne herkesin yapabileceği kadar kolay ne de kimsenin çözemeyeceği kadar imkânsız olmalıdır.", "source": "Ölçme Kuramı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yazılı Kağıdı Okurken İsimleri Kapatma: Öğretmenin öğrenci hakkındaki ön yargılarının (hal ve gidiş, önceki notlar) notu etkilememesi için sınav kağıtları isimler katlanarak okunmalıdır.", "source": "Halo Etkisini Önleme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Soru Başına Puan Dağılımının Şeffaflığı: Sınav kağıdının üzerinde her sorunun kaç puan olduğu ve çözüm basamaklarının ara puanları baştan belirtilmelidir.", "source": "MEB Yazılı Yönergesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınav Sonrası 'Soru Kliniği': Sınav sonuçlarını dağıttıktan sonra doğru cevapları tahtada çözüp geçmeyin; sınıfın en çok döküldüğü 2 soruyu 'Klinik Masası'na yatırıp hata kökünü birlikte tartışın.", "source": "Onarıcı Değerlendirme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çoktan Seçmeli Testlerin Sınırı: Çoktan seçmeli testler tanıma ve hatırlamayı ölçer; yaratıcı sentez, özgün yazı ve problem kurma becerisini asla tam ölçemez. Açık uçlu sorular şarttır.", "source": "Maarif Ölçme Yaklaşımı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sözlü Notu Verme Ölçütleri: Sözlü notu öğretmenin hissiyatına veya anlık kanaatine göre değil; derse hazırlık, derse aktif katılım ve ödev sorumluluğunu gösteren somut bir bareme dayanmalıdır.", "source": "Mevzuat ve Adalet", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kısa Yanıtlı Testler (Boşluk Doldurma): Cümledeki boşluk asla cümlenin en başında olmamalıdır; öğrenci önce cümlenin bağlamını okumalı, boşluk cümlenin sonuna doğru yerleştirilmelidir.", "source": "Soru Hazırlama Teknikleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Doğru-Yanlış Testlerinde 'Şans Başarısı': Doğru-yanlış testlerinde şans başarısı %50'dir; bu nedenle puanlama yapılırken yanlışın doğruyu götürmesi veya ifadenin düzeltilmesinin istenmesi gerekir.", "source": "Ölçme Güvenilirliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Eşleştirme Maddeleri Kuralı: Eşleştirme sorularında öncüller sütunu ile cevaplar sütunundaki madde sayısı eşit olmamalıdır; en az 1-2 fazla çeldirici seçenek konulmalıdır.", "source": "Madde Yazım Kılavuzu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tanılayıcı Dallanmış Ağaç (TDA): Birbiriyle bağlantılı doğru/yanlış kararlarıyla bir ağacın dalları boyunca ilerleyen sistem, öğrencinin hangi adımda kavram yanılgısına düştüğünü nokta atışı tespit eder.", "source": "Alternatif Ölçme Aracı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yapılandırılmış Grid (Grid Testi): 9 veya 12 kutucuktan oluşan bir tabloda kavramlar yer alır; sorulara verilen cevaplarda kutucuk numaraları seçilerek çok boyutlu anlama ölçülür.", "source": "Görsel Değerlendirme Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kavram Haritası ile Ölçme: Öğrenciye sadece kavramları verip aralarındaki ilişkileri ve bağlaçları kendisinin çizmesini istemek zihindeki derin şemayı görünür kılar.", "source": "Yapılandırmacı Ölçme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Gelişim Portfolyosu Puanlama Kuralı: Portfolyoda sadece en mükemmel çalışmalar değil; öğrencinin ilk taslağı ile düzeltilmiş son hali yan yana konmalı ve kat ettiği mesafe puanlanmalıdır.", "source": "Süreç Odaklı Portfolyo", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dijital Quizlerin Gücü (Kahoot/Quizizz): Dersin ilk 5 dakikasında yapılan 4 soruluk eğlenceli bir dijital anket, kimin ön bilgide eksik olduğunu anında renkli grafiklerle öğretmenin önüne serer.", "source": "Anlık Ölçme Teknolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kendi Kendini Puanlama Şeffaflığı: Öğrenciye sınav kağıdını vermeden önce 'Sence bu sınavdan kaç alacaksın?' diye tahmin ettirin; zamanla tahmin ile gerçek not arasındaki fark sıfırlanır, öz farkındalık artar.", "source": "Metakognitif Kalibrasyon", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ödev Vermede 'Miktar Değil Nitelik': 50 sayfa ezber ödev öğrenciyi okuldan soğutur; düşünmeye, araştırmaya ve bir problem çözmeye yönelik 3 nitelikli soru çok daha kalıcıdır.", "source": "Ödev Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Geri Bildirimde 'Zaman' Kuralı: Bir hafta sonra verilen geri bildirim unutulmuştur; ders esnasında sıranın başındayken fısıldanan 10 saniyelik düzeltme en güçlü öğrenme anıdır.", "source": "Mikro Geri Bildirim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenme Çıktısı Tablosu (Belirtke Tablosu): Sınav hazırlamadan önce hangi öğrenme çıktısından kaç soru sorulacağını gösteren bir tablo hazırlamak sınavın kapsam geçerliğini garanti eder.", "source": "Test Planlama Esasları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Güvenilirlik ve Soru Sayısı: Bir sınavda soru sayısı arttıkça tesadüfi hatalar azalır ve sınavın güvenilirliği artar; ancak süre öğrencinin yorulmayacağı makul bir dengede tutulmalıdır.", "source": "Psikometrik Standartlar", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Önyargısız Gözlem Formu: Proje sunumlarında veya laboratuvar derslerinde önceden belirlenmiş 'Gözlem Formu' kullanmak sübjektif kanaatleri sıfırlar.", "source": "Performans Değerlendirme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Grup Değerlendirmesinde 'Serbest Yolcu' Tuzağı: Grup ödevlerinde gruptaki herkesin eşit not alması tembel öğrenciyi ödüllendirir; grup notunun yanında her üyenin kendi katkısını gösteren akran formu alınmalıdır.", "source": "Adil Grup Değerlendirmesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hata Odaklı Barem: Açık uçlu sorularda öğrencinin işlem hatası yapması durumunda sorunun tamamı çizilmemeli; formülü doğru kurduğu kısma kadar hak ettiği puan verilmelidir.", "source": "MEB Ölçme Adaleti", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Geri Bildirimi Soruyla Bitirmek: Öğrenciye sadece 'Burası hatalı' demek yerine 'Sence buradaki formülü neden uygulayamayız?' diye bir soruyla bırakmak zihni aktif tutar.", "source": "Düşündürücü Geri Bildirim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ölçme Sonuçlarının Zümreyle Paylaşımı: Bir zümredeki tüm öğretmenlerin ortak yazılı sonuçlarını masaya yatırıp 'Hangi öğrenme çıktısında ortak eksiklik var?' diye analiz etmesi okul başarısını zıplatır.", "source": "Zümre İşbirliği Kültürü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınav Kaygısını Azaltma Formülü: Sınavdan hemen önce tahtaya motivasyon dolu, içten ve gülümseten bir not yazmak öğrencilerin kalp atışlarını sakinleştirir.", "source": "Sınav Psikolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Klasik Sözlü Sınavların Sakıncası: Tüm sınıfın önünde ayağa kaldırıp soru yağmuruna tutmak ölçmeden çok sahne korkusunu tetikler; bireysel mülakat veya küçük grup görüşmesi tercih edilmelidir.", "source": "Sözlü Değerlendirme İlkeleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Standart Sapma Ne Anlatır?: Bir sınavda standart sapmanın yüksek olması sınıftaki öğrenci düzeylerinin birbirinden çok farklı ve heterojen olduğunu; düşük olması ise sınıfın birbirine yakın olduğunu gösterir.", "source": "Eğitim İstatistiği Notu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kopya ile Mücadelede En Etkili Yol: Soruları doğrudan kitaptan ezber cümlelerle değil, öğrencinin kendi yorumunu ve çözüm yolunu katmak zorunda olduğu senaryo tarzında sormaktır.", "source": "Soru Güvenliği ve Özgünlük", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınav Kağıdını Geri Verme Töreni: Kağıtları en yüksekten en düşüğe sırayla okuyarak dağıtmak düşük alanları ezmektir; kağıtlar sessizce, kapalı olarak ve her öğrenciye göz temasıyla teslim edilmelidir.", "source": "Öğrenci Onuru Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenme Çıktısının Yaşamsallığı: Bir sorunun sonunda öğrenci 'Ben bunu gerçek hayatta nerede kullanacağım?' sorusuna otomatikman cevap bulabilmelidir.", "source": "Bağlamsal Soru Tasarımı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Nöbet Görevi Esasları: Nöbet görevi, ders görevinin olmadığı boş günlere verilemez. Nöbet görevi için haftada en fazla 3 saat ek ders ücreti tahakkuk ettirilir.", "source": "MEB Yönetici ve Öğretmen Ders Saatleri Kararı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Doğum Sonrası Nöbet Muafiyeti: Kadın öğretmenlere doğum yaptığı tarihten itibaren 2 yıl süreyle istememeleri halinde nöbet görevi verilemez.", "source": "MEB Ortaöğretim ve İlköğretim Kurumları Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mazeret İzni Süreleri (657 DMK): Evlilik halinde 7 gün, eşin doğum yapması halinde (babalık izni) 10 gün, anne-baba-eş-çocuk-kardeş vefatında 7 gün mazeret izni verilir.", "source": "657 Sayılı Devlet Memurları Kanunu Madde 104", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yıllık İzin Hakkı: Öğretmenler yaz tatili ve ara tatillerde izinli sayıldıklarından, hizmet yılına bağlı normal memur yıllık izni uygulamasına tabi değildirler.", "source": "657 DMK Madde 103", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Resmi Tatil ve İdari Tatillerde Ek Ders: Kar tatili, resmi tatil veya idari izin gibi mülki amir kararıyla tatil edilen günlerde öğretmenlerin üzerindeki ders görevleri yapılmış sayılarak ek dersleri ödenir.", "source": "MEB Ders ve Ek Ders Saatlerine İlişkin Karar", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Maaş Karşılığı Ders Saatleri: Branş öğretmenleri için haftalık maaş karşılığı 15 saat, sınıf öğretmenleri için ise 18 saattir. Üzeri ek ders olarak değerlendirilir.", "source": "MEB Ek Ders Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zorunlu Ek Ders Sınırı: Branş öğretmenlerine maaş karşılığı olan 15 saatin üzerine ihtiyaç halinde haftada 6 saate kadar zorunlu ek ders görevi verilebilir; fazlası isteğe bağlıdır.", "source": "657 DMK & MEB Mevzuatı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ders Dışı Eğitim Çalışmaları (Egzersiz): İzcilik, spor, satranç, tiyatro, resim, müzik veya bilim olimpiyatı gibi egzersiz çalışmaları haftada en fazla 6 saat olarak açılabilir.", "source": "MEB Ders Dışı Çalışmalar Genelgesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Haftalık Ders Dağıtımında Pedagojik Esaslar: Ders programı hazırlanırken derslerin günlere dengeli dağıtılması, blok derslerin öğrencilerin dikkatini boğmayacak şekilde planlanması esastır.", "source": "MEB Okul Öncesi ve İlköğretim Kurumları Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf Öğretmenliği ve Kulüp Ek Dersi: Bir sınıfın rehberliğini veya bir sosyal kulüp danışmanlığını yürüten öğretmene haftada 2 saat ek ders ücreti ödenir.", "source": "MEB Ek Ders Kararı Madde 6", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hazırlık ve Planlama Ek Dersi: Öğretmenlere okuttukları her 10 saat ders için 1 saat hazırlık ve planlama ek dersi verilir; haftada en fazla 3 saate kadar tahakkuk eder.", "source": "MEB Ek Ders Kararı Madde 11", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hizmet İçi Eğitim Süreci ve ÖBA: Öğretmen Bilişim Ağı (ÖBA) üzerinden tamamlanan uzaktan eğitimler MEBBİS hizmet içi eğitim modülüne otomatik işlenir ve kariyer basamaklarında puan sağlar.", "source": "ÖBA ve Öğretmen Yetiştirme Genel Müdürlüğü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kılık Kıyafet ve Yönetmelik Hakları: Öğretmenler mesleğin vakar ve ciddiyetine uygun, sade ve temiz bir giyim kuşamla derslere girer; mevzuat çerçevesinde sendika kararları da uygulanabilir.", "source": "Kamu Kurum ve Kuruluşlarında Kılık Kıyafet Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dilekçe Hakkı ve Cevap Süresi: 3071 sayılı Dilekçe Kanunu'na göre kurum amirine verilen resmi dilekçelere en geç 30 gün içinde yazılı ve gerekçeli cevap verilmesi zorunludur.", "source": "3071 Sayılı Dilekçe Hakkının Kullanılmasına Dair Kanun", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Disiplin Soruşturmasında Savunma Hakkı: Savunma hakkı tanınmadan memura hiçbir disiplin cezası verilemez; öğretmene savunmasını yapması için en az 7 gün süre tanınır.", "source": "657 DMK Madde 130", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Disiplin Cezalarının Sicilden Silinmesi: Uyarma ve kınama cezaları 5 yıl, aylıktan kesme ve kademe ilerlemesinin durdurulması cezaları 10 yıl sonra iyi hal şartıyla sicilden sildirilebilir.", "source": "657 DMK Madde 133", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hastalık Raporlarının İzne Çevrilmesi: Alınan sağlık raporları okul müdürlüğüne gecikmeksizin intikal ettirilir ve idare tarafından mevzuata uygun olarak hastalık iznine dönüştürülür.", "source": "Devlet Memurlarına Verilecek Hastalık Raporları Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Refakat İzni Esasları: Anne, baba, eş ve çocukların ağır kaza veya hayati tehlike içeren hastalıklarında, sağlık kurulu raporuyla belgelenmek şartıyla 3 aya kadar refakat izni verilebilir.", "source": "657 DMK Madde 105", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "BEP (Bireyselleştirilmiş Eğitim Programı) Zorunluluğu: Özel eğitim ihtiyacı olan (kaynaştırma) her öğrenci için okul BEP birimi tarafından ders bazlı özel öğrenme çıktıları belirlenmesi yasal zorunluluktur.", "source": "MEB Özel Eğitim Hizmetleri Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Destek Eğitim Odası Hakkı: Kaynaştırma öğrencileri için okulda açılan Destek Eğitim Odası'nda ders veren öğretmenlere ek ders ücreti %25 artırımlı olarak ödenir.", "source": "MEB Ek Ders Kararı Madde 8", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Özel Eğitim Sınıfı Ek Ders Artırımı: Özel eğitim sınıflarında ve hastane sınıflarında görev yapan öğretmenlerin ek ders ücretleri yasal olarak %25 fazlasıyla tahakkuk eder.", "source": "657 DMK Ek Ders Düzenlemeleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınav Görevleri ve Ücretleri: ÖSYM, MEB e-Sınav ve Açık Lise gibi merkezi sınavlarda salon başkanı ve gözetmen ücretleri KBS sistemi üzerinden bağımsız olarak yatırılır.", "source": "MEB Merkezi Sınav Yönergesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Veli Toplantısı Evrakları: Dönemde en az bir kez yapılan şube veli toplantısının tutanakları, imza sirküleri ve alınan kararlar şube rehber öğretmeni tarafından okul idaresine teslim edilir.", "source": "Rehberlik Hizmetleri Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zümre Öğretmenler Kurulu Kararları: Sene başı, dönem ortası ve sene sonunda yapılan zümre toplantı tutanakları okulun eğitim kalitesinin resmi anayasasıdır; müfredat planı buna göre yürütülür.", "source": "MEB Eğitim Kurulları ve Zümreleri Yönergesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sosyal Kulüp Dosyası: Her kulüp danışman öğretmeni yıllık çalışma planı, toplum hizmeti projesi ve öğrenci listesini içeren kulüp dosyasını düzenli olarak tutmakla yükümlüdür.", "source": "MEB Sosyal Etkinlikler Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenci İzin Verme Yetkisi: Derste rahatsızlanan bir öğrenciye öğretmen tarafından revir veya nöbetçi idareciye gitmesi için imzalı sevk pusulası verilmelidir; öğrenci başıboş bırakılamaz.", "source": "Okul Güvenliği Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğretmenin Hukuki Sorumluluğu (Gözetim Görevi): Öğretmen, derste ve nöbet saatinde öğrencilerin can güvenliğini gözetmekle yasal olarak mükelleftir; sınıfı izinsiz terk etmemelidir.", "source": "Borçlar Kanunu ve TCK İlgili Maddeleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kişisel Verilerin Korunması (KVKK): Öğrencilerin fotoğraflarını, sınav kağıtlarını veya özel durumlarını velinin yazılı açık rızası olmadan sosyal medyada paylaşmak yasal suç teşkil eder.", "source": "6698 Sayılı KVKK ve MEB Genelgesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "E-Okul Not Giriş Süreleri: Sınav tarihinden itibaren en geç 10 iş günü içinde sınav sonuçlarının e-Okul sistemine girilmesi ve öğrencilere duyurulması yönetmelik gereğidir.", "source": "MEB Ortaöğretim ve Temel Eğitim Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınav Kağıtlarının Saklanma Süresi: Yazılı sınav kağıtları ve performans görevleri okul idaresi arşivinde en az 1 yıl süreyle saklanmak zorundadır; sonrasında tutanakla imha edilir.", "source": "Resmi Yazışma ve Arşiv Mevzuatı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınav Sonucuna İtiraz Süreci: Öğrenci veya veli, sınav sonucunun ilanından itibaren 5 iş günü içinde okul müdürlüğüne yazılı itirazda bulunabilir; komisyon kağıdı yeniden inceler.", "source": "MEB Sınav İtiraz Yönergesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yabancı Uyruklu Öğrencilerin Eğitimi (PIKTES): Uyum sınıflarında görev alan veya yabancı uyruklu öğrencilere Türkçe öğreten öğretmenler ilgili mevzuat kapsamında ek haklara sahiptir.", "source": "PIKTES Proje Yönergesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Rehberlik ve Psikolojik Danışma Servisi Sevk: Sınıfta ciddi davranış veya uyum sorunu yaşayan öğrenci için 'Psikolojik Destek Sevk Formu' doldurularak PDR servisine resmi sevk yapılır.", "source": "MEB PDR Hizmetleri Kılavuzu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İhmal ve İstismar Bildirim Yükümlülüğü: Çocuk ihmali veya istismarı şüphesi duyan bir öğretmenin durumu derhal okul idaresine ve adli mercilere bildirmesi yasal bir zorunluluktur.", "source": "TCK Madde 279 & Çocuk Koruma Kanunu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sendikal Faaliyet ve Eylem Güvencesi: Anayasa ve uluslararası sözleşmeler gereği, sendikanın aldığı yasal karar doğrultusunda yapılan iş bırakma eylemleri disiplin cezasına konu edilemez.", "source": "Danıştay ve Anayasa Mahkemesi İçtihatları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ödül ve Başarı Belgesi Kriterleri: Üstün gayret ve başarı gösteren öğretmenlere ilçe milli eğitim müdürü, kaymakam veya vali tarafından Başarı Belgesi, 3 başarı belgesi alana ise Üstün Başarı Belgesi verilir.", "source": "657 DMK Madde 122", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Maaşla Ödüllendirme: Üstün Başarı Belgesi alan öğretmenler arasından komisyon değerlendirmesiyle en yüksek puana sahip olanlara maaş ödülü verilebilir.", "source": "MEB Ödül Yönergesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kariyer Basamakları (Uzman ve Başöğretmen): Belirlenen mesleki kıdem ve eğitim şartlarını tamamlayan öğretmenler Uzman Öğretmen ve Başöğretmen unvanı ve ek tazminat hakkı kazanır.", "source": "Öğretmenlik Mesleği Kanunu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İl İçi ve İl Dışı Yer Değiştirme: Her yıl mayıs-haziran döneminde MEBBİS üzerinden hizmet puanı üstünlüğüne göre yer değiştirme başvuruları alınır; hizmet puanı adil dağılımın esasıdır.", "source": "MEB Atama ve Yer Değiştirme Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mazerete Bağlı Yer Değiştirme (Eş ve Sağlık Durumu): Eş durumu veya sağlık mazereti bulunan öğretmenler yarıyıl ve yaz tatillerinde mazeret atamasına başvurma hakkına sahiptir.", "source": "MEB Atama Mevzuatı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Norm Kadro Fazlası (Artığı) Öğretmenler: Okuldaki ders saatinin azalması durumunda hizmet puanı en düşük olan öğretmen norm fazlası olur; ilçe emrine veya ihtiyaç olan okullara atanır.", "source": "MEB Norm Kadro Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ders Dışı Okul Gezileri İzni: Okul dışına yapılacak günübirlik veya yatılı geziler için gezi planı, veli izin belgeleri ve araç sözleşmesi en az 7 gün önceden idareye sunulup onay alınmalıdır.", "source": "MEB Okul Gezileri Çerçeve Sözleşmesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Bayrak Töreni Disiplini: Pazartesi sabahı ve Cuma akşamı yapılan İstiklal Marşı bayrak törenlerine tüm idareci ve öğretmenlerin eksiksiz katılması milli ve mesleki bir görevdir.", "source": "Milli Eğitim Bakanlığı Bayrak Törenleri Yönergesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğretmenler Kurulu Kararları Bağlayıcılığı: Sene başında Öğretmenler Kurulu'nda oy çokluğuyla alınan kararlar mevzuata aykırı olmamak kaydıyla tüm okul personeli için bağlayıcıdır.", "source": "Eğitim Kurumları Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Okul Aile Birliği ile Mesleki Mesafe: Öğretmenler Okul Aile Birliği yönetimine seçilebilir; ancak aidat veya bağış toplama gibi nakdi işlemler kesinlikle öğretmen tarafından yürütülemez.", "source": "MEB Okul Aile Birliği Yönetmeliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf İçi Kamera Yasağı: Sınıfın içine ders esnasını kaydedecek şekilde güvenlik kamerası yerleştirilmesi hukuka ve kişilik haklarına aykırıdır; kameralar sadece ortak alanlarda olabilir.", "source": "Danıştay Emsal Kararı & KVKK", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğretmenler Odası Mahremiyeti: Öğretmenler odası, eğitimcilerin zihinsel dinlenme ve mesleki paylaşım alanıdır; öğrencilerin ve velilerin izinsiz girişi sınırlandırılmalıdır.", "source": "Kurum Kültürü ve Çalışma Ortamı Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mesleki Çalışma Dönemi (Seminer): Eğitim öğretim yılı başı ve sonunda yapılan mesleki çalışma dönemleri ek ders karşılığı olup öğretmenlerin pedagojik gelişimini hedefler.", "source": "MEB Çalışma Takvimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Telif Hakları ve Ders Notları: Öğretmenin kendi emeğiyle hazırladığı özgün ders notları ve materyalleri fikir ve sanat eserleri kanunu kapsamında telif hakkına tabidir.", "source": "5846 Sayılı Fikir ve Sanat Eserleri Kanunu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Emeklilik Başvuru Dönemleri: Öğretmenler mevzuat gereği eğitim öğretim yılının aksamaması için emeklilik başvurularını kural olarak haziran ve temmuz aylarında yaparlar.", "source": "5510 Sayılı Sosyal Sigortalar ve Genel Sağlık Sigortası Kanunu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ses Telleri ve Hidrasyon: Ses tellerinin (vokal kordların) sağlıklı titreşmesi için günde en az 2-2.5 litre oda sıcaklığında su tüketilmelidir. Kahve ve çay idrar söktürücü olduğundan suyun yerini tutmaz.", "source": "Kulak Burun Boğaz & Foniyatri Uzmanları Derneği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Boğaz Temizleme Refleksinin Zararı: 'Hımm-hımm' diyerek boğazı kazımak iki ses telini birbirine sertçe çarparak mikrotravma yaratır. Bunun yerine bir yudum su için veya sertçe yutkunun.", "source": "Ses Hijyeni Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Diyafram Nefesi ile Konuşma: Sadece göğüsten alınan sığ nefesle bağırmak ses tellerinde nodül ve polip oluşturur. Konuşurken nefesi karın ve diyafram boşluğundan yönlendirin.", "source": "Vokal Terapi Metodolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfta Mikrofon ve Ses Yükseltici Kullanımı: Geniş amfilerde veya kalabalık sınıflarda taşınabilir bel tipi mikrofon kullanmak ses tellerine binen yükü %70 oranında azaltır.", "source": "Mesleki Ses Sağlığı Araştırması", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Fısıltıyla Konuşmanın Tehlikesi: Ses kısıklığı yaşadığınızda fısıldayarak konuşmak ses tellerini normal konuşmadan daha çok zorlar; fısıldamak yerine sessiz dinlenme (vokal istirahat) yapın.", "source": "Foniatrik İlkeler", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tahtada Yazı Yazarken Boyun Açısı: Tahtaya yazı yazarken kafayı sürekli aşırı yukarı kaldırmak servikal omurgayı sıkıştırır; tahtanın orta hizasını kullanmaya özen gösterin.", "source": "Ergonomi ve Omurga Sağlığı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ayakta Ders Anlatırken Ağırlık Dağılımı: Ağırlığı sürekli tek bir bacağa vermek bel fıtığı ve pelvik eğriliğe davetiye çıkarır; iki ayak omuz genişliğinde açık ve ağırlık eşit dağıtılmalıdır.", "source": "Fizyoterapi Uzmanları Notu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "20-20-20 Göz Kuralı: Akıllı tahta veya bilgisayar ekranına bakarken her 20 dakikada bir 20 saniye boyunca en az 20 fit (yaklaşık 6 metre) uzağa bakarak göz kaslarını gevşetin.", "source": "Göz Sağlığı ve Dijital Ergonomi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ayakkabı Seçimi ve Tabanlık: 6 saat beton zemin üzerinde ayakta kalan bir öğretmenin ayakkabısı sert kösele değil, topuk şokunu emen ortopedik veya spor tabanlı olmalıdır.", "source": "Mesleki Ayak Sağlığı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Teneffüste Ses Dinlenmesi: Ders aralarında sürekli öğretmenler odasında yüksek sesle sohbet etmek yerine 5 dakika sessiz kalarak ses tellerinin ödemini yatıştırın.", "source": "Ses Koçluğu Tavsiyesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tükenmişlik Sendromu (Burnout) Erken Belirtileri: Pazar akşamı başlayan yoğun kaygı, öğrencilere karşı tahammülsüzlük ve sürekli yorgunluk hissi profesyonel destek ve mola vaktinin geldiğini gösterir.", "source": "Christina Maslach Tükenmişlik Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Eşik Ritüeli (Decompression Ritual): Okuldan çıkıp eve girerken kapıda 1 dakika durun ve derin bir nefes vererek 'Bugünkü okul mesaisi burada bitti, şimdi ailem ve kendim için varım' deyin.", "source": "Psikolojik Sağlamlık Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Güne 3 Dakikalık Esneme ile Başlama: Sabah yataktan kalkınca omuz dairesi, boyun esnetme ve kedi-deve hareketi yapmak omurilik sıvısını hareketlendirir ve gün boyu enerjiyi korur.", "source": "Beden Farkındalığı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mide Reflüsü ve Ses Kısıklığı: Akşam geç saatte yemek yemek veya aşırı asitli içecekler gece uyurken asidin boğaza kaçıp ses tellerini yakmasına neden olur. Yastığınızı hafif yüksek tutun.", "source": "Gastroenteroloji ve Ses Sağlığı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Oda Havasının Nemi: Kışın kaloriferli sınıflarda hava aşırı kurur; sınıfta su kabı bulundurmak veya nemlendirici kullanmak boğaz kuruluğunu ve gıcığı önler.", "source": "Ortam Hijyeni Standartları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zümre Dayanışmasının Koruyucu Gücü: Zor bir veli veya disiplin sorunu yaşayan bir öğretmenin zümre arkadaşlarıyla duygusunu paylaşması yalnızlık hissini kırar ve stresi %50 azaltır.", "source": "Sosyal Destek ve Ruh Sağlığı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hayır Diyebilme Sınırı: Okulda her komisyona, her projeye ve her ek göreve evet demek tükenmişliğin bir numaralı sebebidir; önceliklerinizi belirleyin ve nazikçe sınır çizin.", "source": "Kişisel Sınır Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ders Esnasında Su Yudumlamak: Masanızda daima kapalı bir matara su bulunsun; her 15 dakikada bir küçük bir yudum su almak boğaz mukozasını nemli tutar.", "source": "Vokal Koruma Rutini", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zihinsel Detoks Günü: Haftanın bir gününü (tercihen Pazar gününün bir bölümünü) hiçbir e-Okul, MEBBİS veya veli WhatsApp mesajına bakmadan doğaya ve sevdiklerinize ayırın.", "source": "Dijital Denge İlkeleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ilık Ihlamur ve Adaçayı Terapisi: Boğazda yanma veya batma hissi başladığında kaynar olmayan ılık ıhlamur bal karışımı içmek ses telleri üzerindeki tahrişi hafifletir.", "source": "Doğal Vokal Destek", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Göz Temasıyla Dinlenme: Öğrenciler grup çalışması veya bireysel test çözerken öğretmenin masada sırtını dikleştirip gözlerini 30 saniye kapatması mikro bir zihinsel yenilenmedir.", "source": "Sınıfta Mikro Mola", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf Gürültüsüne Karşı 'Ses Yarışı' Yapmama: Sınıfın gürültüsü arttığında sesinizi onların üstüne çıkarmaya çalışmak vokal kord kanamasına yol açabilir; gürültüyü sesle değil sessizlikle yönetin.", "source": "Sınıf İklimi ve Vokal Güvenlik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "D Vitamini ve Güneş Işığı: Öğretmenler kapalı sınıflarda çalıştıkları için D vitamini eksikliği kronik yorgunluğun baş sebebidir; öğle arasında 15 dakika güneşe çıkmak şarttır.", "source": "Mesleki Biyokimya", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zihinsel Yeniden Çerçeveleme (Reframing): Yaramazlık yapan bir çocuğu 'Bana saygısızlık yapıyor' diye değil, 'Şu an dikkat çekmeye ve sevilmeye ihtiyacı var' diye okumak öğretmenin öfkesini şefkate dönüştürür.", "source": "Bilişsel Davranışçı Terapi (BDT)", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Duygusal Bulaşıcılığı Fark Etme: Sınıfa girdiğinizde sınıftaki negatif gerginliği üstünüze sünger gibi çekmek yerine, kendi içsel huzurunuzu sınıfa yayan bir verici (radyo) gibi davranın.", "source": "Duygusal Dayanıklılık", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ağır Çanta Taşıma Ergonomisi: Sınav kağıtları ve kitaplarla dolu çantayı tek omuzda taşımak skolyoz ve omuz ağrısı yapar; sırt çantası kullanılmalı ve ağırlık eşit dağıtılmalıdır.", "source": "Kas İskelet Sistemi Sağlığı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akşam Yürüyüşünün Nörolojik Faydası: Okul çıkışında yapılan 20 dakikalık tempolu bir doğa yürüyüşü beyindeki prefrontal korteksi rahatlatır ve ders yorgunluğunu süpürür.", "source": "Egzersiz ve Beyin Plastisitesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sıcak ve Soğuk Şokundan Kaçınma: Derste terleyip ardından teneffüste soğuk rüzgâra çıkmak veya buzlu su içmek ses tellerinde ani spazma yol açar; ılık su tercih edilmelidir.", "source": "Ses Hijyeni Notu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mizah ve Gülmenin Bağışıklığa Etkisi: Günde içtenlikle birkaç kez gülmek endorfin salgılatır, kan basıncını düşürür ve bağışıklık sistemini enfeksiyonlara karşı korur.", "source": "Psikonöroimmünoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kendine Şefkat (Self-Compassion): Her ders mükemmel geçmek zorunda değildir; bazen planlar aksar. Öğretmen kendi eksikliklerine karşı da şefkatli bir dost gibi yaklaşmalıdır.", "source": "Kristin Neff Öz Şefkat Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğretmenler Odasında Pozitif Dil: Öğretmenler odasında sürekli öğrencilerden veya sistemden şikayet eden toksik sohbetlerden uzak durup ilham verici projelere odaklanmak ruhu korur.", "source": "Mesleki Moral Çevresi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Nefes Farkındalığı (4-7-8 Tekniği): 4 saniyede burundan nefes al -> 7 saniye tut -> 8 saniyede ağızdan yavaşça ver. Bu teknik parasempatik sinir sistemini 1 dakikada devreye sokarak kaygıyı dindirir.", "source": "Dr. Andrew Weil Nefes Protokolü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfta Sıcaklık ve Havalandırma: İdeal sınıf sıcaklığı 20-22 derecedir. Her teneffüste pencerelerin karşılıklı açılarak sınıfın havasının tazelenmesi baş ağrısını önler ve oksijeni artırır.", "source": "Okul Sağlığı Kılavuzu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Magnezyum ve Kas Gevşemesi: Gün boyu ayakta duran bacak kaslarındaki krampları önlemek için akşamları magnezyum zengini besinler (badem, ceviz, muz, ıspanak) tüketilmelidir.", "source": "Beslenme ve Kas Sağlığı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Haftalık Bir Hobi Molası: Öğretmenlik dışında bir sanat, enstrüman, bahçe işi veya ahşap oymacılığı ile uğraşmak mesleki körlüğü engeller ve zihni taze tutar.", "source": "Yaratıcı Dinlenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ses Isınması Egzersizi (Lip Trill): Sabah okula giderken dudakları gevşek bırakıp 'Brrrr' sesiyle dudak titretmek ses tellerini zorlamadan güne uyandırır.", "source": "Şan ve Ses Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Boğaz Pastilleri Seçimi: Uyuşturucu içeren pastiller boğazdaki acı hissini maskelediği için ses tellerini daha çok zorlamanıza yol açabilir; gliserin ve bal içerikli yumuşatıcılar tercih edilmelidir.", "source": "İlaç ve Ses Terapisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Uyku Ortamının Karanlığı: Yatak odasında telefon ışığı veya sokak lambası melatonini baskılar; zifiri karanlık bir odada uyumak hücresel yenilenmeyi sağlar.", "source": "Kronobiyoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfta Yürürken Adım Sayımı: Günlük 8.000 - 10.000 adım atmak kalp ve damar sağlığını korur; sınıfta ders anlatırken sıraların arasında aktif dolaşmak bu hedefi kendiliğinden doldurur.", "source": "Kardiyovasküler Sağlık", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kendi Değerini Notlarla Ölçmeme: Bir öğretmenin mesleki kıymeti sınıfındaki sınav ortalamasıyla değil; öğrencilerin kalbine ektiği insanlık ve erdem tohumlarıyla ölçülür.", "source": "Maarif Ruhu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Eratosthenes'in Dünya'nın Çevresini Ölçmesi: M.Ö. 240 yılında İskenderiye'de yaşayan Eratosthenes, aynı gün ve saatte iki farklı şehirdeki kuyu gölgelerinin açısını (7.2 derece) ölçerek Dünya'nın çevresini %2 gibi inanılmaz bir hata payıyla hesaplamıştır.", "source": "Antik Bilim Tarihi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İbnü'l-Heysem ve Kamera Obscura: Karanlık bir odanın duvarında açılan küçük bir delikten dışarıdaki görüntünün karşı duvara ters yansıdığını keşfeden Heysem, modern fotoğraf makinelerinin ve gözün optik prensiplerinin temelini atmıştır.", "source": "İslam Bilim Mirası (Kitâbü'l-Menâzır)", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Alexander Fleming ve Küfün Mucizesi: 1928'de tatile çıkarken açık unuttuğu stafilokok bakteri kültürünün üzerinde yeşil bir küf mantarının bakterileri yok ettiğini fark eden Fleming, penisilini keşfederek tıpta devrim yapmıştır.", "source": "Tıbbi Keşifler Tarihi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Arşimet ve Su Yoğunluğu: Hamamda suya girdiğinde taşan suyun hacminin kendi vücut hacmine eşit olduğunu ve suyun kaldırma kuvvetini fark eden Arşimet, saf altından tacın içine gümüş katılıp katılmadığını bu yöntemle çözmüştür.", "source": "Fizik Tarihi Anekdotu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mendeleyev'in Periyodik Tablo Sezgisi: Elementlerin atom ağırlıklarına göre periyodik bir özellik gösterdiğini fark eden Mendeleyev, henüz keşfedilmemiş olan galyum, germanyum ve skandiyum gibi elementlerin boşluklarını bırakmış ve özelliklerini önceden tahmin etmiştir.", "source": "Kimya Tarihi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Cahit Arf ve Arf Değişmezi: 1941 yılında cebirsel geometri ve kuadratik formlar alanında geliştirdiği 'Arf Değişmezi', günümüzde kuantum bilgisayarlarından kodlama teorisine kadar küresel bilimde temel kabul edilir.", "source": "Türk Matematik Tarihi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Aziz Sancar ve DNA Onarımı: Hücrelerin UV ışınlarının DNA'da oluşturduğu hasarı 'Nükleotid Kesip Çıkarma Onarımı' mekanizmasıyla nasıl tamir ettiğini aydınlatan Aziz Sancar, 2015 Nobel Kimya Ödülü'nü ülkemize kazandırmıştır.", "source": "Biyokimya ve Genetik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Galileo'nun Katedral Avizesi Deneyi: Pisa Katedrali'ndeki sallanan bir avizenin nabız vuruşlarıyla periyodunu ölçen Galileo, salınım süresinin genişlikten bağımsız (izokronizm) olduğunu keşfedip sarkaçlı saatlerin kapısını aralamıştır.", "source": "Mekanik Bilimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Margaret Hamilton ve Apollo 11 Kurtarışı: 1969'da Apollo 11 Ay'a inerken bilgisayarın aşırı yüklenmesi sonucu sistemi çöküşten kurtaran öncelikli görev yazılımını elle yazan Margaret Hamilton, yazılım mühendisliği terimini dünyaya kazandırmıştır.", "source": "Uzay ve Yazılım Tarihi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "El-Cezerî'nin Otomatik Su Saatleri: 12. yüzyılda Diyarbakır Artuklu Sarayı'nda hidrolik güç ve dişli çarklarla çalışan fil saati ve otomatik abdest alma robotları yapan Cezerî, sibernetik ve robotiğin babasıdır.", "source": "Mühendislik Tarihi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Marie Curie'nin Fedakârlığı: Radyoaktiviteyi keşfedip iki farklı alanda (Fizik ve Kimya) Nobel kazanan tek bilim insanı olan Curie, Birinci Dünya Savaşı'nda seyyar röntgen araçlarıyla cephedeki binlerce askeri kurtarmıştır.", "source": "Nükleer Fizik Tarihi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Uluğ Bey ve Semerkant Rasathanesi: 15. yüzyılda inşa ettirdiği devasa sekstant ile 1018 yıldızın konumunu teleskop olmadan günümüz modern astronomi değerlerine saniyeler kadar yakın hesaplamıştır.", "source": "Astronomi Tarihi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Gregor Mendel ve Bezelyeler: Manastır bahçesinde binlerce bezelye bitkisini çaprazlayarak baskın ve çekinik gen yasalarını keşfeden Mendel, modern genetik biliminin temellerini atmıştır.", "source": "Genetik Bilimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Pisagor Teoremi ve Mısırlı İp Gericiler: Eski Mısırlılar, Nil taşkınlarından sonra tarlaları dik açıyla bölmek için 3-4-5 düğümlü ipler kullanırlardı; Pisagor bu pratik bilgiyi matematiksel olarak kanıtlamıştır.", "source": "Geometri Arkeolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kutup Yıldızı (Polaris) ve Yön Bulma: Kutup Yıldızı, Dünya'nın dönme ekseninin tam üzerinde yer aldığı için gece gökyüzünde konumu hiç değişmez; baktığı yön daima gerçek kuzeyi gösterir.", "source": "Doğada Yön Bulma Bilgisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Işık Yılı Bir Zaman Değil Mesafe Birimidir: Işık yılı bir zaman ölçüsü değil; ışığın boşlukta bir yılda kat ettiği yaklaşık 9.46 trilyon kilometrelik muazzam mesafedir.", "source": "Astrofizik Notu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "DNA Sarmalının Boyutu: Bir insan vücudundaki tüm hücrelerin DNA iplikçikleri uç uca eklenseydi, Güneş Sistemi'nin sınırlarına kadar gidip geri dönebilecek uzunlukta (yaklaşık 10 milyar km) olurdu.", "source": "Moleküler Biyoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ağaçların Mantar Ağıyla İletişimi (Wood Wide Web): Ormandaki ağaçlar köklerindeki mikoriza mantar ağları sayesinde birbirleriyle besin paylaşır, kuraklık veya böcek saldırısı olduğunda birbirlerine kimyasal sinyallerle uyarı gönderirler.", "source": "Ekoloji ve Doğa Bilimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Su Döngüsü ve Dinozorlar: Dünya'daki su miktarı milyarlarca yıldır sabittir; bugün içtiğimiz bir bardak su, milyonlarca yıl önce bir dinozorun içtiği veya buharlaştığı aynı moleküllerden oluşuyor olabilir.", "source": "Hidroloji ve Doğa Döngüleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Fotosentezin Hayati Dengesi: Bitkiler güneş ışığını, suyu ve karbondioksiti şekere ve oksijene dönüştürür; soluduğumuz oksijenin yaklaşık %70'ini karadaki ormanlar değil, okyanuslardaki mikroskobik fitoplanktonlar üretir.", "source": "Deniz Biyolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Altın Oran (Phi - 1.618): Ayçiçeği çekirdeklerinin dizilişinde, çam kozalağında, insan yüzünde ve Selçuklu taç kapılarında görülen altın oran, doğanın ve sanatın en estetik matematiksel ölçütüdür.", "source": "Matematik ve Estetik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Fibonacci Dizisi Doğada: 1, 1, 2, 3, 5, 8, 13... dizisindeki her sayı kendinden önceki ikisinin toplamıdır; çiçeklerin taç yaprak sayıları neredeyse istisnasız bu dizideki sayılardan biridir.", "source": "Biyo-Matematik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Helyumun Keşfi Önce Güneş'te Yapıldı: Helyum elementi Dünya'da bulunmadan önce, 1868 güneş tutulmasında Güneş ışığının spektroskopik analizi sırasında keşfedilmiş ve adını Yunan Güneş Tanrısı Helios'tan almıştır.", "source": "Spektroskopi Tarihi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Grafen: Dünyanın En İnce ve En Güçlü Malzemesi: Karbon atomlarının tek katmanlı altıgen dizilimi olan grafen, çelikten 200 kat daha güçlü, elektrik ve ısıyı bakırdan katbekat iyi ileten 2 boyutlu bir harikadır.", "source": "Nanoteknoloji ve Malzeme Bilimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kuantum Dolanıklık (Spooky Action): İki dolanık parçacık birbirlerinden evrenin iki zıt ucuna kadar uzaklaşsalar bile, birinde yapılan ölçüm anında diğerinin durumunu belirler; Einstein bunu 'uzaktan hayaletimsi etki' olarak adlandırmıştır.", "source": "Kuantum Mekaniği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kar Tanelerinin Altıgen Simetrisi: Su moleküllerinin donarken hidrojen bağlarının oluşturduğu açı (104.5 derece) nedeniyle her kar tanesi 6 köşelidir ve sıcaklık-nem değişimleri sebebiyle hiçbiri birbirinin tıpatıp aynısı değildir.", "source": "Kristalografi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Termodinamiğin İkinci Yasası (Entropi): Evrendeki düzensizlik (entropi) kendiliğinden daima artma eğilimindedir; düzenli bir çalışma ortamı ve bilgi inşası ancak sürekli enerji ve çaba harcayarak korunabilir.", "source": "Fizik Felsefesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Doppler Etkisi: Yaklaşan bir ambulansın siren sesinin tizleşmesi, uzaklaşırken ise kalınlaşması gibi; bizden uzaklaşan galaksilerin ışığı da kırmızıya kayar. Hubble, evrenin genişlediğini bu şekilde keşfetmiştir.", "source": "Kozmoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Gözdeki Kör Nokta (Blind Spot): Optik sinirin retinadan çıkıp beyne gittiği noktada ışık reseptörü (koni ve çubuk) bulunmaz; fakat beynimiz iki gözden gelen bilgiyi birleştirerek bu boşluğu fark ettirmeden doldurur.", "source": "Göz Fizyolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Toprağın Kokusu (Petrikor): Yağmur yağdıktan sonra duyulan o huzur verici toprak kokusu, aslında toprakta yaşayan 'Aktinobakteri' isimli bakterilerin ürettiği 'Geosmin' molekülüdür.", "source": "Toprak Biyolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hücredeki Enerji Santrali: Mitokondri: Hücrelerimizin besinleri parçalayarak ATP enerjisi ürettiği mitokondriler, kendi bağımsız DNA'larına sahiptir ve bize sadece annemizden miras kalır.", "source": "Hücresel Biyoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Gökkuşağının Gerçek Şekli Tam Bir Çemberdir: Yerden baktığımızda ufuk çizgisi kestiği için yarım daire görürüz; fakat uçaktan veya yüksek bir kuleden baktığımızda gökkuşağı tam bir daire olarak görünür.", "source": "Meteorolojik Optik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Karasineklerin Uçuş Akrobasisi: Bir karasinek saniyede 200 kez kanat çırpar ve yön değiştirmek için gözleri saniyede 250 kare işleyebilir; bu yüzden elimizle vurmak istediğimizde hareketi ağır çekimde görür.", "source": "Biyo-Mekanik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Periyodik Tablodaki 'J' ve 'Q' Harfleri: İngilizce periyodik tabloda 118 elementin sembolleri arasında 'J' harfi hiçbir elementin sembolünde yer almayan tek harftir.", "source": "Kimya Trivia", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Okyanus Tabanındaki Hidrotermal Bacalar: Güneş ışığının hiç ulaşmadığı zifiri karanlık okyanus diplerinde, volkanik bacalardan çıkan sülfürü kemosentezle enerjiye dönüştürerek yaşayan dev tüp solucanları ve kör karidesler bulunur.", "source": "Derin Deniz Ekolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Güneş'in Işığı Bize 8 Dakika 20 Saniyede Ulaşır: Güneş'e baktığımızda onun şu anki halini değil, 8 dakika 20 saniye önceki geçmişini görürüz; gökyüzüne bakmak bir zaman makinesine bakmak gibidir.", "source": "Gökbilim Temelleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Karbon Döngüsü ve Elmas: Kurşun kalemimizin ucu olan grafit ile paha biçilemez elmas tamamen aynı atomdan (Karbon) oluşur; aralarındaki tek fark atomların kristal kafes dizilimidir.", "source": "Mineraloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ahtapotların 3 Kalbi ve Mavi Kanı Vardır: Ahtapotların kanında demir yerine bakır içeren hemosiyanin proteini bulunduğu için kanları oksijen taşıdığında mavi renk alır.", "source": "Deniz Canlıları Biyolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Gezegenlerin En Büyüğü: Jüpiter: Jüpiter o kadar büyüktür ki, Güneş Sistemi'ndeki diğer tüm gezegenler bir araya gelse bile Jüpiter'in içine sığabilir ve ünlü 'Kırmızı Leke'si Dünya'dan daha geniştir.", "source": "Gezegenler Bilimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ses Boşlukta Yayılmaz: Ses mekanik bir dalga olduğu için titreşecek bir maddeye (hava, su, katı) ihtiyaç duyar; bu yüzden uzay boşluğunda en büyük patlamalar bile mutlak bir sessizlik içinde gerçekleşir.", "source": "Dalga Mekaniği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akıllı Tahtada 'Örtme' (Curtain) Aracı: Sorunun veya metnin cevabını bir perde aracıyla kapatıp, sınıfla tartıştıktan sonra perdeyi yavaşça aşağı çekmek dikkati en üst düzeyde tutar.", "source": "İnteraktif Tahta Teknikleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Simülasyon Odaklı Fen Eğitimi (PhET): Soyut fizik veya kimya kavramlarını (Örn: atom altı parçacıklar, devre akımı) görsel ve dinamik laboratuvar simülasyonlarıyla deneyimletmek öğrenmeyi somutlaştırır.", "source": "STEM Eğitim Teknolojileri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yapay Zekâyı Ders Planlamasında Asistan Olarak Kullanma: Yapay zekâya doğrudan plan yazdırmak yerine, 'Bu öğrenme çıktısı için 7. sınıf öğrencilerine yönelik 3 farklı tartışma senaryosu üret' diyerek yaratıcı alternatifler türetin.", "source": "Eğitimde Yapay Zekâ İlkeleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dijital Zihin Haritaları: Öğrencilere konunun özetini kağıt yerine Coggle veya MindMeister gibi interaktif araçlarla çizdirmek kavramlar arası bağlantıları keşfetmelerini sağlar.", "source": "Görsel Düşünme Yazılımları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kahoot ve Quizizz'de 'Grup Modu': Bireysel hız yarışması kaygıyı tetikleyebilir; öğrencileri 3'erli takımlar haline getirip takım puanıyla yarıştırmak işbirliğini güçlendirir.", "source": "Oyunlaştırma Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "QR Kodlu Soru İstasyonları: Sınıfın farklı köşelerine QR kodlar yapıştırın; öğrenciler tablet veya telefonla kodu okutarak soruyu açsın ve cevapları çalışma kağıdına işlesin.", "source": "Mobil Öğrenme Etkinliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sanal Müze Gezileri (360 Derece): Tarih veya görsel sanatlar dersinde Topkapı Sarayı, Ayasofya veya Louvre Müzesi'ni akıllı tahtada 360 derece gezmek mekân hissi kazandırır.", "source": "Dijital Kültür Mirası", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Google Earth ile Coğrafya Keşfi: Dağ oluşumlarını, fay hatlarını ve kanyonları tahtadaki 2 boyutlu harita yerine Google Earth 3D yüzey modeliyle inceletmek coğrafi derinlik katar.", "source": "Uzamsal Coğrafya Araçları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Canva ile Görsel İnfografik Hazırlatma: Öğrencilere klasik yazılı ödev yerine bir tarihi olayı veya fen konusunu özetleyen tek sayfalık bir infografik tasarlatmak görsel okuryazarlığı besler.", "source": "Tasarım Odaklı Öğrenme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Padlet ile Dijital Fikir Panosu: Soru sorduktan sonra tüm öğrencilerin kendi cümleleriyle aynı dijital panoya yapışkan not bırakması, çekingen öğrencilerin de sesini duyurur.", "source": "Eşzamanlı Katılım Aracı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tinkercad ile 3D Tasarım Mantığı: Geometri veya teknoloji tasarım dersinde prizmaları ve silindirleri birleştirerek 3 boyutlu model yaptırmak uzamsal zekâyı geliştirir.", "source": "3D Modelleme Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Scratch ile Blok Tabanlı Kodlama: Bir fen kuralını veya matematik formülünü animasyona dönüştüren bir blok kod yazmak algoritmik düşünme becerisini perçinler.", "source": "Bilişimsel Düşünme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Podcast Hazırlatma Ödevi: Öğrencilerin seçtikleri bir yazar veya bilim insanı hakkında 3 dakikalık bir ses kaydı (podcast) hazırlayıp sınıfla paylaşması hitabet gücünü artırır.", "source": "Sesli İfade Becerisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dijital Hikâye Anlatımı (Digital Storytelling): Bir konuyu görseller, müzik ve kendi seslendirmesiyle birleştiren 1 dakikalık kısa bir video haline getirtmek kalıcı sahiplenme üretir.", "source": "Çoklu Ortam Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "GeoGebra ile Dinamik Geometri: Bir üçgenin köşesini fareyle çekiştirirken iç açılar toplamının 180 derece kaldığını veya çevrel çemberin merkezini canlı görmek ispat mantığını kavratır.", "source": "Dinamik Matematik Yazılımı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf İçi Dijital Zamanlayıcı Kullanımı: Grup çalışmalarında veya test çözümlerinde tahtaya dev bir kum saati veya sayaç yansıtmak zaman disiplini kazandırır.", "source": "Görsel Zaman Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ters Arama ile Görsel Doğrulama: Öğrencilere internette gördükleri her resmin gerçek olmadığını, görseli Google Görsellerde aratarak sahte haberleri nasıl tespit edeceklerini öğretin.", "source": "Medya Okuryazarlığı ve Teyitçilik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dijital Tahtayı Karalama Değil Etkileşim Alanı Yapma: Öğretmenin sadece tahtada slayt ilerletmesi yerine, öğrencileri tahtaya kaldırıp nesneleri sürükletmesi veya grafik çizdirmesi gerekir.", "source": "İnteraktif Tahta Kullanım İlkesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Siber Zorbalık Farkındalığı: WhatsApp gruplarında bir arkadaşı gruptan atmanın veya komik fotoğrafını izinsiz yaymanın akran zorbalığı ve suç olduğunu sınıfta açıkça konuşun.", "source": "Siber Güvenlik ve Hukuk", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "E-Kitap ve Açık Kaynak Kütüphaneler: MEB EBA Kütüphanesi ve TÜBİTAK Popüler Bilim yayınlarının PDF arşivlerine öğrencilerin ücretsiz nasıl erişebileceğini derste gösterin.", "source": "Açık Erişim Kültürü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kelime Bulutu (Word Cloud) ile Giriş: Bir kavram hakkında öğrencilerin söylediği ilk kelimeleri Mentimeter gibi bir araçla tahtada toplayıp anında dev bir kelime bulutuna dönüştürün.", "source": "Bilişsel Çağrışım Görselleştirme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Formlar ile Anında Sınav Analizi: Google Formlar veya Microsoft Forms üzerinden yapılan testlerde her sorunun başarı yüzdesini anında sütun grafiklerle görüp zayıf öğrenme çıktılarına geri dönün.", "source": "Veriye Dayalı Öğretim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dijital Dosya Düzenleme Becerisi: Öğrencilere dosyaları 'adsız1.docx' yerine 'Tarih_Proje_AdSoyad.pdf' formatında kaydetme ve klasörleme disiplinini öğretmek ömür boyu fayda sağlar.", "source": "Temel Dijital Okuryazarlık", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ekran Süresi Hijyeni: Öğrencilere gece yatmadan 1 saat önce mavi ışık saçan telefon ve tabletleri bırakmanın melatonin salgısı ve öğrenme kalitesi için şart olduğunu anlatın.", "source": "Uyku Hijyeni ve Teknoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Algoritmada Hata Ayıklama (Debugging) Sabrı: Kodlamada çalışan ilk kod nadirdir; hatayı sabırla arayıp adım adım düzeltme alışkanlığı hayattaki problem çözme dirayetini besler.", "source": "Yazılım Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yapay Zekâ Metinlerinde İntihal Sınırı: Öğrencilere ChatGPT veya benzeri araçların bir başlangıç taslağı olabileceğini, fakat doğrudan kopyalanan metnin kendi düşüncelerini körelteceğini açıklayın.", "source": "Akademik Etik ve Yapay Zekâ", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Desmos ile Fonksiyon Dansı: Matematikte f(x) fonksiyonunun katsayıları değiştikçe grafiğin nasıl daralıp genişlediğini veya kaydığını kaydırıcılarla canlı göstermek formülleri canlandırır.", "source": "Görsel Fonksiyon Analizi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çevrimiçi Sözlük Kullanım Alışkanlığı: Yabancı dil dersinde tek kelimelik çeviri siteleri yerine kelimenin cümle içindeki kullanımını ve telaffuzunu veren kaliteli lügatleri tanıtın.", "source": "Dil Öğretimi Teknolojileri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ses Kaydıyla Kendi Okumasını Dinleme: Türkçe dersinde öğrencilerin bir şiiri kaydedip sonra kulaklıkla kendi vurgu ve tonlamasını dinlemesi diksiyonu hızla düzeltir.", "source": "Öz Değerlendirmeli Okuma", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İnteraktif Zaman Çizelgesi (Timeline): Tarih dersinde olayları kronolojik bir dijital şerit üzerinde resimler ve kaynak bağlantılarıyla dizmek neden-sonuç zincirini netleştirir.", "source": "Tarihsel Kronoloji Yazılımları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Artırılmış Gerçeklik (AR) ile Anatomi: Bir tablet kamerasıyla insan vücudunun organlarını veya kalbin çalışmasını sıranın üzerinde 3 boyutlu canlandırmak tıp seviyesinde merak uyandırır.", "source": "AR Eğitim Uygulamaları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Bulut Depolama ile Grup Çalışması: Ortak bir döküman üzerinde 4 öğrencinin aynı anda farklı renkli imleçlerle çalışıp birbirinin yazdığını düzenlemesi gerçek işbirliğini öğretir.", "source": "Kolektif Belge Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dijital Güvenlik: Güçlü Şifre Oluşturma: Öğrencilere doğum tarihi veya 123456 yerine en az 12 karakterli, harf-rakam-sembol içeren karmaşık parolalar kurma bilinci aşılayın.", "source": "Kişisel Veri Güvenliği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Görsel Telif Hakları (Creative Commons): Öğrencilere bir projede Google'dan rastgele resim kopyalamak yerine telifsiz veya atıflı görseller (Unsplash, Pixabay) kullanma ahlakını öğretin.", "source": "Dijital Telif Etiği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akıllı Tahtada 'Geri Al' (Undo) Güvencesi: Tahtada yapılan bir hatanın tek bir dokunuşla geri alınabilmesi, öğrencilerin hata yapmaktan korkmadan cesurca çizim yapmasını sağlar.", "source": "Psikolojik Rahatlık ve Teknoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Webinar ve Canlı Bilim İnsanı Bağlantısı: İmkan varsa sınıfa uzaktan görüntülü bağlantıyla bir astronom, arkeolog veya mühendisi 15 dakika bağlamak vizyonu fersah fersah genişletir.", "source": "Dünyayı Sınıfa Getirme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dijital Portfolyo Web Sitesi: Lise öğrencilerine Google Sites veya benzeri ücretsiz araçlarla kendi projelerini sergiledikleri bir kişisel portfolyo açtırmak üniversite ve iş hayatına hazırlar.", "source": "Kariyer Becerileri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Mikrobit ile Fiziksel Programlama: Küçük bir devre kartının üzerindeki LED ekrana yazı yazdırmak veya sıcaklık sensörüyle sınıfın ısısını ölçtürmek kodlamayı fiziksel dünyaya bağlar.", "source": "Fiziksel Bilişim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kavram Karşılaştırma Tabloları: Çevrimiçi dinamik tablolarda iki teoriyi veya canlı sınıfını kriterlere göre sıralayıp filtrelemek analitik sınıflama kabiliyetini biler.", "source": "Veri Analitiği Temelleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Teknoloji Bir Amaç Değil Araçtır Kuralı: En pahalı teknoloji bile pedagojik bir amaca, etkileşime ve sıcak bir öğretmen sevgisine hizmet etmiyorsa hiçbir değer taşımaz.", "source": "Eğitim Teknolojileri Felsefesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "DEHB (Dikkat Eksikliği ve Hiperaktivite): DEHB'li öğrenciye 'Dikkatsiz' demek yanlıştır; onun sorunu dikkatsizlik değil, dikkatini regüle edememesidir. Onu ön sıralara oturtun ve yönergeleri tek tek verin.", "source": "Özel Eğitim ve Nörogelişim Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "DEHB'de Fiziksel Hareket Molası: Sürekli kıpırdanan bir çocuğa tahtayı silme veya tebeşir getirme gibi meşru bir hareket görevi vermek enerjisini olumluya kanalize eder.", "source": "Sınıfta DEHB Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Disleksi (Özgül Öğrenme Güçlüğü): Disleksi bir zekâ geriliği değil, beynin yazılı dili farklı işlemesidir. 'b' ve 'd' harflerini karıştıran öğrenciye renkli zeminli kağıtlar ve geniş aralıklı yazılar sunun.", "source": "Disleksi Farkındalık Kılavuzu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dislekside Yüksek Sesle Zorla Okutmama: Disleksili bir çocuğu tüm sınıfın önünde habersizce tahtaya kaldırıp kitap okutmak ağır travma yaratır; ona önceden haber verip hazırlıklı okutun.", "source": "Kapsayıcı Eğitim İlkeleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Disgrafi (Yazma Güçlüğü): Yazısı aşırı düzensiz ve yavaş olan öğrencinin sınavlarını gerekirse sözlü veya dijital formda yapmak onun gerçek bilgi seviyesini ortaya çıkarır.", "source": "Özel Öğrenme Güçlüğü Notu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Diskalkuli (Matematik Öğrenme Güçlüğü): Rakamları ve büyüklükleri kavramakta zorlanan öğrenciye formül ezberletmek yerine fasulye, çubuk ve somut nesnelerle işlem yaptırın.", "source": "Matematik Öğrenme Güçlüğü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Özel Yetenekli Çocukların İhtiyacı: Sınıfın hızının çok önünde olan özel yetenekli öğrenciye aynı problemden 20 tane daha çözdürmek ceza gibidir; ona derinleşme ve proje araştırma rotası verin.", "source": "BİLSEM ve Özel Yetenekliler Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Özel Yeteneklilerde Asenkron Gelişim: Zihinsel yaşı 15 olan bir çocuğun duygusal yaşı 8 olabilir; onun zekâsına hayran kalırken duygusal olarak hala bir çocuk olduğunu unutmayın.", "source": "Üstün Zekâ ve Gelişim Psikolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Hafif Otizm Spektrumu (Asperger) Özelliği: Mecaz, kinaye ve şakaları anlamakta zorlanıp her şeyi harfi harfine (lafzi) algılarlar. Onlarla konuşurken net, somut ve doğrudan ifadeler kullanın.", "source": "Otizm Spektrum Bozukluğu Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Duyusal Hassasiyetler (Sensorimotor): Otizmli veya duyusal hassasiyeti olan bir çocuk için floresan lambanın vızıltısı veya tebeşir gıcırtısı dayanılmaz bir acı olabilir; ortamı sakinleştirin.", "source": "Duyusal Bütünleme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akran Zorbalığı Türleri: Zorbalık sadece fiziksel itme-kakma değildir; dedikodu yaymak, gruptan dışlamak ve alaycı lakap takmak da ağır birer psikolojik zorbalıktır.", "source": "Akran Zorbalığını Önleme Programı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zorbalıkta Seyirci (Bystander) Rolü: Zorbalığı besleyen en büyük güç seyircilerin gülmesi veya sessiz kalmasıdır. Sınıfta 'Zorbalığa sessiz kalmayan cesur arkadaşlar' kültürü inşa edin.", "source": "Dan Olweus Zorbalık Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zorba ile Kurbanı Yan Yana Oturtmama: Bir çatışma çözülene kadar zorbalığa maruz kalan çocuğu koruma altına almak ve kendini güvende hissettirmek ilk önceliktir.", "source": "Okul Güvenlik Protokolü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenciye 'Şikâyetçi' Dememe: Bir haksızlığı veya zorbalığı öğretmene haber veren çocuğa 'İspiyoncu' damgası vurulmasına izin vermeyin; güvenli bildirim kanalları açın.", "source": "Pozitif İklim Güvencesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "BEP Toplantılarında Ailenin Yeri: BEP hazırlanırken ailenin görüşü ve evdeki gözlemleri programa mutlaka dâhil edilmelidir; okul-aile ortaklığı olmadan özel eğitim yürütülemez.", "source": "MEB BEP Yönergesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İçe Kapanık (İntrovert) Öğrencileri Anlama: Sessiz ve sakin bir çocuk 'problemli' değildir; o enerjisini yalnızlıktan alır ve yazılı ifadede sözlüden çok daha derin olabilir.", "source": "Susan Cain - Sessizliğin Gücü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Aşırı Mükemmeliyetçi Öğrenci Kaygısı: 100 yerine 95 aldığında ağlayan bir çocuğa başarının notla değil çabayla ölçüldüğünü ve hataların doğal olduğunu sabırla aşılayın.", "source": "Çocukluk Kaygıları Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınav Kaygısında Bedensel Belirtiler: Mide bulantısı, baş ağrısı ve kalp çarpıntısı yaşayan öğrenciye 'Korkacak bir şey yok' demek işe yaramaz; duygusunu onaylayıp nefes egzersizi yaptırın.", "source": "Sınav Kaygısı Müdahale Rehberi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenilmiş Güçsüzlük Döngüsü: Sürekli 'Zaten yapamayacağım' diyen bir öğrencinin geçmişteki başarılarını hatırlatın ve 'Daha önce de zorlanmıştın ama başarmıştın' diyerek güven aşılayın.", "source": "Bilişsel Yeniden Yapılandırma", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Görsel Destekli Günlük Akış: Özel eğitim ve ilkokul sınıflarında günün ders programını resimli kartlarla tahtaya asmak, çocukların belirsizlik kaygısını sıfıra indirir.", "source": "Görsel Çizelge Yöntemi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Somutlaştırılmış Zaman Algısı: '10 dakika kaldı' demek yerine kum saati veya dijital görsel sayaç göstermek zaman algısı zayıf çocukların paniklemesini önler.", "source": "Zaman Yönetimi Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öfke Patlaması Anında Mantık Aramama: Bir çocuk öfke nöbeti geçirirken ona nasihat vermek veya hesap sormak yangına körükle gitmektir; önce sakinleşmesini bekleyin, sonra konuşun.", "source": "Duygusal Kriz Müdahalesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sakinleşme Köşesi (Calm Down Corner): Sınıfın bir köşesinde yumuşak minderler, stres topu ve resim defteri olan sessiz bir alan oluşturmak çocukların kendi duygularını regüle etmesini sağlar.", "source": "Pozitif Sınıf Ortamı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Duygu Çarkı Kullanımı: 'Kötüyüm' diyen bir öğrenciye Duygu Çarkı göstererek 'Kırgın mısın, hayal kırıklığı mı yaşıyorsun, yalnız mı hissediyorsun?' diye sormak duygusal okuryazarlık kazandırır.", "source": "Robert Plutchik Duygu Teorisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akran Destek Grubu (Buddy Sistemi): Sınıfa yeni gelen veya özel eğitime ihtiyacı olan bir öğrenciye şefkatli bir arkadaşını 'Rehber Eş' olarak atamak uyum sürecini yarıya indirir.", "source": "Kapsayıcı Okul Kültürü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Övgüde 'Sosyal Etiketleme' Tehlikesi: Bir çocuğu överken diğerlerini yermek ('Bakın Ali ne kadar uslu, siz de onun gibi olun') Ali'yi sınıfta hedef tahtası haline getirir; bireysel övgü bireysel kalmalıdır.", "source": "Grup Dinamikleri ve Pedagoji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Boşanmış Aile Çocuklarına Yaklaşım: Anne babası ayrılan çocuklarda suçluluk ve terk edilme kaygısı yüksektir; öğretmenin tutarlı sevgisi ve güvenli liman olması hayati bir kalkandır.", "source": "Travma Odaklı Okul Yaklaşımı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yası Olan Öğrenciye Yaklaşım: Yakınını kaybeden bir çocuğa 'Artık ağlama, cennete gitti' gibi bastırıcı sözler yerine 'Üzüntünü anlıyorum, buradayım ve seni dinlemeye hazırım' demek şifadır.", "source": "Çocuk ve Yas Psikolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kayıp ve Değişimlerde Rutinlerin Gücü: Hayatında sarsıntı yaşayan bir çocuk için okuldaki değişmeyen ders saatleri, zil sesi ve kurallar en büyük güvenlik duygusudur.", "source": "Psikolojik Dayanıklılık", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfta 'Sıfır Reddetme' İlkesi: Hiçbir çocuk zekâsı, engeli veya sosyoekonomik durumu yüzünden dışlanamaz; maarif her bir ferdi bağrına basan bir çatıdır.", "source": "Kapsayıcı Eğitim Felsefesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Görme Yetersizliği Olan Öğrenciye Alan: Sınıftaki eşyaların ve sıraların yerini sık sık değiştirmemek görme engelli öğrencinin güvenle hareket etmesini sağlar.", "source": "Erişilebilir Sınıf Ergonomisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İşitme Yetersizliğinde Dudak Okuma: İşitme cihazı kullanan öğrenciyle konuşurken arkası dönük tahtaya yazı yazarak değil, yüz yüze ve dudakların net görüleceği şekilde konuşulmalıdır.", "source": "İşitme Engelliler Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Fiziksel Engelli Öğrenciler İçin Ortak Alanlar: Okul gezilerinde ve bahçe oyunlarında bedensel engelli öğrencinin kenarda seyirci kalmayacağı uyarlanmış roller üretilmelidir.", "source": "Bütünleştirici Oyun Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akademik Benlik Saygısı: 'Ben bu derste başarısızım' inancı kırılmadan öğrenme başlayamaz; ilk hedef küçük bir başarıyla bu inancı sarsmaktır.", "source": "Benlik Kuramları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Çekingen Çocuğa Söz Verme Yolu: Sınıfın ortasında aniden söz vermek yerine, dersten önce sırasına gidip 'Bugün şu soruyu sana soracağım, hazırlanmak ister misin?' demek özgüvenini inşa eder.", "source": "Şefkatli Rehberlik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Soru Sormaktan Çekinen Sınıfı Kırma: 'Bunu anlamayacak ne var?' tepkisi sınıfta soru sormayı öldürür; en basit soruya bile 'Bunu sorman harika oldu' demek kapıları ardına kadar açar.", "source": "Psikolojik Güvenlik Kültürü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yaratıcı Çocuğun 'Tuhaf' Soruları: Müfredat dışı ve garip sorular soran bir çocuğu susturmak yerine 'Ne kadar sıra dışı bir bakış açısı, bunu teneffüste araştıralım' demek dehayı besler.", "source": "Yaratıcılık Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Lider Ruhlu Öğrencileri Olumluya Yönlendirme: Sınıfın doğal lideri olan haylaz bir öğrenciye disiplin cezası vermek yerine sorumluluk vermek tüm sınıfın dinamiğini pozitife çevirir.", "source": "Grup Dinamiği Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Adalet ile Eşitlik Arasındaki Fark: Herkese aynı boyutta ayakkabı vermek eşitliktir; herkese ayağına uyan ayakkabıyı vermek ise adalettir. Eğitimde asıl olan adalettir.", "source": "Eğitim Felsefesi İlkesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Rehberlik Servisi ile İşbirliği: Çözmekte zorlandığınız kronik bir davranış sorununda tek başınıza mücadele etmeyin; okul PDR servisiyle erken aşamada ortak plan yapın.", "source": "Okul Psikolojik Danışmanlığı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "'Pabucu Dama Atılmak' Deyiminin Hikâyesi: Osmanlı lonca teşkilatında (Ahilik) bir ayakkabıcı kalitesiz ve çürük ayakkabı üretirse, Ahiler heyeti o ayakkabıyı dükkânın damına atardı; bu, ustanın itibarının bittiğini ve meslekten men edildiğini gösterirdi.", "source": "Türk Kültürü ve Ahilik Teşkilatı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "'İki Dirhem Bir Çekirdek' Deyiminin Hikâyesi: Osmanlı'da altın paralar dirhem ve çekirdek (kırat) ile tartılırdı; 1 dirhem 16 çekirdekti. Giyimine aşırı özen gösteren ve şık giyinen zarif insanlara bu yüzden 'iki dirhem bir çekirdek' denirdi.", "source": "Kültür Tarihi ve Deyimler", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "'Çizmeyi Aşmak' Deyiminin Hikâyesi: Fransız ressam Delacroix sergisinde bir kunduracı tablodaki çizmeyi eleştirir, ressam düzeltir. Cesaret alan kunduracı pantolonu da eleştirmeye kalkınca ressam: 'Usta, çizmeyi aşma!' der.", "source": "Sanat Tarihi ve Deyimler", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "'Ateş Pahası' Deyiminin Hikâyesi: Kanuni Sultan Süleyman fırtınalı bir av gününde bir kulübeye sığınır; kulübedeki odun ateşinde ısınıp kurulanınca köylüye borcunu sorar. Köylü 'Bin altın' deyince padişah 'Ateş bu kadar pahalı mı?' der; köylü 'Padişahım, can kurtaran ateş pahalıdır' der.", "source": "Tarihsel Deyim Hikâyeleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "'Eski Çamlar Bardak Oldu' Hikâyesi: Eskiden çam ağaçlarından su bardağı ve testiler oyulurdu; zamanla porselen ve cam yaygınlaşınca eski ahşap bardakların dönemi kapandı ve bu deyim 'devir değişti, eski usuller geride kaldı' manasında kaldı.", "source": "Geleneksel Türk Zanaatları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "'De/Da' Bağlacının Yazımı Pratik Kuralı: Cümleden 'de/da'yı çıkardığınızda cümlenin anlamı tamamen bozulmuyorsa o bir bağlaçtır ve ayrı yazılır; eğer anlam tamamen anlamsızlaşıyorsa bulunma ekidir ve bitişik yazılır.", "source": "TDK Yazım Kılavuzu Kuralı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "'Ki' Bağlacının Yazımı (SOMBAHÇEMİ Formülü): Kalıplaşmış olduğu için bitişik yazılan 'ki'ler: Sanki, Oysaki, Mademki, Belki, Halbuki, Çünkü, Meğerki, İllaki.", "source": "Türkçe Dil Bilgisi Formülleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Düzeltme İşareti (Şapka ^) Kalkmadı!: TDK kurallarına göre anlam karışıklığını önlemek için (kar / kâr, adet / âdet, hala / hâlâ) ve ince 'k, g, l' seslerinden sonra (kâğıt, sükût, ahlâk) düzeltme işareti kullanılmaya devam etmektedir.", "source": "TDK İmla Kuralları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kesme İşaretinin Kurum ve Kuruluş Adlarında Kullanılmaması: 'Türkiye Büyük Millet Meclisine', 'Milli Eğitim Bakanlığına', 'İstanbul Üniversitesine' gibi kurum ve kuruluş adlarına gelen ekler kesme işaretiyle ayrılmaz.", "source": "TDK Noktalama Kılavuzu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Büyük Harflerin Noktası: Türkçede küçük 'i'nin büyüğü noktalı 'İ', küçük 'ı'nın büyüğü ise noktasız 'I'dır. Yazılım ve metinlerde dil kodu olarak her zaman 'tr-TR' seçilmelidir.", "source": "Türk Dili Tipografi Standartları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Türkçenin Matematiksel Yapısı (Sondan Eklemeli Dil): Türkçe, kök ve eklerin kurallı birleşimiyle bilgisayar diline ve yapay zekâ algoritmalarına dünyadaki en yatkın dillerden biridir.", "source": "Dilbilim ve Hesaplamalı Morfoloji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ünlü Uyumu (Büyük ve Küçük Ünlü Uyumu): Bir kelimenin Türk kökenli olup olmadığını anlamanın en güçlü filtresi kalınlık-incelik ve düzlük-yuvarlaklık uyumudur.", "source": "Türkçe Ses Bilgisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Noktalı Virgül (;) Kullanım Sırrı: Bir cümlede noktalı virgül kullanabilmek için cümlenin içinde daha önceden virgülle ayrılmış en az bir öge veya tür bulunması şarttır; yoksa doğrudan nokta konur.", "source": "Noktalama Sanatı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "İki Nokta (:) Sonrası Büyük Harf Kuralı: İki noktadan sonra gelen kısım bağımsız bir cümle ise büyük harfle başlar; sadece örnekler sıralanıyorsa küçük harfle başlar.", "source": "Yazım Kuralları İncelikleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Üç Nokta (...) ile Anlatımı Zenginleştirme: Bitmemiş, yüklemi söylenmemiş cümlelerin sonuna üç nokta konur; bu okuyucunun hayal gücünü ve tefekkürünü metne davet etmektir.", "source": "Edebi Noktalama", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Soru İşaretinin Bilinmeyen Bilgilerde Kullanımı: Parantez içinde kullanılan soru işareti (?) şüphe duyulan veya kesin olmayan bilgileri (Örn: Yunus Emre [1240? - 1320]) belirtmek için kullanılır.", "source": "Akademik Yazım Kuralı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ünlem İşaretinin Parantez İçi Alay Anlamı: Parantez içinde ünlem (!), bir söze alay, kinaye veya küçümseme anlamı kazandırmak için kullanılır.", "source": "Retorik Noktalama", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "'Şey' Sözcüğü Daima Ayrı Yazılır: 'Bir şey', 'her şey', 'hiçbir şey' tamlamalarında 'şey' sözcüğü her zaman ayrı yazılır; çünkü o müstakil bir zamirdir.", "source": "TDK Temel Kuralı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sayıların Yazımı: Metin içinde sayılar kural olarak yazıyla yazılır (Örn: 'üç ay sonra', 'on beş öğrenci'); sadece saat, para tutarı, ölçü ve istatistik verilerinde rakam kullanılır.", "source": "Yazım ve İmla Standartları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sıra Sayılarının Yazımı: Rakamdan sonra nokta konmuşsa ayrıca kesme işareti ve ek yazılmaz (Örn: '2.' veya '2'nci' doğrudur; '2.'nci' hatalıdır).", "source": "TDK Yazım Esasları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Üleştirme Sayıları Rakamla Yazılmaz: Üleştirme sayıları ('ikişer', 'beşer', 'onaltışar') kural olarak rakamla (2'şer değil) harfle yazılmalıdır.", "source": "Türkçe İmla Kuralı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ara Sözlerin Ayrımı: Cümle içindeki ara sözler veya ara cümleler ya iki virgül arasında ya da iki kısa çizgi (--) arasında gösterilir.", "source": "Cümle Bilgisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yabancı Sözcüklere Türkçe Karşılık: 'Selfie' yerine 'Özçekim', 'Online' yerine 'Çevrim içi', 'Link' yerine 'Bağlantı' demek dilimizin bağımsızlığını korumaktır.", "source": "TDK Yabancı Sözlere Karşılıklar", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Atasözleri ve Deyimler Arasındaki Fark: Atasözleri genel bir hayat dersi ve öğüt verir (yargı bildirir); deyimler ise sadece bir durumu veya duyguyu mecazla tasvir eder.", "source": "Halk Edebiyatı ve Anlambilim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kitap Adlarının Tırnak İçi Yazımı: Metin içinde geçen kitap, dergi ve makale adları tırnak içine alınır veya eğik (italik) yazılır.", "source": "Yayın Standartları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Göz Temasının Pedagojik Gücü: Bir öğrenciye ders anlatırken gözlerinin içine 3 saniye odaklanarak konuşmak, onun kendini özel ve değerli hissetmesini sağlar.", "source": "Sözsüz İletişim İlkeleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğretmenin Gülümsemesi: Güler yüzlü bir öğretmenin sınıfındaki öğrencilerin kortizol seviyesi düşük, derse katılım isteği %40 daha fazladır.", "source": "Pozitif Pedagoji Araştırması", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenciyi Arkadaşlarına Örnek Gösterirken Dikkat: 'Bakın o ne kadar çalışkan' demek diğerlerinde kıskançlık doğurur; 'Bu yaklaşım tarzı hepimize ilham verebilir' demek yapıcıdır.", "source": "Sınıf Dinamiği İlkeleri", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sessizliği Bekleme Sabrı: Sınıfın susması için bağırmayın; tahtanın önüne geçip saatine bakarak sakince beklemek öğrencilerin kendi kendini susturmasını sağlar.", "source": "Proaktif Sınıf Yönetimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ödev Tesliminde Esneklik: Kronik olmayan, tek seferlik bir ödev aksamasında öğrenciye ek 24 saat süre vermek sorumluluk bilincini pekiştirir.", "source": "Şefkatli Disiplin", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfın Ortak Şarkısı: Özellikle ilkokul ve ortaokulda derse başlamadan önce söylenen 30 saniyelik neşeli bir sınıf tekerlemesi öğrencilerin enerjisini hizalar.", "source": "Müziksel Pedagoji", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenciye Bir Sır Verir Gibi Anlatmak: 'Şimdi size sınavda herkesin yanıldığı çok önemli bir ipucu vereceğim' diyerek fısıltıya geçmek sınıftaki dikkati bir anda zirveye taşır.", "source": "Dramatik Anlatım Sanatı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Dersin Başındaki 3 Dakika: Dersin ilk 3 dakikasında yoklama almak yerine konuya dair merak uyandırıcı bir soruyla başlamak akademik başarıyı katlar.", "source": "Zamanın Etkili Kullanımı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrencinin Adını Unutmamak: Sene başında 1 hafta içinde tüm öğrencilerin isimlerini ezberleyen öğretmen sınıf yönetiminde %80 avantaj sağlar.", "source": "Bağ Kurma Sanatı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf Kapısındaki Karşılama: Kapıda durup gelen her öğrenciye 'Hoş geldin Ahmet', 'Günaydın Ayşe' demek aidiyeti sabahın ilk saniyesinde başlatır.", "source": "Karşılama Ritüeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrencinin Ailesini Tanımak: Çocuğun evdeki şartlarını, kardeş sayısını ve ilgi alanlarını bilmek ders içi davranışlarını doğru anlamlandırmanın anahtarıdır.", "source": "Bütüncül Rehberlik", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfta 'Hata Panosu': Sınıfın panosuna 'Haftanın En Eğitici Hatası' başlığı açıp oraya yapılan bir hatayı ve ondan öğrenilen dersi asmak hata korkusunu yıkar.", "source": "Büyüme Zihniyeti Pratiği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tahtayı Temiz Bırakma Nezaketi: Ders bittiğinde tahtayı pırıl pırıl silip bir sonraki zümre arkadaşına temiz teslim etmek mesleki zarafetin göstergesidir.", "source": "Meslektaş Dayanışması ve Nezaket", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğretmenin Kendi Öğrenme Heyecanı: Öğretmen yeni bir kitap okuduğunda veya yeni bir bilgi öğrendiğinde heyecanla sınıfla paylaşırsa, çocuklar da öğrenmeye aşık olur.", "source": "Rol Model Olma Felsefesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Her Çocuğun Bir Yıldız Olduğu Gerçeği: Kimi öğrenci gökyüzünde kutup yıldızı gibi hemen parlar; kimi ise derin bir süpernova gibi zamanı gelince ışığını saçar. Sabırla bekleyiniz.", "source": "Maarif Hikmeti", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Beyin Fırtınasında 3-12-3 Tekniği: 3 dakika bireysel düşünme -> 12 dakika grupça fikirleri tahtaya saçma -> 3 dakika en iyi 3 fikri oylama. Zaman sınırlı olduğunda verimi katlar.", "source": "Hızlı İnovasyon Yöntemi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Soru Sormada 'Topu Döndürme' (Bounce): Bir öğrenci cevap verdiğinde öğretmen doğrudan 'Doğru' veya 'Yanlış' dememeli; 'Peki Elif, Mehmet'in bu fikrine katılıyor musun?' diyerek topu sınıfta paslaştırmalıdır.", "source": "Sokratik Tartışma Tekniği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Gözleri Kapatarak Dinleme: Şiir veya edebi metin tahlillerinde öğrencilere gözlerini kapattırıp sadece okunan metnin sesine ve ritmine odaklanmalarını istemek hayal gücünü katlar.", "source": "İşitsel İmgelem", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Akıllı Tahtada 'Günün Kelimesi' Köşesi: Tahtanın sağ üst köşesine her sabah yeni ve az bilinen bir Türkçe kelime ve anlamını yazmak öğrencilerin lügat dağarcığını zenginleştirir.", "source": "Kelime Hazinesi Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Laboratuvar Güvenliğinde 'Önce Tedbir': Fen derslerinde deney yapmadan önce mutlaka önlük, gözlük ve güvenlik kuralları hatırlatılmalı; güvenlik bilinci bilimin ilk adımıdır.", "source": "Laboratuvar Güvenlik Protokolü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenciye Bir 'Çırak' Gibi Bakmak: Öğretmenlik sadece hoca-talebe ilişkisi değil, aynı zamanda köklü bir usta-çırak geleneğidir; işin ahlakı ve adabı yaşayarak aktarılır.", "source": "Ahilik ve Maarif Geleneği", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfta 'Soru Kutusu' Açma: Haftalık olarak öğrencilerin isimsiz merak ettikleri soruları attığı bir kutu açıp Cuma günü cevaplamak çekingen öğrencilerin ufkunu açar.", "source": "Anonim Katılım Modeli", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zor Bir Konuyu 'Tersine Çevirerek' Anlatma: Önce kuralı verip sonra örnek çözmek yerine; önce 3 ilginç örnek gösterip kuralı öğrencilerin kendisinin keşfetmesini sağlayın.", "source": "Tümevarım Yöntemi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıf İçi mini Münazaralarda 1 Dakika Kuralı: Öğrencilere fikirlerini savunurken 60 saniye zaman sınırı koymak, lafı uzatmadan ana fikre odaklanma becerisi kazandırır.", "source": "Kısa ve Öz Hitabet", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Matematikte 'Görselleştirme': Kesirleri tahtadaki sayılarla anlatmak yerine bir elmayı veya pizzayı dilimleyerek somutlaştırmak zihindeki soyut engeli kaldırır.", "source": "Somuttan Soyuta Öğretim", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğretmenin Kendi Zayıflığını Kabul Edebilmesi: Öğrencinin sorduğu zor bir soruya 'Bunu şu an tam bilmiyorum, gelin birlikte araştıralım' demek öğrenciye bilimin sınırlarını ve dürüstlüğü öğretir.", "source": "Akademik Dürüstlük ve Tevazu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Ders Esnasında 'Rol Değişimi': 10 dakikalığına bir öğrenciyi öğretmen kürsüsüne geçirip konunun bir alt başlığını arkadaşlarına anlattırmak liderlik becerisini coşturur.", "source": "Öğrenci Liderliği Metodu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfta 'Teşekkür Duvarı': Bir öğrencinin arkadaşından gördüğü bir yardımı veya nazik davranışı küçük bir karta yazıp astığı duvar, akran zorbalığını kökünden kurutur.", "source": "Nezaket Kültürü İnşası", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Görsel Sanatlarda 'Kusursuzluk Değil İfade': Resim dersinde herkesin aynı vazoyu çizmesini beklemek yerine çocuğun kendi iç dünyasını renklerle yansıtmasını teşvik etmek ruhu besler.", "source": "Sanat Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Müzik Dinletisiyle Derse Giriş: Derse girişte arka planda çalınan 2 dakikalık hafif bir ney, kanun veya klasik müzik ezgisi sınıfın gerginliğini anında süpürür.", "source": "Müzikoterapi ve Konsantrasyon", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Beden Eğitimi ve Karakter Eğitimi: Sporda kazanmaktan çok rakibe saygı duymak, centilmenlik ve yenilgiyi olgunlukla kabul edebilmek erdemli karakterin göstergesidir.", "source": "Spor Ahlakı Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenciye Bir 'Görev Rozeti' Vermek: Haftalık nöbetçi veya kütüphane sorumlusuna yakasına takacağı minik bir kurdele veya rozet vermek sorumluluk ciddiyeti aşılar.", "source": "Görsel Sorumluluk Simgesi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Tarih Dersinde 'Zaman Makinesi': 'Eğer Malazgirt Savaşı'nda Sultan Alparslan'ın yanında bir okçu olsaydın o gün ovada neler hissederdin?' sorusu tarihi canlandırır.", "source": "Tarihsel Canlandırma Metodu", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Coğrafyada 'Harita Okuryazarlığı': Haritadaki renklerin yükseklik basamaklarını (yeşil alçak, kahverengi yüksek) gösterdiğini, bitki örtüsü olmadığını öğrencilere kavratın.", "source": "Temel Harita Bilgisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Felsefede 'Düşünce Deneyleri': 'Trolley Problemi' veya 'Platon'un Mağarası' gibi düşünce deneyleriyle derse başlamak öğrencilerin ahlaki muhakemesini biler.", "source": "Felsefi Düşünce Eğitimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Din Kültüründe 'Evrensel Ahlak Vurgusu': İbadetlerin temel gayesinin güzel ahlak, komşu hakkı, dürüstlük ve kul hakkından sakınmak olduğunu somut hayat olaylarıyla işleyin.", "source": "Ahlak ve İrfan Pedagojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Yabancı Dilde 'Hata Yapma Cesareti': Yabancı dil öğrenirken en büyük engel telaffuzda hata yapma korkusudur; 'Önemli olan konuşabilmek, hata yaptıkça düzeltiriz' rahatlığını verin.", "source": "Dil Edinimi Psikolojisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Rehberlikte 'Gizlilik İlkesi': Bir öğrencinin rehber öğretmene veya sınıf öğretmenine anlattığı özel sırlar (hukuki ve can güvenliği tehdidi hariç) asla başkalarıyla paylaşılmaz.", "source": "Mesleki Etik Kuralları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenciye Soru Sorarken Göz Teması Dağılımı: Soruyu sınıfa sorarken sadece ön sıralara değil, en arka ve köşelerdeki öğrencilerin de gözlerine bakarak tüm sınıfı kapsayın.", "source": "Kapsayıcı Beden Dili", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Zil Çalmadan Önce Masayı Toparlamama Kuralı: Öğrencilerin zil çalmadan 5 dakika önce çantalarını toplayıp fermuar sesi çıkarmasını nazikçe engelleyin; son saniyeye kadar odak korunsun.", "source": "Ders Bitiş Disiplini", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğretmenin Kitap Okurken Görülmesi: Teneffüste veya serbest okuma saatinde öğretmenin de elinde bir kitapla sessizce okuması, bin nasihatten daha tesirli bir örnektir.", "source": "Model Öğretmen Davranışı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfın Isısını Kontrol Etme: 24 derecenin üzerindeki aşırı sıcak sınıflarda uyku hali başlar, 18 derecenin altında ise üşüme dikkat dağıtır; ideal ısı 20-21 derecedir.", "source": "Sınıf Fiziksel Şartları", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrencinin Başarısını Aileye Mesajla Kutlama: Çocuğun güzel bir davranışını akşam veliye kısa bir WhatsApp mesajıyla iletmek aile içi iletişimi ve saygıyı ihya eder.", "source": "Pozitif Veli İletişimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Kendi Öğrenme Çıktısını Test Eden Öğrenci: Dersin sonunda öğrenciye 'Bugün öğrendiğin en önemli kuralı tek bir soruyla bana sor' demek öğrenme çıktısının oturup oturmadığını gösterir.", "source": "Soru Odaklı Ölçme", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfta 'Barışma Çubuğu': İki arkadaş küstüğünde iki ucundan tuttukları barışma çubuğu eşliğinde birbirlerine duygu ve düşüncelerini anlatıp el sıkışması dostluğu pekiştirir.", "source": "Onarıcı Akran İletişimi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğretmenlikte 'Tükenmeyen Ümit': Toprağa atılan her tohum aynı gün başak vermez; bir çocuğun bugün anlamadığı bir öğüt, on yıl sonra bir gün aniden zihninde şimşek gibi çakabilir.", "source": "Maarif İnancı ve Sabır", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğrenciyi Dinlerken Baş Sallama ve Tasdik: Konuşan bir öğrenciye göz temasıyla baş sallayarak 'Seni anlıyorum' mesajı vermek onun kendini ifade etme cesaretini ikiye katlar.", "source": "Aktif Dinleme Becerisi", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sınıfta Her Gün Yeni Bir Başlangıçtır: Dün yaramazlık yapan veya dersi kaynatan bir öğrenciye bugün yeni ve temiz bir sayfa açarak bakmak onun değişebilmesine fırsat tanır.", "source": "Pedagojik Hoşgörü", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Sevginin Açamayacağı Kapı Yoktur: Bilginin kapısı zorla kırılamaz; fakat sevgi ve şefkat anahtarıyla dokunulan her kalp sonuna kadar açılır.", "source": "Öğretmenlik Sanatı", "icon": "💡"}, {"title": "Günün Bilgisi", "text": "Öğretmen Bir Bahçıvandır: Bahçıvan her çiçeğe aynı miktarda su vermez; kaktüse ayrı, güle ayrı, zambak için ayrı bakım gerekir. Her çocuk nev-i şahsına münhasır bir cevherdir.", "source": "Bireyselleştirilmiş Maarif Ruhu", "icon": "💡"}];
window.PIRTIL_POEMS = [{"id": "istiklal_marsi", "title": "İstiklâl Marşı", "poet": "Mehmet Âkif Ersoy", "category": "🇹🇷 Vatan & Bayrak", "stanzas": ["Korkma, sönmez bu şafaklarda yüzen al sancak;\\nSönmeden yurdumun üstünde tüten en son ocak.\\nO benim milletimin yıldızıdır, parlayacak;\\nO benimdir, o benim milletimindir ancak.", "Çatma, kurban olayım, çehreni ey nazlı hilâl!\\nKahraman ırkıma bir gül! Ne bu şiddet, bu celâl?\\nSana olmaz dökülen kanlarımız sonra helâl...\\nHakkıdır, Hakk'a tapan, milletimin istiklâl!", "Ben ezelden beridir hür yaşadım, hür yaşarım.\\nHangi çılgın bana zincir vuracakmış? Şaşarım!\\nKükremiş sel gibiyim, bendimi çiğner, aşarım.\\nYırtarım dağları, enginlere sığmam, taşarım.", "Garbın âfâkını sarmışsa çelik zırhlı duvar,\\nBenim iman dolu göğsüm gibi serhaddim var.\\nUlusun, korkma! Nasıl böyle bir imânı boğar,\\n'Medeniyyet!' dediğin tek dişi kalmış canavar?", "Arkadaş! Yurduma alçakları uğratma, sakın.\\nSiper et gövdeni, dursun bu hayâsızca akın.\\nDoğacaktır sana va'dettiği günler Hakk'ın...\\nKim bilir, belki yarın, belki yarından da yakın.", "Bastığın yerleri 'toprak!' diyerek geçme, tanı:\\nDüşün altındaki binlerce kefensiz yatanı.\\nSen şehit oğlusun, incitme, yazıktır, atanı:\\nVerme, dünyaları alsan da, bu cennet vatanı.", "Kim bu cennet vatanın uğruna olmaz ki fedâ?\\nŞühedâ fışkıracak toprağı sıksan, şühedâ!\\nCânı, cânânı, bütün varımı alsın da Hudâ,\\nEtmesin tek vatanımdan beni dünyada cüdâ.", "Rûhumun senden, İlâhi, şudur ancak emeli:\\nDeğmesin ma'bedimin göğsüne nâmahrem eli.\\nBu ezanlar-ki şehâdetleri dînin temeli,\\nEbedî yurdumun üstünde benim inlemeli.", "O zaman vecd ile bin secde eder -varsa- taşım,\\nHer cerîhamdan, İlâhi, boşanıp kanlı yaşım,\\nFışkırır rûh-ı mücerred gibi yerden na'şım;\\nO zaman yükselerek arşa değer belki başım.", "Dalgalan sen de şafaklar gibi ey şanlı hilâl!\\nOlsun artık dökülen kanlarımın hepsi helâl.\\nEbediyyen sana yok, ırkıma yok izmihlâl:\\nHakkıdır, hür yaşamış, bayrağımın hürriyet;\\nHakkıdır, Hakk'a tapan, milletimin istiklâl!"]}, {"id": "canakkale_sehitlerine", "title": "Çanakkale Şehitlerine", "poet": "Mehmet Âkif Ersoy", "category": "🇹🇷 Vatan & Bayrak", "stanzas": ["Şu Boğaz harbi nedir? Var mı ki dünyâda eşi?\\nEn kesîf orduların yükleniyor dördü beşi,\\n-Tepeden yol bularak geçmek için Marmara’ya-\\nKaç donanmayla sarılmış ufacık bir karaya.", "Ne hayâsızca tahaşşüd ki ufuklar kapalı!\\nNerde-gösterdiği vahşetle 'bu: bir Avrupalı!'\\nDedirir-yırtıcı, hissiz, yalınız küfrün tek dişi,\\nKustu Mehmetçiğin üstüne koca bir cehennemi.", "Bomba şimşekleri beyninden inip her siperin;\\nSönüyor göğsünün üstünde o arslan neferin.\\nÖlüm indirmede gökler, ölü püskürmede yer;\\nO ne müdhiş tipidir: Savrulur enkaaz-ı beşer...", "Kafa, göz, gövde, bacak, kol, çene, parmak, el, ayak,\\nBoşanır sırtlara, vâdîlere, sağnak sağnak.\\nSaçıyor zırha bürünmüş de o nâmerd eller,\\nYıldırım yaylımı tûfanlar, alevden seller.", "Vurulup tertemiz alnından, uzanmış yatıyor,\\nBir hilâl uğruna, yâ Rab, ne güneşler batıyor!\\nEy, bu topraklar için toprağa düşmüş asker!\\nGökten ecdâd inerek öpse o pâk alnı değer.", "Ne büyüksün ki kanın kurtarıyor Tevhîd'i...\\nBedr'in arslanları ancak, bu kadar şanlı idi.\\nSana dar gelmeyecek makberi kimler kazsın?\\n'Gömelim gel seni târîhe' desem, sığmazsın.", "Ey şehîd oğlu şehîd, isteme benden makber,\\nSana âğûşunu açmış duruyor Peygamber."]}, {"id": "sakarya_turkusu", "title": "Sakarya Türküsü", "poet": "Necip Fazıl Kısakürek", "category": "📜 Destan & Tarih", "stanzas": ["İnsan üç beş damla kan, ırmak üç beş damla su;\\nBir hayata çattık ki, hayata kurmuş pusu.\\nGeldi ölümlü yalan, gitti ölümsüz gerçek;\\nSiz, hayat süren leşler, sizi kim diriltecek?\\nHani dağ gibi devler, dağları devirenler?\\nVarmı yeryüzünde bir eser bırakmadan ölenler?", "Kafdağını assalar, belki çeker de bir kıl!\\nBu fersah fersah boşluk, iki dikili taşlık;\\nGökler bile dardır bu cüce dünyaya göre;\\nKim bilir ne dertler saklar şu kara yer?", "Nerede kardeşlerin, cömert Nil, yeşil Tuna?\\nGiden şanlı akıncı, ne zaman döner yurduna?\\nMermerlerin nabzında hâlâ çarpar mı tekbir?\\nBulunmaz mı dünyada akıncılara bir kabir?", "Su iner yokuşlardan, hep basamak basamak;\\nBenimse alın yazım, yokuşlarda susamak.\\nHer şey akar, su, tarih, yıldız, insan ve fikir;\\nOluklar çift; birinden nur akar; birinden kir.", "Akışta demetlenmiş, büyük, küçük, kâinat;\\nŞu çıkan buluta bak, bu inen suya inat!\\nFakat Sakarya başka, yokuş mu meyilli ne?\\nKurşundan bir yük binmiş, köpükten gövdesine;\\nÇatlıyor, yırtınıyor yokuşu sökmek için.\\nHey Sakarya, kim demiş suya vurulmaz perçin?", "Rabbim isterse, sular büklüm büklüm burulur,\\nSırtına Sakaryanın, Türk tarihi vurulur.\\nEyvah, eyvah, Sakaryam, sana mı düştü bu yük?\\nBu dâva hor, bu dâva öksüz, bu dâva büyük!..", "Ne ağır imtihandır, başındaki, Sakarya!\\nBinbir başlı ejderi nasıl yener Sakarya?\\nGeldiler akın akın, her bucaktan, her yandan;\\nGözlerinde kin ve hırs, dillerinde hezeyan!", "Vicdan azabına eş, kayna kayna Sakarya,\\nÖz yurdunda garipsin, öz vatanında parya!\\nİnsanlar nerde kaldı, hani o altın çağlar?\\nYine mi yas bağladı şu dumanlı dağlar?", "Bana kefendir yatak, sana tabuttur havuz;\\nSen kıvrıl, ben gideyim, Son Peygamber kılavuz.\\nYol onun, varlık onun, gerisi hep angarya;\\nYüzüstü çok süründün, ayağa kalk, Sakarya!.."]}, {"id": "bayrak", "title": "Bayrak", "poet": "Arif Nihat Asya", "category": "🇹🇷 Vatan & Bayrak", "stanzas": ["Ey mavi göklerin beyaz ve kızıl süsü,\\nKız kardeşimin gelinliği, şehidimin son örtüsü,\\nIşık ışık, dalga dalga bayrağım!\\nSenin destanını okudum, senin destanını yazacağım.", "Sana benim gözümle bakmayanın\\nMezarını kazacağım.\\nSeni selâmlamadan uçan kuşun\\nYuvasını bozacağım.", "Dalgalandığın yerde ne korku, ne keder...\\nGölgende bana da, bana da yer ver!\\nSabah olmasın, günler doğmasın ne çıkar:\\nYurda ay yıldızının ışığı yeter.", "Savaş bizi karlı dağlara götürdüğü gün\\nKızıllığında ısındık;\\nDağlardan çöllere düştüğümüz gün\\nGölgene sığındık.", "Ey şimdi süzgün, rüzgârlarda dalgalı;\\nBarışın güvercini, savaşın kartalı\\nYüksek yerlerde açan çiçeğim.\\nSenin altında doğdum,\\nSenin altında öleceğim.", "Tarihim, şerefim, şiirim, her şeyim:\\nYer yüzünde yer beğen!\\nNereye dikilmek istersen,\\nSöyle, seni oraya dikeyim!"]}, {"id": "sessiz_gemi", "title": "Sessiz Gemi", "poet": "Yahya Kemal Beyatlı", "category": "🍃 Zaman & Hayat", "stanzas": ["Artık demir almak günü gelmişse zamandan,\\nMeçhule giden bir gemi kalkar bu limandan.\\nHiç yolcusu yokmuş gibi sessizce alır yol;\\nSallanmaz o kalkışta ne mendil, ne de bir kol.", "Rıhtımda kalanlar bu seyahatten elemli,\\nGünlerce siyah ufka bakar gözleri nemli,\\nBiçare gönüller! Ne giden son gemidir bu!\\nHicranlı hayatın ne de son matemidir bu.", "Dünyada sevilmiş ve seven nafile bekler;\\nBilmez ki giden sevgililer dönmeyecekler.\\nBirçok gidenin her biri memnun ki yerinden,\\nBirçok seneler geçti; dönen yok seferinden."]}, {"id": "otuz_bes_yas", "title": "Otuz Beş Yaş Şiiri", "poet": "Cahit Sıtkı Tarancı", "category": "🍃 Zaman & Hayat", "stanzas": ["Yaş otuz beş! yolun yarısı eder.\\nDante gibi ortasındayız ömrün.\\nDelikanlı çağımızdaki cevher,\\nYalvarmak, yakarmak nafile bugün,\\nGözünün yaşına bakmadan gider.", "Şakaklarıma kar mı yağdı ne var?\\nBenim mi Allahım bu çizgili yüz?\\nYa gözler altındaki mor halkalar?\\nNeden böyle düşman görünürsünüz,\\nYıllar yılı dost bildiğim aynalar?", "Zamanla nasıl değişiyor insan!\\nHangi resmime baksam ben değilim.\\nNerde o günler, o şevk, o heyecan?\\nBu güler yüzlü adam ben değilim;\\nYalandır kaygısız olduğum yalan.", "Hayal meyal şeylerden ilk aşkımız;\\nHatırası bile yabancı gelir.\\nHayata beraber başladığımız\\nDostlarla da yollar ayrıldı bir bir;\\nGittikçe artıyor yalnızlığımız.", "Gökyüzünün başka rengi de varmış!\\nGeç farkettim taşın sert olduğunu.\\nSu insanı boğar, ateş yakarmış!\\nHer doğan günün bir dert olduğunu,\\nİnsan bu yaşa gelince anlarmış.", "Ayva sarı nar kırmızı sonbahar!\\nHer yıl biraz daha benimsediğim.\\nNe dönüp duruyor havada kuşlar?\\nNerden çıktı bu cenaze? ölen kim?\\nBu kaçıncı bahçe gördüm tarumar?", "Neylersin ölüm herkesin başında.\\nUyudun uyanamadın olacak.\\nKimbilir nerde, nasıl, kaç yaşında?\\nBir namazlık saltanatın olacak,\\nTaht misali o musalla taşında."]}, {"id": "mona_roza", "title": "Mona Roza", "poet": "Sezai Karakoç", "category": "❤️ Sevgi & Hasret", "stanzas": ["Mona Roza, siyah güller, ak güller;\\nGülce'nin gülleri ve beyaz yatak.\\nKanadı kırık kuş merhamet ister;\\nAh, senin yüzünden kana batacak,\\nMona Roza, siyah güller, ak güller.", "Yağmurdan sonra büyürmüş başak,\\nMeyveler sabırla olgunlaşırmış.\\nBir gün gözlerimin ta içine bak;\\nAnlarsın ölüler niçin yaşarmış,\\nYağmurdan sonra büyürmüş başak.", "Zambaklar en ıssız yerlerde açar,\\nVe vardır her vahşi çiçekte gurur.\\nBir mumun ardında bekleyen rüzgar,\\nIşıksız ruhumu sallar da durur;\\nZambaklar en ıssız yerlerde açar.", "Ellerin, ellerin ve parmakların,\\nBir nar çiçeğini eziyor gibi.\\nBeyaz bir ay doğar fıstıkların ardından,\\nBir kadın kederle gülümsüyor gibi;\\nEllerin, ellerin ve parmakların.", "Kırgın kırgın bakma yüzüme Roza,\\nHenüz dinlemedin benden türküler.\\nBenim de söyleyecek sözüm var sana,\\nRuhumu ateşe salan bu yerler;\\nMona Roza, siyah güller, ak güller."]}, {"id": "ben_sana_mecburum", "title": "Ben Sana Mecburum", "poet": "Attila İlhan", "category": "❤️ Sevgi & Hasret", "stanzas": ["Ben sana mecburum bilemezsin\\nAdını mıh gibi aklımda tutuyorum\\nBüyüdükçe büyüyor gözlerin\\nBen sana mecburum bilemezsin\\nİçimi seninle ısıtıyorum.", "Ağaçlar sonbahara hazırlanıyor\\nBu şehir o eski İstanbul mudur\\nKaranlıkta bulutlar parçalanıyor\\nSokak lambaları birden yanıyor\\nKaldırımlarda yağmur kokusu\\nBen sana mecburum sen yoksun.", "Sevmek kimi zaman rezilce korkudur\\nİnsan bir akşamüstü ansızın yorulur\\nTutsak ustura ağzında yaşamaktan\\nKimi zaman ellerini kırar tutkusu\\nBirkaç hayat çıkarır yaşamasından\\nHangi kapıyı çalsa kimi zaman\\nArkasında yalnızlığın hınzır uğultusu.", "Fatih'te yoksul bir gramofon çalıyor\\nEski zamanlardan bir cuma çalıyor\\nDurup köşe başında dinlesem\\nSana seslensem duyar mısın\\nBen sana mecburum bilemezsin\\nİçimi seninle ısıtıyorum."]}, {"id": "istanbulu_dinliyorum", "title": "İstanbul'u Dinliyorum", "poet": "Orhan Veli Kanık", "category": "🍃 Zaman & Hayat", "stanzas": ["İstanbul'u dinliyorum, gözlerim kapalı;\\nÖnce hafiften bir rüzgar esiyor;\\nYavaş yavaş sallanıyor\\nYapraklar ağaçlarda;\\nUzaklarda, çok uzaklarda,\\nSucuların hiç durmayan çıngırakları;\\nİstanbul'u dinliyorum, gözlerim kapalı.", "İstanbul'u dinliyorum, gözlerim kapalı;\\nKuşlar geçiyor, derken;\\nYükseklerden, sürü sürü, çığlık çığlık.\\nAğlar çekiliyor dalyanlarda;\\nBir kadının suya değiyor ayakları;\\nİstanbul'u dinliyorum, gözlerim kapalı.", "İstanbul'u dinliyorum, gözlerim kapalı;\\nSerin serin Kapalıçarşı,\\nCıvıl cıvıl Mahmutpaşa,\\nGüvercin dolu avlular.\\nÇekiç sesleri geliyor doklardan,\\nGüzelim bahar rüzgarında ter kokuları;\\nİstanbul'u dinliyorum, gözlerim kapalı.", "İstanbul'u dinliyorum, gözlerim kapalı;\\nBaşımda eski alemlerin sarhoşluğu,\\nLoş kayıkhaneleriyle bir yalı;\\nDinmiş uğultusu kürek çekişlerin;\\nİstanbul'u dinliyorum, gözlerim kapalı.", "İstanbul'u dinliyorum, gözlerim kapalı;\\nBir yosma geçiyor kaldırımdan;\\nKüfürler, şarkılar, türküler, laf atmalar.\\nBir şey düşüyor elinden yere;\\nBir gül olmalı;\\nİstanbul'u dinliyorum, gözlerim kapalı.", "İstanbul'u dinliyorum, gözlerim kapalı;\\nBir kuş çırpınıyor eteklerinde;\\nAlnın sıcak mı, değil mi, biliyorum;\\nDudakların ıslak mı, değil mi, biliyorum;\\nBeyaz bir ay doğuyor fıstıkların arkasından,\\nKalbinin vuruşundan anlıyorum;\\nİstanbul'u dinliyorum."]}, {"id": "ilim_ilim_bilmektir", "title": "İlim İlim Bilmektir", "poet": "Yunus Emre", "category": "🕊️ Hikmet & Tefekkür", "stanzas": ["İlim ilim bilmektir,\\nİlim kendin bilmektir.\\nSen kendini bilmezsin,\\nYa nice okumaktır?", "Okumaktan mâni ne?\\nKişi Hakk'ı bilmektir.\\nÇün okudun, bilmezsin,\\nHa bir kuru emektir.", "Okudum bildim deme,\\nÇok taat kıldım deme.\\nErişemezsin menzile,\\nGönül kırmışsan eğer.", "Dört kitabın ma'nisi,\\nBellidir bir elifte.\\nSen elifi bilmezsin,\\nBu nice okumaktır?", "Yunus Emre der hoca,\\nGerekse bin var hacca.\\nHepsinden iyice,\\nBir gönüle girmektir."]}, {"id": "uzun_ince_bir_yoldayim", "title": "Uzun İnce Bir Yoldayım", "poet": "Âşık Veysel", "category": "🕊️ Hikmet & Tefekkür", "stanzas": ["Uzun ince bir yoldayım,\\nGidiyorum gündüz gece.\\nBilmiyorum ne hâldeyim,\\nGidiyorum gündüz gece.", "Dünyaya geldiğim anda,\\nYürüdüm aynı zamanda.\\nİki kapılı bir handa,\\nGidiyorum gündüz gece.", "Uykuda dahi yürüyom,\\nKalkıp yerime bakıyom.\\nGündüz hayal, gece rüyam,\\nGidiyorum gündüz gece.", "Kırk dokuz yıl bu yollarda,\\nOvada, dağda, çöllerde.\\nDüşmüşüm gurbet ellerde,\\nGidiyorum gündüz gece.", "Düşünülürse derince,\\nIrak görünür görünce.\\nYol bir dakka miktarınca,\\nGidiyorum gündüz gece.", "Şaşar Veysel işbu hâle,\\nGâh ağlaya gâhi güle.\\nYetişmek için menzile,\\nGidiyorum gündüz gece."]}, {"id": "bursada_zaman", "title": "Bursa'da Zaman", "poet": "Ahmet Hamdi Tanpınar", "category": "📜 Destan & Tarih", "stanzas": ["Bursa'da bir eski cami avlusu,\\nKüçük şadırvanda şakırdayan su;\\nOrhan zamanından kalma bir duvar...\\nOnunla bir yaşta ihtiyar çınar\\nEliyor dört yana sakin bir günü.", "Bir zafer müjdesi burda her isim:\\nSanki tek bir anda gün, saat, mevsim\\nYaşıyor sihrini geçmiş zamanın\\nHâlâ bu taşlarda gülen rüyanın.", "Güvercin bakışlı sessizlik bile\\nÇınlıyor bir sonsuz hatıra ile;\\nGümüşlü bir fecrin zafer aynası,\\nMuradiye sabrın acı meyvası,\\nÖmrünün derdine gülen Cem'lerin.", "Ne içindeyim zamanın,\\nNe de büsbütün dışında;\\nYekpâre, geniş bir ânın\\nParçalanmaz akışında."]}, {"id": "mihriban", "title": "Mihriban", "poet": "Abdurrahim Karakoç", "category": "❤️ Sevgi & Hasret", "stanzas": ["Sarı saçlarına deli gönlümü\\nBağlamışlar, çözülmüyor Mihriban!\\nAyrılıktan zor belleme ölümü\\nGörmeyince sezilmiyor Mihriban!", "Yâr, deyince kalem elden düşüyor\\nGözlerim görmüyor, aklım şaşıyor\\nLâmbada titreyen alev üşüyor\\nAşk kâğıda yazılmıyor Mihriban!", "Önce naz sonra söz ve sonra hile\\nSevilen seveni düşürür dile\\nSeneler asırlar değişse bile\\nEski töre bozulmuyor Mihriban!", "Tabiplerde ilâç yoktur yarama\\nAşk deyince ötesini arama\\nHer nesnenin bir bitimi var ama\\nAşka hudut çizilmiyor Mihriban!", "Boşa bağlanmamış bülbül gülüne\\nKar koysan köz olur aşkın külüne\\nŞaştım kara bahtın tahammülüne\\nTaşa çalsam ezilmiyor Mihriban!", "Tarife sığmıyor aşkın anlamı\\nAncak çeken bilir bu dert gamı\\nBir gerçek var ki dünyada tamamı\\nKader kısmet bozulmuyor Mihriban!"]}, {"id": "etme", "title": "Etme", "poet": "Mevlânâ Celâleddîn-i Rûmî", "category": "🕊️ Hikmet & Tefekkür", "stanzas": ["Duydum ki bizi bırakmaya azmediyorsun, etme.\\nBaşka bir yâr, başka bir dosta meylediyorsun, etme.\\nSen yadeller dünyasında ne arıyorsun yabancı?\\nHangi hasta gönüllüyü kastediyorsun, etme.", "Biz dudak ucuyla gülmüyoruz ki gözlerimiz gülsün,\\nSen bizim tebessümümüzü hüzne çeviriyorsun, etme.\\nEy ay yüzlü, ey parlak gökyüzü, ey nurlu sabah,\\nBizi karanlık gecelerde bırakıp gidiyorsun, etme.", "Harama bulaşmış gözlerle bakma bize,\\nBizim gözümüz sendeki nura hayrandır, etme.\\nAşk yolunda can veren aşıkları terk edip,\\nBizi hasretin çöllerinde viran ediyorsun, etme."]}, {"id": "yagmur", "title": "Yağmur", "poet": "Nurullah Genç", "category": "🕊️ Hikmet & Tefekkür", "stanzas": ["Yağmur, seni bekleyen bir taş da ben olsaydım,\\nÇölde seni arayan bir serap da ben olsaydım.\\nDokunduğun her zerre nura boyanır senin,\\nO nura susayan bir toprak da ben olsaydım.", "Gelişin bir bahardır, solgun gülleri güldürür,\\nBir tebessümün bin yıllık kederleri öldürür.\\nYağmur, bırak aksın sineme merhametin,\\nGönlümü aşkının ateşiyle söndürür.", "Kuşlar senin adınla kanat çırpar semaya,\\nYıldızlar secde eder getirdiğin hüdaya.\\nSensiz geçen ömrün ne manası var ey sevgili,\\nRahmetinle can ver bu solmuş dünyaya."]}];
